package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.config.ConfigWrites.Write;
import com.ghordrin.bosshealthbar.gamebars.NativeBossBarMode;
import com.ghordrin.bosshealthbar.render.BarFonts;
import com.ghordrin.bosshealthbar.render.BarIconPlacement;
import com.google.common.collect.ImmutableList;
import java.awt.Font;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.FontType;

@Singleton
public class ConfigMigrations
{
	// The checkbox nativeBossBarMode replaced. Its saved value is moved over on startup.
	static final String OLD_REPLACE_NATIVE_BOSS_BAR_KEY = "replaceNativeBossBar";
	// Remembered what Match boss colors was before the Oldschool theme turned it off. The two now work together,
	// so the key is dropped. Its value isn't restored, which leaves the look unchanged.
	static final String OLD_SAVED_MATCH_BOSS_COLORS_KEY = "oldschoolSavedMatchBossColors";
	// The checkbox iconPlacement replaced. It read as where the icon goes rather than whether it shows, so its
	// saved value is moved over together with Use boss icon, which stays on as the icon's source.
	static final String OLD_SHOW_ICONS_KEY = "showIcons";
	// Set once the old default font has been checked for a switch to the new one. Not a config item, so Reset keeps it.
	static final String FONT_DEFAULT_MIGRATED_KEY = "fontDefaultMigrated";
	// Set once a RuneScape font's saved size has been put back to its native size. Not a config item either.
	static final String PIXEL_FONT_SIZE_MIGRATED_KEY = "pixelFontSizeMigrated";
	// Set once the item fonts have been given the look they had with the name's font. Not a config item either.
	static final String ITEM_FONTS_MIGRATED_KEY = "itemFontsMigrated";
	// Set once the fight timer font has been given the kill count's font. Not a config item either.
	static final String FIGHT_TIMER_FONT_MIGRATED_KEY = "fightTimerFontMigrated";

	private static final int OLD_DEFAULT_FONT_SIZE = 17;
	static final List<String> SMALL_TEXT_FONT_KEYS = ImmutableList.of(
		BossHealthBarConfig.COMBAT_LEVEL_FONT_KEY,
		BossHealthBarConfig.HITPOINTS_FONT_KEY,
		BossHealthBarConfig.KILL_COUNT_FONT_KEY,
		BossHealthBarConfig.PARTY_DEFENCE_FONT_KEY,
		BossHealthBarConfig.SPECIAL_ATTACK_COUNTS_FONT_KEY,
		BossHealthBarConfig.WEAKNESS_FONT_KEY,
		BossHealthBarConfig.DRAIN_CAP_FONT_KEY);

	private final ConfigManager configManager;

	@Inject
	ConfigMigrations(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public void migrate()
	{
		migrateReplaceNativeBossBar();
		migrateShowIcons();
		apply(savedMatchBossColorsWrites(
			configManager.getConfiguration(BossHealthBarConfig.GROUP, OLD_SAVED_MATCH_BOSS_COLORS_KEY)));
		migrateFont(FONT_DEFAULT_MIGRATED_KEY, BossHealthBarConfig.FONT_KEY, ConfigMigrations::defaultFontWrites);
		migrateFont(PIXEL_FONT_SIZE_MIGRATED_KEY, BossHealthBarConfig.FONT_KEY, ConfigMigrations::pixelFontSizeWrites);
		migrateFont(ITEM_FONTS_MIGRATED_KEY, BossHealthBarConfig.FONT_KEY, ConfigMigrations::itemFontWrites);
		migrateFont(FIGHT_TIMER_FONT_MIGRATED_KEY, BossHealthBarConfig.KILL_COUNT_FONT_KEY,
			ConfigMigrations::fightTimerFontWrites);
	}

	private void migrateReplaceNativeBossBar()
	{
		final String oldSaved = configManager.getConfiguration(BossHealthBarConfig.GROUP, OLD_REPLACE_NATIVE_BOSS_BAR_KEY);
		if (oldSaved == null)
		{
			return;
		}

		apply(replaceNativeBossBarWrites(oldSaved,
			configManager.getConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.NATIVE_BOSS_BAR_MODE_KEY)));
	}

	private void migrateShowIcons()
	{
		final String oldSaved = configManager.getConfiguration(BossHealthBarConfig.GROUP, OLD_SHOW_ICONS_KEY);
		if (oldSaved == null)
		{
			return;
		}

		apply(showIconsWrites(oldSaved,
			ConfigWrites.savedBoolean(configManager, BossHealthBarConfig.USE_BOSS_ICON_KEY),
			configManager.getConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.ICON_PLACEMENT_KEY)));
	}

	private void migrateFont(String migratedKey, String fontKey, Function<FontType, List<Write>> writes)
	{
		if (ConfigWrites.savedBoolean(configManager, migratedKey) != null)
		{
			return;
		}

		apply(writes.apply(configManager.getConfiguration(BossHealthBarConfig.GROUP, fontKey, FontType.class)));
	}

	private void apply(List<Write> writes)
	{
		for (Write write : writes)
		{
			ConfigWrites.write(configManager, write.getKey(), write.getValue());
		}
	}

	static List<Write> replaceNativeBossBarWrites(String oldSaved, String savedMode)
	{
		final List<Write> writes = new ArrayList<>();
		final NativeBossBarMode mode = nativeBossBarMode(oldSaved, savedMode);
		if (mode != null)
		{
			writes.add(new Write(BossHealthBarConfig.NATIVE_BOSS_BAR_MODE_KEY, mode));
		}
		writes.add(new Write(OLD_REPLACE_NATIVE_BOSS_BAR_KEY, null));
		return writes;
	}

	static List<Write> showIconsWrites(String oldSaved, Boolean savedUseBossIcon, String savedPlacement)
	{
		final List<Write> writes = new ArrayList<>();
		final BarIconPlacement placement = iconPlacement(oldSaved, savedUseBossIcon, savedPlacement);
		if (placement != null)
		{
			writes.add(new Write(BossHealthBarConfig.ICON_PLACEMENT_KEY, placement));
			// With no icon shown, the old Use boss icon was never a choice of source, so it goes back to its default.
			if (placement == BarIconPlacement.NONE)
			{
				writes.add(new Write(BossHealthBarConfig.USE_BOSS_ICON_KEY, true));
			}
		}
		writes.add(new Write(OLD_SHOW_ICONS_KEY, null));
		return writes;
	}

	// The old pair: Show icons on put the icon in the crests, and off moved it before the name, where Use boss
	// icon doubled as whether it showed at all. RuneLite saves the default before the plugin starts, so a saved
	// Crests may not be the user's choice.
	static BarIconPlacement iconPlacement(String oldSaved, Boolean savedUseBossIcon, String savedPlacement)
	{
		if (oldSaved == null
			|| (savedPlacement != null && !BarIconPlacement.CRESTS.name().equals(savedPlacement)))
		{
			return null;
		}
		if (Boolean.parseBoolean(oldSaved))
		{
			return BarIconPlacement.CRESTS;
		}
		return savedUseBossIcon == null || savedUseBossIcon ? BarIconPlacement.BEFORE_NAME : BarIconPlacement.NONE;
	}

	static List<Write> savedMatchBossColorsWrites(String saved)
	{
		return saved == null
			? Collections.emptyList()
			: Collections.singletonList(new Write(OLD_SAVED_MATCH_BOSS_COLORS_KEY, null));
	}

	// The old "Replace game's boss health bar" checkbox: on replaced the game's bar, off hid ours.
	static NativeBossBarMode fromReplaceSetting(String saved)
	{
		if (saved == null)
		{
			return null;
		}
		return Boolean.parseBoolean(saved) ? NativeBossBarMode.REPLACE : NativeBossBarMode.HIDE_OURS;
	}

	// RuneLite saves the default before the plugin starts, so a saved REPLACE may not be the user's choice.
	static NativeBossBarMode nativeBossBarMode(String oldSaved, String currentSaved)
	{
		final NativeBossBarMode old = fromReplaceSetting(oldSaved);
		if (old == null || (currentSaved != null && !NativeBossBarMode.REPLACE.name().equals(currentSaved)))
		{
			return null;
		}
		return old;
	}

	static List<Write> defaultFontWrites(FontType saved)
	{
		final List<Write> writes = new ArrayList<>();
		if (isOldDefaultFont(saved))
		{
			writes.add(new Write(BossHealthBarConfig.FONT_KEY, FontType.REGULAR));
		}
		writes.add(new Write(FONT_DEFAULT_MIGRATED_KEY, true));
		return writes;
	}

	static List<Write> pixelFontSizeWrites(FontType saved)
	{
		final List<Write> writes = new ArrayList<>();
		final FontType migrated = withNativePixelSize(saved);
		if (migrated != null)
		{
			writes.add(new Write(BossHealthBarConfig.FONT_KEY, migrated));
		}
		writes.add(new Write(PIXEL_FONT_SIZE_MIGRATED_KEY, true));
		return writes;
	}

	// The item fonts are new, so their saved values are only the defaults and can be overwritten. The damage
	// number always used the name's font, whatever it was. The smaller text only needs a change for other
	// fonts, since the RuneScape defaults already match.
	static List<Write> itemFontWrites(FontType name)
	{
		final List<Write> writes = new ArrayList<>();
		if (name != null)
		{
			writes.add(new Write(BossHealthBarConfig.DAMAGE_NUMBER_FONT_KEY, name));
			final FontType small = smallTextFont(name);
			if (small != null)
			{
				for (String key : SMALL_TEXT_FONT_KEYS)
				{
					writes.add(new Write(key, small));
				}
			}
		}
		writes.add(new Write(ITEM_FONTS_MIGRATED_KEY, true));
		return writes;
	}

	// Newer than the item fonts, so it gets its own one-time copy of the kill count font, which that migration set.
	static List<Write> fightTimerFontWrites(FontType killCount)
	{
		final List<Write> writes = new ArrayList<>();
		if (killCount != null)
		{
			writes.add(new Write(BossHealthBarConfig.FIGHT_TIMER_FONT_KEY, killCount));
		}
		writes.add(new Write(FIGHT_TIMER_FONT_MIGRATED_KEY, true));
		return writes;
	}

	// The default before the RuneScape font. RuneLite saves defaults before the plugin starts, so
	// everyone who never changed the font has this saved.
	static boolean isOldDefaultFont(FontType font)
	{
		return font != null
			&& Font.SERIF.equals(font.getFamily())
			&& font.getSize() == OLD_DEFAULT_FONT_SIZE
			&& !font.isBold()
			&& !font.isItalic();
	}

	// The RuneScape fonts used to ignore the saved size, and the font picker keeps the old size when the
	// family changes, so a saved size other than the native one was never seen. Returns null to keep the font.
	static FontType withNativePixelSize(FontType font)
	{
		if (font == null || font.getFamily() == null)
		{
			return null;
		}
		for (FontType pixel : new FontType[]{FontType.REGULAR, FontType.SMALL})
		{
			if (pixel.getFamily().equals(font.getFamily()))
			{
				return font.getSize() == pixel.getSize() ? null : font.withSize(pixel.getSize());
			}
		}
		return null;
	}

	// Before each item had its own font, other fonts drew the smaller text in the name's family at a smaller
	// size, italic like the name but never bold. Returns null for the RuneScape fonts, whose defaults already match.
	public static FontType smallTextFont(FontType name)
	{
		if (name == null || name.getFamily() == null || BarFonts.isRunescapeFont(name.getFamily()))
		{
			return null;
		}
		return new FontType()
			.withFamily(name.getFamily())
			.withSize(BarFonts.smallTextSize(name.getSize()))
			.withItalic(name.isItalic());
	}
}

package com.ghordrin.bosshealthbar.config;

import lombok.Value;
import net.runelite.client.config.ConfigManager;

public final class ConfigWrites
{
	// A null value means unset the key.
	@Value
	static class Write
	{
		String key;
		Object value;
	}

	private ConfigWrites()
	{
	}

	public static void write(ConfigManager configManager, String key, Object value)
	{
		write(configManager, BossHealthBarConfig.GROUP, key, value);
	}

	public static void write(ConfigManager configManager, String group, String key, Object value)
	{
		if (value == null)
		{
			configManager.unsetConfiguration(group, key);
		}
		else
		{
			configManager.setConfiguration(group, key, value);
		}
	}

	static Boolean savedBoolean(ConfigManager configManager, String key)
	{
		final String saved = configManager.getConfiguration(BossHealthBarConfig.GROUP, key);
		return saved != null ? Boolean.valueOf(saved) : null;
	}
}

package com.ghordrin.bosshealthbar.config;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ButtonGroup;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.JToggleButton;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.border.Border;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.http.api.item.ItemPrice;

// The window behind "Choose custom icon". Items are searched by name, sprites are browsed, and whichever is
// picked is the one the Custom theme shows.
class CustomIconPickerDialog extends JDialog
{
	private static final int THUMB_SIZE = 48;
	private static final int COLUMNS = 6;
	// A pass runs once per game cycle, so the whole range costs its size divided by this many cycles. Fifty
	// at a time left the window loading for over a minute; this reads it in a few.
	private static final int SPRITES_PER_PASS = 500;
	// Sprite ids run well past the icons; this covers the ones the game has without probing forever.
	private static final int MAX_SPRITE_ID = 6000;
	// An icon is small. Anything larger is interface furniture, which would swamp the grid and the memory
	// it takes to hold it, and would be drawn far too small on a bar anyway.
	private static final int MAX_SPRITE_SIZE = 64;
	private static final int MIN_SPRITE_SIZE = 6;
	private static final int MAX_ITEM_RESULTS = 120;
	private static final Border SELECTED_BORDER = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE, 2);
	private static final Border HOVER_BORDER = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 2);
	private static final Border IDLE_BORDER = BorderFactory.createEmptyBorder(2, 2, 2, 2);

	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	private final JPanel resultsPanel = new JPanel(new GridLayout(0, COLUMNS, 4, 4));
	private final JLabel statusLabel = new JLabel();
	private final JTextField searchField = new JTextField();
	private final JToggleButton itemsButton = new JToggleButton("Items", true);
	private final JToggleButton spritesButton = new JToggleButton("Sprites");

	// The sprites found by the last browse, kept so typing filters them without probing the game again.
	private final List<Integer> spriteIds = new ArrayList<>();
	private final List<BufferedImage> spriteImages = new ArrayList<>();

	private JButton selectedButton;
	private volatile int loadGeneration;

	CustomIconPickerDialog(Client client, ClientThread clientThread, ConfigManager configManager,
		BossHealthBarConfig config, ItemManager itemManager, SpriteManager spriteManager)
	{
		super(SwingUtilities.getWindowAncestor(client.getCanvas()), "Choose custom icon");
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;

		setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

		final JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setContentPane(content);

		final ButtonGroup sources = new ButtonGroup();
		sources.add(itemsButton);
		sources.add(spritesButton);
		itemsButton.setFocusable(false);
		spritesButton.setFocusable(false);
		itemsButton.setToolTipText("Search the game's items by name");
		spritesButton.setToolTipText("Browse the game's sprites, such as clan ranks and skill icons");
		itemsButton.addActionListener(e -> sourceChanged());
		spritesButton.addActionListener(e -> sourceChanged());

		final JButton none = new JButton("None");
		none.setToolTipText("Go back to no custom icon");
		none.setFocusable(false);
		none.addActionListener(e -> selectNone());

		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		buttons.setOpaque(false);
		buttons.add(itemsButton);
		buttons.add(spritesButton);
		buttons.add(none);

		searchField.setToolTipText("Part of an item's name, or part of a sprite's number");
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				searchChanged();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				searchChanged();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				searchChanged();
			}
		});

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());

		final JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		header.add(buttons, BorderLayout.NORTH);
		header.add(searchField, BorderLayout.CENTER);
		header.add(statusLabel, BorderLayout.SOUTH);

		// Keeps the grid at its own size in the top left, instead of stretching it over the whole view.
		final JPanel resultsHolder = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		resultsHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resultsPanel.setOpaque(false);
		resultsHolder.add(resultsPanel);
		final JScrollPane scrollPane = new JScrollPane(resultsHolder);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		content.add(header, BorderLayout.NORTH);
		content.add(scrollPane, BorderLayout.CENTER);

		setSize(400, 460);
		setResizable(false);
		setLocationRelativeTo(getOwner());

		showItems();
	}

	private boolean showingItems()
	{
		return itemsButton.isSelected();
	}

	private void sourceChanged()
	{
		searchField.setText("");
		if (showingItems())
		{
			showItems();
		}
		else if (spriteIds.isEmpty())
		{
			loadSprites();
		}
		else
		{
			showSprites();
		}
	}

	private void searchChanged()
	{
		if (showingItems())
		{
			showItems();
		}
		else
		{
			showSprites();
		}
	}


	private void showItems()
	{
		final String query = searchField.getText().trim();
		if (query.isEmpty())
		{
			clear();
			statusLabel.setText("Type part of an item's name");
			return;
		}

		final List<ItemPrice> found = itemManager.search(query);
		clear();
		if (found.isEmpty())
		{
			statusLabel.setText("No item matches \"" + query + "\"");
			return;
		}

		final int shown = Math.min(found.size(), MAX_ITEM_RESULTS);
		final int currentId = config.customIconSpriteId() < 0 ? config.customIconItemId() : -1;
		for (int i = 0; i < shown; i++)
		{
			final ItemPrice item = found.get(i);
			final JButton button = buildButton(item.getName(), () -> selectItem(item.getId()));
			itemManager.getImage(item.getId()).addTo(button);
			if (item.getId() == currentId)
			{
				markSelected(button);
			}
			resultsPanel.add(button);
		}

		statusLabel.setText(shown < found.size() ? "First " + shown + " of " + found.size() + " items"
			: shown + (shown == 1 ? " item" : " items"));
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	// Sprite ids aren't listed anywhere, so they are read one by one. Decoded in batches over several frames
	// so opening the window doesn't stall the game, and a newer load makes an older one stop.
	private void loadSprites()
	{
		clear();
		statusLabel.setText("Loading sprites...");
		spriteIds.clear();
		spriteImages.clear();
		final int generation = ++loadGeneration;
		final int[] nextId = {0};

		clientThread.invoke(() ->
		{
			if (generation != loadGeneration)
			{
				return true;
			}

			final List<Integer> ids = new ArrayList<>();
			final List<BufferedImage> images = new ArrayList<>();
			final int end = Math.min(MAX_SPRITE_ID, nextId[0] + SPRITES_PER_PASS);
			for (int id = nextId[0]; id < end; id++)
			{
				final BufferedImage sprite = sprite(id);
				if (sprite == null || sprite.getWidth() > MAX_SPRITE_SIZE || sprite.getHeight() > MAX_SPRITE_SIZE
					|| sprite.getWidth() < MIN_SPRITE_SIZE || sprite.getHeight() < MIN_SPRITE_SIZE)
				{
					continue;
				}
				ids.add(id);
				images.add(sprite);
			}
			nextId[0] = end;
			final boolean done = end >= MAX_SPRITE_ID;

			// Each pass is shown as it lands, so the grid fills in rather than the window sitting on
			// "Loading sprites..." until the last id has been read.
			SwingUtilities.invokeLater(() ->
			{
				if (generation != loadGeneration)
				{
					return;
				}
				spriteIds.addAll(ids);
				spriteImages.addAll(images);
				showSprites();
				if (!done)
				{
					statusLabel.setText("Loading sprites... " + spriteIds.size() + " so far");
				}
			});
			return done;
		});
	}

	// Not every id is a sprite the game can hand over: some archives hold nothing, and reading one throws
	// rather than answering with nothing. Left to itself that ends the whole sweep, since the client drops a
	// task that threw, and the window would sit on "Loading sprites..." for good.
	private BufferedImage sprite(int id)
	{
		try
		{
			return spriteManager.getSprite(id, 0);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private void showSprites()
	{
		final String query = searchField.getText().trim();
		clear();
		if (spriteIds.isEmpty())
		{
			statusLabel.setText("No sprites loaded, log in and reopen this window");
			return;
		}

		final int currentId = config.customIconSpriteId();
		int shown = 0;
		for (int i = 0; i < spriteIds.size(); i++)
		{
			final int id = spriteIds.get(i);
			if (!query.isEmpty() && !String.valueOf(id).contains(query))
			{
				continue;
			}
			final JButton button = buildButton("Sprite " + id, () -> selectSprite(id));
			button.setIcon(new ImageIcon(spriteImages.get(i)));
			if (id == currentId)
			{
				markSelected(button);
			}
			resultsPanel.add(button);
			shown++;
		}

		statusLabel.setText(shown == 0 ? "No sprite number has \"" + query + "\" in it"
			: shown + (shown == 1 ? " sprite" : " sprites"));
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	private void clear()
	{
		resultsPanel.removeAll();
		selectedButton = null;
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	private JButton buildButton(String tooltip, Runnable onPick)
	{
		final JButton button = new JButton();
		button.setToolTipText(tooltip);
		button.setPreferredSize(new Dimension(THUMB_SIZE + 4, THUMB_SIZE + 4));
		button.setBorder(IDLE_BORDER);
		button.setContentAreaFilled(false);
		button.setFocusable(false);
		button.addActionListener(e ->
		{
			markSelected(button);
			onPick.run();
		});
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(HOVER_BORDER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(IDLE_BORDER);
				}
			}
		});
		return button;
	}

	private void markSelected(JButton button)
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
		}
		selectedButton = button;
		button.setBorder(SELECTED_BORDER);
	}

	private void selectItem(int itemId)
	{
		write(CustomIcon.ITEM, itemId);
	}

	private void selectSprite(int spriteId)
	{
		write(CustomIcon.SPRITE, spriteId);
	}

	private void selectNone()
	{
		write(CustomIcon.NONE, -1);
		clear();
		if (showingItems())
		{
			statusLabel.setText("Type part of an item's name");
		}
		else
		{
			showSprites();
		}
	}

	// Only one of the two is ever set, so what the bar shows is what was just picked.
	private void write(CustomIcon kind, int id)
	{
		ConfigWrites.write(configManager, BossHealthBarConfig.CUSTOM_ICON_ITEM_ID_KEY,
			kind == CustomIcon.ITEM ? id : -1);
		ConfigWrites.write(configManager, BossHealthBarConfig.CUSTOM_ICON_SPRITE_ID_KEY,
			kind == CustomIcon.SPRITE ? id : -1);
	}

	private enum CustomIcon
	{
		NONE,
		ITEM,
		SPRITE
	}
}

package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.render.BarPainter;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.border.Border;
import net.runelite.api.Client;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

class FillTexturePickerDialog extends JDialog
{
	private static final int THUMB_SIZE = 48;
	private static final int COLUMNS = 6;
	private static final int TEXTURES_PER_FRAME = 50;
	private static final Border SELECTED_BORDER = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE, 2);
	private static final Border HOVER_BORDER = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 2);
	private static final Border IDLE_BORDER = BorderFactory.createEmptyBorder(2, 2, 2, 2);

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final JPanel resultsPanel = new JPanel(new GridLayout(0, COLUMNS, 4, 4));
	private final JLabel statusLabel = new JLabel();

	private JButton selectedButton;
	private volatile int loadGeneration;

	FillTexturePickerDialog(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config)
	{
		super(SwingUtilities.getWindowAncestor(client.getCanvas()), "Choose fill texture");
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;

		setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

		final JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setContentPane(content);

		final JButton none = new JButton("None");
		none.setToolTipText("Go back to the plain fill");
		none.setFocusable(false);
		none.addActionListener(e -> selectNone());

		final JButton refresh = new JButton("Refresh");
		refresh.setToolTipText("Read the game's textures again");
		refresh.setFocusable(false);
		refresh.addActionListener(e -> loadTextures());

		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		buttons.setOpaque(false);
		buttons.add(none);
		buttons.add(refresh);

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());

		final JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		header.add(buttons, BorderLayout.NORTH);
		header.add(statusLabel, BorderLayout.SOUTH);

		// Keeps the grid at its own size in the top left, instead of stretching it over the whole view.
		final JPanel resultsHolder = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		resultsHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resultsPanel.setOpaque(false);
		resultsHolder.add(resultsPanel);
		final JScrollPane scrollPane = new JScrollPane(resultsHolder);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		content.add(header, BorderLayout.NORTH);
		content.add(scrollPane, BorderLayout.CENTER);

		setSize(400, 460);
		setResizable(false);
		setLocationRelativeTo(getOwner());

		loadTextures();
	}

	private void loadTextures()
	{
		statusLabel.setText("Loading...");
		// Decoded in batches over several frames so opening the window doesn't stall the game.
		// A newer load (from Refresh) makes an older one stop.
		final int generation = ++loadGeneration;
		final List<Integer> ids = new ArrayList<>();
		final List<BufferedImage> images = new ArrayList<>();
		final int[] nextId = {0};

		clientThread.invoke(() ->
		{
			if (generation != loadGeneration)
			{
				return true;
			}

			final TextureProvider provider = client.getTextureProvider();
			if (provider != null)
			{
				final Texture[] textures = provider.getTextures();
				final int end = Math.min(textures.length, nextId[0] + TEXTURES_PER_FRAME);
				for (int id = nextId[0]; id < end; id++)
				{
					if (textures[id] == null)
					{
						continue;
					}
					final BufferedImage image = toThumbnail(provider, id);
					if (image != null)
					{
						ids.add(id);
						images.add(image);
					}
				}
				nextId[0] = end;
				if (end < textures.length)
				{
					return false;
				}
			}

			SwingUtilities.invokeLater(() ->
			{
				if (generation == loadGeneration)
				{
					populate(ids, images);
				}
			});
			return true;
		});
	}

	private static BufferedImage toThumbnail(TextureProvider provider, int id)
	{
		final BufferedImage image = BarPainter.decodeTexture(provider, id);
		if (image == null)
		{
			return null;
		}

		final BufferedImage thumb = new BufferedImage(THUMB_SIZE, THUMB_SIZE, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = thumb.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(image, 0, 0, THUMB_SIZE, THUMB_SIZE, null);
		g.dispose();
		return thumb;
	}

	private void populate(List<Integer> ids, List<BufferedImage> images)
	{
		resultsPanel.removeAll();
		selectedButton = null;
		final int currentId = config.fillTextureId();

		for (int i = 0; i < ids.size(); i++)
		{
			final int id = ids.get(i);
			final JButton button = buildButton(id, images.get(i));
			if (id == currentId)
			{
				selectedButton = button;
				button.setBorder(SELECTED_BORDER);
			}
			resultsPanel.add(button);
		}

		statusLabel.setText(ids.isEmpty() ? "No textures loaded yet, try Refresh" : ids.size() + " textures");
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	private JButton buildButton(int textureId, BufferedImage image)
	{
		final JButton button = new JButton(new ImageIcon(image));
		button.setToolTipText("Texture " + textureId);
		button.setPreferredSize(new Dimension(THUMB_SIZE + 4, THUMB_SIZE + 4));
		button.setBorder(IDLE_BORDER);
		button.setContentAreaFilled(false);
		button.setFocusable(false);
		button.addActionListener(e -> select(button, textureId));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(HOVER_BORDER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(IDLE_BORDER);
				}
			}
		});
		return button;
	}

	private void select(JButton button, int textureId)
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
		}
		selectedButton = button;
		button.setBorder(SELECTED_BORDER);
		configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.FILL_TEXTURE_ID_KEY, textureId);
	}

	private void selectNone()
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
			selectedButton = null;
		}
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.FILL_TEXTURE_ID_KEY);
	}
}

package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.config.ConfigWrites.Write;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import net.runelite.client.config.ConfigManager;

// The Oldschool checkbox turns off Rare gold bars and brings it back when it's unticked. Ticking Rare gold
// bars while Oldschool is on unticks Oldschool instead.
public final class OldschoolToggle
{
	// What Rare gold bars was set to before Oldschool turned it off.
	static final String SAVED_RARE_GOLD_BARS_KEY = "oldschoolSavedRareGoldBars";

	@Value
	static class Settings
	{
		boolean oldschool;
		boolean rareGoldBars;
		// Null when nothing is remembered.
		Boolean savedRareGoldBars;
	}

	private OldschoolToggle()
	{
	}

	public static boolean handles(String key)
	{
		return BossHealthBarConfig.OLDSCHOOL_THEME_KEY.equals(key)
			|| BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(key);
	}

	// The defaults of the three boxes. Memory goes first so unticking Oldschool restores nothing.
	public static List<Write> resetWrites()
	{
		return Arrays.asList(
			new Write(SAVED_RARE_GOLD_BARS_KEY, null),
			new Write(BossHealthBarConfig.OLDSCHOOL_THEME_KEY, false),
			new Write(BossHealthBarConfig.MATCH_BOSS_COLORS_KEY, false),
			new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, true));
	}

	// The remembered keys are cleared before anything is ticked back on, so the change events these
	// writes cause find nothing left to do.
	static List<Write> writes(String key, boolean oldValue, boolean newValue, Settings current)
	{
		if (oldValue == newValue)
		{
			return Collections.emptyList();
		}

		final List<Write> writes = new ArrayList<>();
		if (BossHealthBarConfig.OLDSCHOOL_THEME_KEY.equals(key))
		{
			if (newValue)
			{
				// Switching RuneLite profiles also reports changed keys. Values the new profile already
				// remembers are kept rather than overwritten with the boxes it has turned off.
				if (current.getSavedRareGoldBars() == null)
				{
					writes.add(new Write(SAVED_RARE_GOLD_BARS_KEY, current.isRareGoldBars()));
				}
				writes.add(new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, false));
			}
			else
			{
				restore(writes, null, current);
			}
		}
		else if (newValue && current.isOldschool() && BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(key))
		{
			restore(writes, key, current);
			writes.add(new Write(BossHealthBarConfig.OLDSCHOOL_THEME_KEY, false));
		}
		return writes;
	}

	private static void restore(List<Write> writes, String skippedKey, Settings current)
	{
		if (current.getSavedRareGoldBars() == null)
		{
			return;
		}
		writes.add(new Write(SAVED_RARE_GOLD_BARS_KEY, null));
		if (!BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(skippedKey))
		{
			writes.add(new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, current.getSavedRareGoldBars()));
		}
	}

	public static void apply(ConfigManager configManager, BossHealthBarConfig config, String key, boolean oldValue,
		boolean newValue)
	{
		applyWrites(configManager, writes(key, oldValue, newValue,
			new Settings(config.oldschoolTheme(), config.rareGoldBars(),
				ConfigWrites.savedBoolean(configManager, SAVED_RARE_GOLD_BARS_KEY))));
	}

	public static void applyWrites(ConfigManager configManager, List<Write> writes)
	{
		// Each write posts its own change event straight away. Handling those again is harmless, since
		// the remembered keys are cleared before anything is turned back on.
		for (Write write : writes)
		{
			ConfigWrites.write(configManager, write.getKey(), write.getValue());
		}
	}
}

package com.ghordrin.bosshealthbar.config;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

// Says once where the settings that used to be on the settings screen went.
@Singleton
public class PanelMoveNotice
{
	// Set once the notice has been shown. Not a config item, so neither Reset nor an import brings it back.
	static final String TOLD_KEY = "panelMoveTold";

	private static final String MESSAGE = "Boss Health Bar: the look, text, boss info, animations and layout"
		+ " settings are now in the plugin's own panel. Open it from the sidebar icon, or right-click the bar"
		+ " and pick \"Open panel\".";

	private final ConfigManager configManager;
	private final ChatMessageManager chatMessageManager;

	private boolean told;

	@Inject
	PanelMoveNotice(ConfigManager configManager, ChatMessageManager chatMessageManager)
	{
		this.configManager = configManager;
		this.chatMessageManager = chatMessageManager;
	}

	// A chat message before login goes nowhere, so this waits for one, and every login after the first is
	// one the notice has already been shown on.
	public void onLoggedIn()
	{
		if (!shouldTell(configManager.getConfiguration(BossHealthBarConfig.GROUP, TOLD_KEY), told))
		{
			return;
		}

		told = true;
		ConfigWrites.write(configManager, TOLD_KEY, true);
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(MESSAGE)
			.build());
	}

	static boolean shouldTell(String saved, boolean toldThisSession)
	{
		return !toldThisSession && saved == null;
	}
}

package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.theme.HealthBarTheme;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;

// Opens the custom icon window and the fill texture window.
@Singleton
public class Pickers
{
	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	// Only touched on the EDT.
	private FillTexturePickerDialog texturePickerDialog;
	private CustomIconPickerDialog iconPickerDialog;

	// The theme the switch was declined for, so the prompt asks once per theme. Only touched on the EDT.
	private String declinedFor;

	@Inject
	Pickers(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config,
		ItemManager itemManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
	}

	public void openIconPicker()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (iconPickerDialog == null || !iconPickerDialog.isDisplayable())
			{
				iconPickerDialog = new CustomIconPickerDialog(client, clientThread, configManager, config,
					itemManager, spriteManager);
			}
			iconPickerDialog.setVisible(true);
			iconPickerDialog.toFront();
		});
	}

	public void openFillTexturePicker()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog == null || !texturePickerDialog.isDisplayable())
			{
				texturePickerDialog = new FillTexturePickerDialog(client, clientThread, configManager, config);
			}
			texturePickerDialog.setVisible(true);
			texturePickerDialog.toFront();
		});
	}

	// Picking a theme writes its colors over the section again, so whatever was declined before is moot.
	public void themeChanged()
	{
		declinedFor = null;
	}

	// A picked color only shows on the Custom theme, so offer the switch rather than change nothing. The theme
	// it asked about is kept so a decline doesn't ask again for every other color of the same theme.
	public void confirmCustomTheme()
	{
		if (config.theme() == HealthBarTheme.CUSTOM
			|| config.theme().name().equals(declinedFor))
		{
			return;
		}

		final String asked = config.theme().name();
		SwingUtilities.invokeLater(() ->
		{
			final int choice = JOptionPane.showConfirmDialog(SwingUtilities.getWindowAncestor(client.getCanvas()),
				"The Custom colors are only used by the Custom theme, which starts from the colors of the theme"
					+ " you have now. Switch the theme to Custom so your color shows?",
				"Switch to the Custom theme?", JOptionPane.YES_NO_OPTION);
			if (choice == JOptionPane.YES_OPTION)
			{
				configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.THEME_KEY,
					HealthBarTheme.CUSTOM);
			}
			else
			{
				declinedFor = asked;
			}
		});
	}

	public void close()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog != null)
			{
				texturePickerDialog.dispose();
				texturePickerDialog = null;
			}
			if (iconPickerDialog != null)
			{
				iconPickerDialog.dispose();
				iconPickerDialog = null;
			}
		});
	}
}

package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.BossHealthBarPlugin;
import com.ghordrin.bosshealthbar.theme.CustomColors;
import com.ghordrin.bosshealthbar.theme.PaletteCode;
import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.awt.Color;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.io.IOException;
import java.io.Reader;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigItemDescriptor;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Filepath;

// Saves every setting to a file you can keep or pass on, and puts one back. The file is plain JSON, so a
// setup can also be shared as text through the clipboard.
@Slf4j
@Singleton
public class SettingsTransfer
{
	private static final String FILE_PREFIX = "boss-health-bar-settings-";
	private static final String FILE_SUFFIX = ".json";
	private static final DateTimeFormatter FILE_TIME = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");
	private static final DateTimeFormatter SAVED_TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
	private static final String KEY_PREFIX = BossHealthBarConfig.GROUP + ".";

	// Buttons that do something the moment they are ticked, and bookkeeping that says which one-off changes
	// have already been made to this installation. Neither belongs to a saved look, so neither travels: a
	// button would fire on import, and another installation's bookkeeping would skip or redo a change here.
	private static final Set<String> NOT_SETTINGS = ImmutableSet.of(
		BossHealthBarConfig.SAVE_DEBUG_LOG_KEY,
		BossHealthBarConfig.CHOOSE_FILL_TEXTURE_KEY,
		BossHealthBarConfig.CHOOSE_CUSTOM_ICON_KEY,
		BossHealthBarConfig.EXPORT_SETTINGS_KEY,
		BossHealthBarConfig.IMPORT_SETTINGS_KEY,
		BossHealthBarConfig.SHOW_PREVIEW_KEY,
		BossHealthBarConfig.OPEN_PANEL_KEY,
		PanelMoveNotice.TOLD_KEY,
		ConfigMigrations.FONT_DEFAULT_MIGRATED_KEY,
		ConfigMigrations.PIXEL_FONT_SIZE_MIGRATED_KEY,
		ConfigMigrations.ITEM_FONTS_MIGRATED_KEY,
		ConfigMigrations.FIGHT_TIMER_FONT_MIGRATED_KEY);

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final CustomColors customColors;
	private final ChatMessageManager chatMessageManager;
	private final ScheduledExecutorService executor;
	private final BossHealthBarPlugin plugin;
	private final Gson gson;

	// While this is on, the settings are being written in bulk. The plugin leaves them alone until it is
	// over: the theme would copy itself over the custom colors, every color would ask about the theme, and
	// the Oldschool toggle would write its companions, all on top of settings that were just chosen.
	@Getter
	private volatile boolean importing;

	@Inject
	SettingsTransfer(Client client, ClientThread clientThread, ConfigManager configManager,
		BossHealthBarConfig config, CustomColors customColors, ChatMessageManager chatMessageManager,
		ScheduledExecutorService executor, BossHealthBarPlugin plugin, Gson gson)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.customColors = customColors;
		this.chatMessageManager = chatMessageManager;
		this.executor = executor;
		this.plugin = plugin;
		this.gson = gson;
	}

	public void export()
	{
		executor.execute(() ->
		{
			final LocalDateTime now = LocalDateTime.now();
			final String json = gson.toJson(new Saved(BossHealthBarPlugin.NAME, BossHealthBarPlugin.VERSION,
				SAVED_TIME.format(now), settings()));
			final String fileName = FILE_PREFIX + FILE_TIME.format(now) + FILE_SUFFIX;
			try
			{
				final Filepath directory = plugin.dataDirectory();
				directory.createDirectories();
				directory.joinSegment(fileName).write(json);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Couldn't save the settings", e);
				chat("Couldn't save your settings to a file.");
				return;
			}
			copyToClipboard(json);
			chat("Settings saved to .runelite/plugin-data/" + BossHealthBarPlugin.INTERNAL_NAME + "/" + fileName
				+ " and copied to your clipboard.");
		});
	}

	private Map<String, String> settings()
	{
		final Map<String, String> settings = new TreeMap<>();
		for (String key : keys())
		{
			final String value = configManager.getConfiguration(BossHealthBarConfig.GROUP, key);
			if (value != null)
			{
				settings.put(key, value);
			}
		}
		return settings;
	}

	// The keys this installation has a saved value for, without the group in front and without the ones that
	// aren't part of a look. A setting left at its default has no saved value and so isn't one of them.
	private List<String> keys()
	{
		final List<String> keys = new ArrayList<>();
		for (String full : configManager.getConfigurationKeys(KEY_PREFIX))
		{
			final String key = full.substring(KEY_PREFIX.length());
			if (!key.isEmpty() && !NOT_SETTINGS.contains(key))
			{
				keys.add(key);
			}
		}
		return keys;
	}

	private void copyToClipboard(String json)
	{
		SwingUtilities.invokeLater(() ->
		{
			try
			{
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(json), null);
			}
			catch (RuntimeException e)
			{
				log.warn("Couldn't copy to the clipboard", e);
			}
		});
	}

	public void startImport()
	{
		SwingUtilities.invokeLater(() ->
		{
			final Filepath.Chooser chooser = new Filepath.Chooser()
				.setIsOpen()
				.setAcceptsFiles()
				.setDialogTitle("Import settings")
				.addExtensionFilter("Settings file (*.json)", "json");
			startIn(chooser);
			final List<Filepath> chosen = chooser.showDialog(parent());
			if (chosen == null || chosen.isEmpty())
			{
				return;
			}

			final Filepath file = chosen.get(0);
			executor.execute(() -> read(file));
		});
	}

	// Settings shared as text rather than as a file, the way a setup is passed on.
	public void importFromClipboard()
	{
		SwingUtilities.invokeLater(() ->
		{
			final String text = clipboardText("settings");
			if (text != null)
			{
				executor.execute(() -> use(text, "Your clipboard holds no settings for this plugin."));
			}
		});
	}

	// Only the look: the Custom colors and icon as one line, short enough to share in a chat.
	public void copyColors()
	{
		final String code = CustomColors.code(config);
		copyToClipboard(code);
		chat("Your colors are on your clipboard as a color code, ready to paste.");
	}

	public void pasteColors()
	{
		SwingUtilities.invokeLater(() ->
		{
			final String text = clipboardText("colors");
			if (text == null)
			{
				return;
			}
			final PaletteCode.Palette palette = PaletteCode.decode(text);
			if (palette == null)
			{
				error("Your clipboard holds no color code. A color code starts with bhb1:");
				return;
			}
			clientThread.invoke(() ->
			{
				customColors.use(palette);
				chat("Colors pasted. The theme is now Custom.");
			});
		});
	}

	// Null, after saying so, when there is no text to read.
	private String clipboardText(String what)
	{
		try
		{
			return (String) Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
		}
		catch (UnsupportedFlavorException | IOException | RuntimeException e)
		{
			log.debug("Couldn't read the clipboard", e);
			error("There is no text on your clipboard to read " + what + " from.");
			return null;
		}
	}

	private void startIn(Filepath.Chooser chooser)
	{
		try
		{
			final Filepath directory = plugin.dataDirectory();
			if (directory.isDirectory())
			{
				chooser.setCurrentDirectory(directory);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Couldn't start the file chooser in the plugin's folder", e);
		}
	}

	private void read(Filepath file)
	{
		final Saved saved;
		try (Reader reader = file.openReader())
		{
			saved = gson.fromJson(reader, Saved.class);
		}
		catch (JsonSyntaxException e)
		{
			log.debug("Couldn't read the settings", e);
			error("That file holds no settings for this plugin.");
			return;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Couldn't read the settings file", e);
			error("That file couldn't be read.");
			return;
		}
		use(saved, "That file holds no settings for this plugin.");
	}

	private void use(String text, String emptyMessage)
	{
		final Saved saved;
		try
		{
			saved = gson.fromJson(text, Saved.class);
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read the settings", e);
			error(emptyMessage);
			return;
		}
		use(saved, emptyMessage);
	}

	private void use(Saved saved, String emptyMessage)
	{
		if (saved == null || saved.settings == null || saved.settings.isEmpty())
		{
			error(emptyMessage);
			return;
		}

		final Map<String, String> wanted = keep(saved.settings);
		if (wanted.isEmpty())
		{
			error(emptyMessage);
			return;
		}

		final int dropped = saved.settings.size() - wanted.size();
		confirm(wanted, dropped);
	}

	// A file is someone else's text, so only the settings this plugin actually has are taken from it, and
	// only where the value is one that setting can hold. Anything else would either mean nothing or would
	// break the setting it landed in the first time the bar tried to read it.
	private Map<String, String> keep(Map<String, String> settings)
	{
		final Map<String, Class<?>> declared = declared();
		final Map<String, String> wanted = new TreeMap<>();
		for (Map.Entry<String, String> setting : settings.entrySet())
		{
			final String key = setting.getKey();
			final Class<?> type = declared.get(key);
			if (type == null || NOT_SETTINGS.contains(key) || setting.getValue() == null)
			{
				log.debug("Ignoring {}, which isn't one of this plugin's settings", key);
				continue;
			}
			if (!holds(type, setting.getValue()))
			{
				log.debug("Ignoring {}, which can't hold \"{}\"", key, setting.getValue());
				continue;
			}
			wanted.put(key, setting.getValue());
		}
		return wanted;
	}

	// Every setting this plugin declares, and what each one holds. Taken from the config itself, so a setting
	// added later is known here without being listed twice.
	private Map<String, Class<?>> declared()
	{
		final Map<String, Class<?>> declared = new HashMap<>();
		for (ConfigItemDescriptor item : configManager.getConfigDescriptor(config).getItems())
		{
			// What a setting holds is the class behind it. A setting whose type isn't a plain class, such as
			// a list of something, has no one value a saved line could be read as, so it is left out here
			// and never taken from a file.
			if (item.getType() instanceof Class)
			{
				declared.put(item.key(), (Class<?>) item.getType());
			}
		}
		return declared;
	}

	// The saved keys to clear outright: the ones the file doesn't name and this version no longer declares,
	// such as a setting a later version dropped. Everything still declared is covered by the defaults.
	static List<String> keysToUnset(Collection<String> saved, Set<String> declared, Set<String> named)
	{
		final List<String> unset = new ArrayList<>();
		for (String key : saved)
		{
			if (!named.contains(key) && !declared.contains(key))
			{
				unset.add(key);
			}
		}
		return unset;
	}

	// The same readings the client makes of a saved value, asked beforehand rather than when the bar is drawn.
	private boolean holds(Class<?> type, String value)
	{
		try
		{
			if (type == boolean.class || type == Boolean.class)
			{
				return "true".equalsIgnoreCase(value) || "false".equalsIgnoreCase(value);
			}
			if (type == int.class || type == Integer.class)
			{
				Integer.parseInt(value);
				return true;
			}
			if (type == double.class || type == Double.class)
			{
				Double.parseDouble(value);
				return true;
			}
			if (type == Color.class)
			{
				return ColorUtil.fromString(value) != null;
			}
			if (type.isEnum())
			{
				for (Object constant : type.getEnumConstants())
				{
					if (((Enum<?>) constant).name().equals(value))
					{
						return true;
					}
				}
				return false;
			}
			// A plain string setting, such as the lists of bosses to always or never show.
			return type == String.class;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	// Loading puts back everything the file names and returns the rest to its default, so it is worth saying
	// so first. The count is what the file turned out to be worth, not how long it was.
	private void confirm(Map<String, String> settings, int dropped)
	{
		SwingUtilities.invokeLater(() ->
		{
			final String ignored = dropped == 0 ? ""
				: "\n" + dropped + (dropped == 1 ? " entry was" : " entries were") + " ignored.";
			final int answer = JOptionPane.showConfirmDialog(parent(),
				"Load " + settings.size() + (settings.size() == 1 ? " setting" : " settings")
					+ "? Everything the file doesn't name goes back to its default." + ignored,
				"Import settings", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE);
			if (answer == JOptionPane.YES_OPTION)
			{
				apply(settings);
			}
		});
	}

	// Written on the client thread so the writes and everything they set off happen while importing is on,
	// and the plugin sees one finished set of settings rather than a half-applied one.
	private void apply(Map<String, String> settings)
	{
		clientThread.invoke(() ->
		{
			int written = 0;
			importing = true;
			try
			{
				// A setting the file doesn't name goes back to its default, so what is loaded is what was
				// saved, and not what was saved on top of whatever was here before. The defaults are
				// written rather than the keys unset: a setting with nothing saved for it reads as null,
				// and the client's own editor for a font type doesn't expect that, so the font settings
				// couldn't be opened at all after an import that left them out.
				configManager.setDefaultConfiguration(config, true);
				for (String key : keysToUnset(keys(), declared().keySet(), settings.keySet()))
				{
					configManager.unsetConfiguration(BossHealthBarConfig.GROUP, key);
				}
				for (Map.Entry<String, String> setting : settings.entrySet())
				{
					configManager.setConfiguration(BossHealthBarConfig.GROUP, setting.getKey(), setting.getValue());
					written++;
				}
			}
			finally
			{
				importing = false;
			}
			chat(written + (written == 1 ? " setting" : " settings") + " loaded.");
		});
	}

	private void error(String message)
	{
		SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(parent(), message, "Import settings",
			JOptionPane.WARNING_MESSAGE));
	}

	private Window parent()
	{
		return SwingUtilities.getWindowAncestor(client.getCanvas());
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	// The file's shape. Everything but the settings is there to read, so a file can be told apart by eye.
	// The empty constructor is the one a file is read back into.
	private static class Saved
	{
		private String plugin;
		private String version;
		private String saved;
		private Map<String, String> settings;

		Saved()
		{
		}

		Saved(String plugin, String version, String saved, Map<String, String> settings)
		{
			this.plugin = plugin;
			this.version = version;
			this.saved = saved;
			this.settings = settings;
		}
	}
}

package com.ghordrin.bosshealthbar.data;

import com.ghordrin.bosshealthbar.integrations.HealthIndicatorMarkers;
import com.ghordrin.bosshealthbar.integrations.SpecialAttackCounts;
import java.util.Collections;
import java.util.List;

public final class BarState
{
	public static final float[] NO_PHASE_MARKERS = new float[0];

	// No delve level to show.
	public static final int NO_DELVE_LEVEL = 0;

	public final String name;
	// The shorter name to fall back on when the full one doesn't fit, or null when the boss has none.
	public final String shortName;
	public final int combatLevel;
	public final int delveLevel;
	public final Health health;
	public final float[] phaseMarkers;
	public final HealthIndicatorMarkers.Marker[] userMarkers;
	public final String killCountKey;
	public final BossStats.Info stats;
	public final List<SpecialAttackCounts.Reading> specialAttacks;
	public final String fightTime;

	public BarState(String name, String shortName, int combatLevel, int delveLevel, Health health, float[] phaseMarkers,
		HealthIndicatorMarkers.Marker[] userMarkers, String killCountKey, BossStats.Info stats,
		List<SpecialAttackCounts.Reading> specialAttacks, String fightTime)
	{
		this.name = name;
		this.shortName = shortName;
		this.combatLevel = combatLevel;
		this.delveLevel = delveLevel;
		this.health = health;
		this.phaseMarkers = phaseMarkers;
		this.userMarkers = userMarkers;
		this.killCountKey = killCountKey;
		this.stats = stats;
		this.specialAttacks = specialAttacks;
		this.fightTime = fightTime;
	}

	// A bar with a name and health but none of the extras.
	public static BarState healthOnly(String name, Health health)
	{
		return new BarState(name, null, 0, NO_DELVE_LEVEL, health, NO_PHASE_MARKERS, HealthIndicatorMarkers.NONE, null,
			null, Collections.emptyList(), null);
	}

	public BarState withHealth(Health newHealth)
	{
		return new BarState(name, shortName, combatLevel, delveLevel, newHealth, phaseMarkers, userMarkers,
			killCountKey, stats, specialAttacks, fightTime);
	}

	public BarState withFightTime(String time)
	{
		return new BarState(name, shortName, combatLevel, delveLevel, health, phaseMarkers, userMarkers, killCountKey,
			stats, specialAttacks, time);
	}
}

