package com.ghordrin.bosshealthbar.gamebars;

import static com.ghordrin.bosshealthbar.render.BarAnimation.clamp01;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

// The game's pillar charge bars, read from the scripts that drive them so they can be drawn while the game's are hidden.
@Singleton
public class PillarBars
{
	// Client script ids, which have no gameval constants.
	static final int UPDATE_SCRIPT = 3315;
	static final int FADE_IN_SCRIPT = 3312;
	static final int FADE_OUT_SCRIPT = 3323;

	static final int CORNERS = 4;
	private static final int ARGS_PER_CORNER = 4;
	// The script id, four corners and a trailing flag.
	static final int UPDATE_ARGS = 1 + CORNERS * ARGS_PER_CORNER + 1;
	private static final int UNCHANGED = -1;
	private static final int TRANSPARENT = 255;

	// In drawing order: north west, north east, south west, south east.
	private static final int[] BAR_BACKS = {
		InterfaceID.NightmareTotems.TOTEM_NW_BAR_BACK,
		InterfaceID.NightmareTotems.TOTEM_NE_BAR_BACK,
		InterfaceID.NightmareTotems.TOTEM_SW_BAR_BACK,
		InterfaceID.NightmareTotems.TOTEM_SE_BAR_BACK,
	};
	private static final int[] BAR_REMAINING = {
		InterfaceID.NightmareTotems.TOTEM_NW_BAR_REMAINING,
		InterfaceID.NightmareTotems.TOTEM_NE_BAR_REMAINING,
		InterfaceID.NightmareTotems.TOTEM_SW_BAR_REMAINING,
		InterfaceID.NightmareTotems.TOTEM_SE_BAR_REMAINING,
	};

	private final Client client;
	private final DebugLog debugLog;
	private final HiddenWidget totems;

	private final float[] fractions = new float[CORNERS];
	private final boolean[] full = new boolean[CORNERS];
	private final boolean[] known = new boolean[CORNERS];
	private final int[] maxes = new int[CORNERS];
	private final int[] currents = {UNCHANGED, UNCHANGED, UNCHANGED, UNCHANGED};
	private boolean shown;
	private boolean shownKnown;
	private boolean seen;

	@Inject
	PillarBars(Client client, DebugLog debugLog)
	{
		this.client = client;
		this.debugLog = debugLog;
		this.totems = new HiddenWidget(client, debugLog, InterfaceID.NightmareTotems.TOTEMS);
	}

	public void onScript(int scriptId, Object[] args)
	{
		if (scriptId == FADE_IN_SCRIPT || scriptId == FADE_OUT_SCRIPT)
		{
			final boolean fadeIn = scriptId == FADE_IN_SCRIPT;
			if (fadeIn != shown)
			{
				debugLog.add("Pillar bars fade {}", fadeIn ? "in" : "out");
			}
			shown = fadeIn;
			shownKnown = true;
			return;
		}
		if (scriptId != UPDATE_SCRIPT || args == null || args.length < UPDATE_ARGS)
		{
			return;
		}

		for (int group = 0; group < CORNERS; group++)
		{
			final int first = 1 + group * ARGS_PER_CORNER;
			final Object back = args[first];
			final Object max = args[first + 2];
			final Object current = args[first + 3];
			if (!(back instanceof Integer) || !(max instanceof Integer) || !(current instanceof Integer))
			{
				continue;
			}

			final int corner = corner((Integer) back);
			if (corner >= 0)
			{
				apply(corner, (Integer) max, (Integer) current);
			}
		}
	}

	// Either value can come as unchanged, so the last one the script sent stands in for it.
	private void apply(int corner, int maxValue, int currentValue)
	{
		final int max = maxValue == UNCHANGED ? maxes[corner] : maxValue;
		if (max <= 0)
		{
			return;
		}
		final int previousMax = maxes[corner];
		maxes[corner] = max;
		final int current = currentValue == UNCHANGED ? currents[corner] : currentValue;
		if (current == UNCHANGED)
		{
			return;
		}
		// Charge changes every hit, so only the first value, a new max and reaching or leaving full are logged.
		final boolean nowFull = current >= max;
		final boolean logged = !known[corner] || max != previousMax || nowFull != full[corner];
		currents[corner] = current;
		fractions[corner] = fraction(current, max);
		full[corner] = nowFull;
		known[corner] = true;
		if (logged)
		{
			debugLog.add("Pillar bar {}: {}/{}", corner, current, max);
		}
	}

	public void update(boolean replace)
	{
		final Widget widget = totems.widget();
		if (widget == null)
		{
			totems.forget();
			clear();
			return;
		}

		if (!seen)
		{
			seed();
			seen = true;
		}

		if (replace)
		{
			totems.hide(widget, "Pillar bars: game's bars hidden");
		}
		else
		{
			release();
		}
	}

	// Hidden widgets don't run their timers, so the widths are only read before the bars are first hidden.
	private void seed()
	{
		for (int corner = 0; corner < CORNERS; corner++)
		{
			final Widget back = client.getWidget(BAR_BACKS[corner]);
			final Widget remaining = client.getWidget(BAR_REMAINING[corner]);
			if (known[corner] || back == null || remaining == null)
			{
				continue;
			}
			fractions[corner] = seedFraction(remaining.getWidth(), back.getWidth());
			full[corner] = seedFull(remaining.getWidth(), back.getWidth());
		}

		if (!shownKnown)
		{
			final Widget border = client.getWidget(InterfaceID.NightmareTotems.TOTEMS_BORDER);
			shown = border != null && border.getOpacity() < TRANSPARENT;
		}
		debugLog.add("Pillar bars seeded: {} {} shown={}", Arrays.toString(fractions), Arrays.toString(full), shown);
	}

	private void release()
	{
		totems.release("Pillar bars: game's bars released");
	}

	public void reset()
	{
		release();
		clear();
	}

	private void clear()
	{
		Arrays.fill(fractions, 0f);
		Arrays.fill(full, false);
		Arrays.fill(known, false);
		Arrays.fill(maxes, 0);
		Arrays.fill(currents, UNCHANGED);
		shown = false;
		shownKnown = false;
		seen = false;
	}

	boolean isVisible()
	{
		return totems.isHidden() && shown;
	}

	float fraction(int corner)
	{
		return fractions[corner];
	}

	boolean isFull(int corner)
	{
		return full[corner];
	}

	static int corner(int barBackId)
	{
		for (int corner = 0; corner < CORNERS; corner++)
		{
			if (BAR_BACKS[corner] == barBackId)
			{
				return corner;
			}
		}
		return -1;
	}

	static float fraction(int current, int max)
	{
		return clamp01(current / (float) max);
	}

	static float seedFraction(int remainingWidth, int backWidth)
	{
		return backWidth > 0 ? clamp01(remainingWidth / (float) backWidth) : 0f;
	}

	static boolean seedFull(int remainingWidth, int backWidth)
	{
		return backWidth > 0 && remainingWidth == backWidth;
	}

	public boolean isShown()
	{
		return shown;
	}

	public boolean isSeen()
	{
		return seen;
	}

	public boolean isHidingGameBars()
	{
		return totems.isHidden();
	}
}

package com.ghordrin.bosshealthbar.gamebars;

import static com.ghordrin.bosshealthbar.render.BarAnimation.clamp01;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.brighten;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.lerp;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;
import com.ghordrin.bosshealthbar.BossHealthBarOverlay;
import com.ghordrin.bosshealthbar.BossHealthBarPlugin;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.render.BarPainter;
import com.ghordrin.bosshealthbar.render.BarTextPainter;
import com.ghordrin.bosshealthbar.theme.BarTheme;
import com.ghordrin.bosshealthbar.theme.ThemeColors;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

// Draws the game's pillar charge bars in the bar's style while this plugin hides the game's.
public class PillarBarsOverlay extends Overlay
{
	private static final String[] LABELS = {"North West", "North East", "South West", "South East"};
	private static final float[] PREVIEW_FRACTIONS = {1f, 0.6f, 0.25f, 0f};
	private static final boolean[] PREVIEW_FULL = {true, false, false, false};

	private static final int MIN_BAR_WIDTH = 64;
	// Small enough that dragging an edge only ever runs into the width this class clamps to itself.
	private static final int MIN_GRID_SIZE = 48;
	private static final int LABEL_PADDING = 4;
	private static final int MIN_BAR_HEIGHT = 5;
	private static final int MAX_BAR_HEIGHT = 9;
	private static final int COLUMN_GAP = 6;
	private static final int ROW_GAP = 3;
	private static final int LABEL_GAP = 1;
	private static final float FULL_BRIGHTEN = 0.75f;
	// The lift and shade the main bar gives its frame and its fill.
	private static final float FRAME_LIFT = 0.45f;
	private static final float FRAME_SHADE = 0.25f;
	private static final float FILL_LIFT = 0.3f;
	private static final float FILL_SHADE = 0.45f;

	// The game's own colors, used with the Oldschool theme.
	private static final Color FLAT_TRACK = new Color(0x2D2B00);
	private static final Color FLAT_FILL = new Color(0xDBD300);
	private static final Color FLAT_FULL = Color.WHITE;
	private static final Color FLAT_OUTLINE = new Color(0x191511);

	private final BossHealthBarConfig config;
	private final PillarBars pillarBars;
	private final BossHealthBarOverlay barOverlay;
	private final BarTextPainter textPainter;

	private final int[] labelWidths = new int[PillarBars.CORNERS];
	private FontMetrics labelMetrics;
	// The width the labels ask for, which a dragged width takes over from.
	private int naturalBarWidth;
	private int barWidth;
	private int labelHeight;

	private int trackPaintHeight = -1;
	private final Paint[] trackPaints = new Paint[2];

	private Color fullSource;
	private Color fullColor;

	@Inject
	private PillarBarsOverlay(BossHealthBarPlugin plugin, BossHealthBarConfig config, PillarBars pillarBars,
		BossHealthBarOverlay barOverlay, BarTextPainter textPainter)
	{
		super(plugin);
		this.config = config;
		this.pillarBars = pillarBars;
		this.barOverlay = barOverlay;
		this.textPainter = textPainter;

		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setResizable(true);
		setMinimumSize(MIN_GRID_SIZE);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, BossHealthBarPlugin.NAME);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final boolean live = pillarBars.isVisible();
		if (!live && !barOverlay.isShowingPreview())
		{
			return null;
		}

		textPainter.updateFonts();
		final FontMetrics metrics = textPainter.nameMetrics();
		if (metrics != labelMetrics)
		{
			measureLabels(metrics);
		}

		barWidth = barWidth(naturalBarWidth, getPreferredSize());
		final int barHeight = barHeight(config.barHeight());
		final int cellHeight = cellHeight(labelHeight, barHeight);

		final ThemeColors colors = barOverlay.baseColors();
		final boolean flat = BarTheme.of(config).isFlat();
		final Color fillHigh = flat ? FLAT_FILL : colors.getFillHigh();
		final Color fillLow = flat ? FLAT_FILL : colors.getFillLow();
		final Color full = flat ? FLAT_FULL : fullColor(fillHigh);
		final Color outline = flat ? FLAT_OUTLINE : colors.getFrame();
		final Color labelColor = colors.getHitpointsText();
		updateTrackPaints(barHeight, cellHeight);

		textPainter.applyTextHints(graphics);
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			final int column = corner % 2;
			final int row = corner / 2;
			final int x = column * (barWidth + COLUMN_GAP);
			final int y = row * (cellHeight + ROW_GAP);
			textPainter.drawNameStyleText(graphics, LABELS[corner], x + (barWidth - labelWidths[corner]) / 2,
				y + metrics.getAscent(), labelColor);

			final Paint track = flat ? FLAT_TRACK : colors.getTrack() != null ? colors.getTrack() : trackPaints[row];
			final float fraction = live ? pillarBars.fraction(corner) : PREVIEW_FRACTIONS[corner];
			final boolean isFull = live ? pillarBars.isFull(corner) : PREVIEW_FULL[corner];
			// The same blend the main bar uses, so these follow it from full health down to the low color.
			final Color fill = isFull ? full : lerp(fillLow, fillHigh, clamp01(fraction));
			drawBar(graphics, x, y + labelHeight + LABEL_GAP, barHeight, fraction, isFull, track, fill, outline, flat);
		}

		return gridSize(barWidth, cellHeight);
	}

	// The main bar's look at a tenth of its height: the frame is a single line of its gradient rather than a
	// moulding, and there are no end pieces, which at this size would leave no room for the bar itself.
	private void drawBar(Graphics2D graphics, int x, int y, int height, float fraction, boolean isFull, Paint track,
		Color fill, Color outline, boolean flat)
	{
		final int innerWidth = barWidth - 2;
		graphics.setPaint(flat ? outline : BarPainter.verticalSheen(y, height, outline, FRAME_LIFT, FRAME_SHADE));
		graphics.drawRect(x, y, barWidth - 1, height - 1);
		graphics.setPaint(track);
		graphics.fillRect(x + 1, y + 1, innerWidth, height - 2);
		final int filled = filledWidth(innerWidth, fraction, isFull);
		if (filled > 0)
		{
			graphics.setPaint(flat ? fill : BarPainter.verticalSheen(y + 1, height - 2, fill, FILL_LIFT, FILL_SHADE));
			graphics.fillRect(x + 1, y + 1, filled, height - 2);
		}
	}

	private void measureLabels(FontMetrics metrics)
	{
		int widest = 0;
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			labelWidths[corner] = metrics.stringWidth(LABELS[corner]);
			widest = Math.max(widest, labelWidths[corner]);
		}
		naturalBarWidth = barWidth(widest);
		// One more for the text shadow.
		labelHeight = metrics.getAscent() + 1;
		labelMetrics = metrics;
		trackPaintHeight = -1;
	}

	private void updateTrackPaints(int barHeight, int cellHeight)
	{
		if (barHeight == trackPaintHeight)
		{
			return;
		}
		for (int row = 0; row < trackPaints.length; row++)
		{
			final int top = row * (cellHeight + ROW_GAP) + labelHeight + LABEL_GAP + 1;
			trackPaints[row] = new GradientPaint(0, top, BarPainter.TRACK_TOP, 0, top + barHeight - 2, BarPainter.TRACK_BOTTOM);
		}
		trackPaintHeight = barHeight;
	}

	private Color fullColor(Color fill)
	{
		if (fill != fullSource)
		{
			fullColor = brighten(fill, FULL_BRIGHTEN);
			fullSource = fill;
		}
		return fullColor;
	}

	static int barWidth(int widestLabel)
	{
		return Math.max(MIN_BAR_WIDTH, widestLabel + LABEL_PADDING);
	}

	// Alt-dragging the overlay's edge sets a preferred size, which takes over from the width the labels ask
	// for until the overlay is reset. Only its width is used; the bars' height follows "Bar height".
	static int barWidth(int naturalWidth, Dimension preferred)
	{
		return preferred != null
			? Math.max(MIN_BAR_WIDTH, (preferred.width - COLUMN_GAP) / 2)
			: naturalWidth;
	}

	static int barHeight(int configured)
	{
		return Math.max(MIN_BAR_HEIGHT, Math.min(MAX_BAR_HEIGHT, configured));
	}

	static int cellHeight(int labelHeight, int barHeight)
	{
		return labelHeight + LABEL_GAP + barHeight;
	}

	static Dimension gridSize(int barWidth, int cellHeight)
	{
		return new Dimension(barWidth * 2 + COLUMN_GAP, cellHeight * 2 + ROW_GAP);
	}

	static int filledWidth(int innerWidth, float fraction, boolean full)
	{
		return full ? innerWidth : Math.max(0, Math.min(innerWidth, Math.round(innerWidth * fraction)));
	}
}

package com.ghordrin.bosshealthbar.gamebars;

import com.ghordrin.bosshealthbar.data.NpcUtil;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
public class TobBossBar
{
	// Values of TOB_CLIENT_WAVEPROGRESS_TYPE. Other values show room progress instead of health.
	private static final int PROGRESS_NONE = 0;
	private static final int PROGRESS_BOSS_HEALTH = 1;
	// TOB_CLIENT_PARTYSTATUS: 1 is a party outside, 2 is inside the raid and 3 is spectating it dead.
	private static final int PARTY_INSIDE = 2;
	private static final int SEARCH_DISTANCE = 32;
	// The room's boss can be out of reach while its bar is up: too far to find, or in another place entirely,
	// such as the maze a room can take the player into. The bar stays replaced for a moment, which covers
	// walking into a room and the death animation, but not an absence long enough to leave no bar at all.
	private static final int MISSING_GRACE_TICKS = 10;
	private static final int NOT_MISSING = -1;

	private final Client client;
	private final DebugLog debugLog;
	private final HiddenWidget raidBar;

	private NPC boss;
	private NPC loggedBoss;
	private boolean searchNeeded = true;
	private boolean loggedLeftOver;
	private boolean roomBossShown = true;
	private NPC shownBoss;
	private int missingSince = NOT_MISSING;

	@Inject
	TobBossBar(Client client, DebugLog debugLog)
	{
		this.client = client;
		this.debugLog = debugLog;
		this.raidBar = new HiddenWidget(client, debugLog, InterfaceID.TobHud.PROGRESS_CONTAINER);
	}

	// The Theatre of Blood bar doesn't say which NPC it belongs to, so this takes the highest level
	// attackable NPC nearby. Cached until a stronger NPC spawns or the boss changes or despawns.
	public NPC findBoss()
	{
		if (!barIsLive())
		{
			boss = null;
			searchNeeded = true;
			roomBossShown = true;
			shownBoss = null;
			missingSince = NOT_MISSING;
			if (loggedBoss != null)
			{
				loggedBoss = null;
				debugLog.add("Raid boss bar gone");
			}
			return null;
		}

		if (!searchNeeded)
		{
			return boss;
		}

		searchNeeded = false;
		boss = null;
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc.isDead() || !NpcUtil.isAttackable(npc)
				|| npc.getWorldLocation().distanceTo(player.getWorldLocation()) > SEARCH_DISTANCE)
			{
				continue;
			}

			if (boss == null
				|| npc.getCombatLevel() > boss.getCombatLevel()
				|| (npc.getCombatLevel() == boss.getCombatLevel() && NpcUtil.size(npc) > NpcUtil.size(boss)))
			{
				boss = npc;
			}
		}
		if (boss != loggedBoss)
		{
			loggedBoss = boss;
			debugLog.add("Raid boss bar belongs to {}", DebugLog.describe(boss));
		}
		return boss;
	}

	// Leaving the Theatre doesn't clear the progress varbits or unload its HUD, so on their own they keep
	// reading the health the last raid ended on, hours later and anywhere, and hand it to the strongest NPC
	// nearby. The party status is the game's own answer to whether you are in there, so it decides.
	private boolean barIsLive()
	{
		final int status = partyStatus();
		final boolean bossHealth = client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE) == PROGRESS_BOSS_HEALTH;
		final boolean leftOver = bossHealth && status < PARTY_INSIDE;
		if (leftOver != loggedLeftOver)
		{
			loggedLeftOver = leftOver;
			if (leftOver)
			{
				debugLog.add("Raid boss bar values left over from a raid, ignored (party status {})", status);
			}
		}
		return bossHealth && status >= PARTY_INSIDE && raidBar.widget() != null;
	}

	// The last boss found, without searching again.
	public NPC cachedBoss()
	{
		return boss;
	}

	public boolean isTracking(Actor actor)
	{
		return actor != null && actor == findBoss();
	}

	public void onNpcSpawned(NPC npc)
	{
		if (mayBeBoss(npc))
		{
			searchNeeded = true;
		}
	}

	public void onNpcChanged(NPC npc)
	{
		if (npc == boss || mayBeBoss(npc))
		{
			searchNeeded = true;
		}
	}

	public void onNpcDespawned(NPC npc)
	{
		if (npc == boss)
		{
			boss = null;
			searchNeeded = true;
		}
	}

	public void onGameTick()
	{
		if (boss == null)
		{
			// The room's boss may only have come into range as the player walked in.
			searchNeeded = true;
		}
	}

	private boolean mayBeBoss(NPC npc)
	{
		return boss == null || npc.getCombatLevel() >= boss.getCombatLevel();
	}

	// The Theatre's bar is replaced for as long as it is up for the room's boss, and not only while that boss
	// is the opponent: it is up from the moment the room starts, before the boss is near enough to be found,
	// and stays up for a moment after the boss dies, when there is no NPC left to match it to. found is the
	// boss findBoss() gave this frame, and bossGetsBar the answer the settings give for it.
	public void update(boolean replaceEnabled, NPC found, boolean bossGetsBar)
	{
		final Widget bar = raidBar.widget();
		if (bar == null)
		{
			raidBar.forget();
			return;
		}

		if (found != null)
		{
			missingSince = NOT_MISSING;
			// The answer belongs to the strongest NPC the room's bar has been matched to. While the boss is
			// away the search falls back on an NPC it spawned, and that one doesn't get to answer for it.
			if (shownBoss == null || found == shownBoss || found.getCombatLevel() > shownBoss.getCombatLevel())
			{
				shownBoss = found;
				roomBossShown = bossGetsBar;
			}
		}
		else if (missingSince == NOT_MISSING)
		{
			missingSince = client.getTickCount();
		}

		if (replaceEnabled && barIsLive() && roomBossShown && !missingTooLong())
		{
			raidBar.hide(bar, "Raid boss bar hidden");
		}
		else
		{
			restore();
		}
	}

	// Whether the room's boss has been out of reach long enough that the game's bar is the only one left.
	private boolean missingTooLong()
	{
		return missingSince != NOT_MISSING && client.getTickCount() - missingSince >= MISSING_GRACE_TICKS;
	}

	public void restore()
	{
		if (!raidBar.isHidden())
		{
			return;
		}

		raidBar.release("Raid boss bar restored",
			client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE) != PROGRESS_NONE);
	}

	public void reset()
	{
		raidBar.forget();
		loggedLeftOver = false;
		roomBossShown = true;
		shownBoss = null;
		missingSince = NOT_MISSING;
		boss = null;
		loggedBoss = null;
		searchNeeded = true;
	}

	// Says whether the player is in the Theatre, which decides whether the progress varbits mean anything.
	public int partyStatus()
	{
		return client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS);
	}

	public boolean isHidden()
	{
		return raidBar.isHidden();
	}

	public int maxHealth()
	{
		return client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_MAX);
	}

	public int health(int maxHealth)
	{
		return Math.max(0, Math.min(maxHealth, client.getVarbitValue(VarbitID.TOB_CLIENT_WAVEPROGRESS_VAL)));
	}
}

