package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.data.Health;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.google.common.annotations.VisibleForTesting;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.PluginManager;

// Reads the health lines users set up in the "Boss Health Indicators" plugin, which draws them onto the
// game's boss bar. That bar is hidden when this one replaces it, so the lines are drawn here instead.
@Slf4j
@Singleton
public class HealthIndicatorMarkers
{
	public static final String CONFIG_GROUP = "bosshealthindicators";
	private static final String CONFIG_KEY = "indicators";
	private static final String PLUGIN_NAME = "Boss Health Indicators";

	@Value
	public static class Marker
	{
		float fraction;
		Color color;
	}

	@Value
	private static class Entry
	{
		Pattern bossName;
		List<Marker> markers;
	}

	public static final Marker[] NONE = new Marker[0];

	private final BossHealthBarConfig config;
	private final ConfigManager configManager;
	private final PluginReader plugin;
	private final Gson gson;
	private final DebugLog debugLog;

	private List<Entry> entries;
	private String cachedName;
	private Marker[] cachedMarkers = NONE;

	@Inject
	HealthIndicatorMarkers(BossHealthBarConfig config, ConfigManager configManager, PluginManager pluginManager, Gson gson,
		DebugLog debugLog)
	{
		this.config = config;
		this.configManager = configManager;
		this.plugin = new PluginReader(pluginManager, PLUGIN_NAME);
		this.gson = gson;
		this.debugLog = debugLog;
	}

	public void invalidate()
	{
		plugin.invalidate();
		entries = null;
		cachedName = null;
	}

	// Called every frame, so the result is kept for the last name.
	public Marker[] markersFor(String name)
	{
		if (name == null || !config.showHealthIndicatorMarkers())
		{
			return NONE;
		}

		if (entries == null)
		{
			entries = plugin.isActive()
				? parse(gson, configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY), debugLog) : Collections.emptyList();
			cachedName = null;
		}

		if (!name.equals(cachedName))
		{
			cachedName = name;
			cachedMarkers = match(entries, name);
		}
		return cachedMarkers;
	}

	private static Marker[] match(List<Entry> entries, String name)
	{
		final List<Marker> matched = new ArrayList<>();
		for (Entry entry : entries)
		{
			if (entry.getBossName().matcher(name).matches())
			{
				matched.addAll(entry.getMarkers());
			}
		}
		return matched.isEmpty() ? NONE : matched.toArray(NONE);
	}

	@VisibleForTesting
	public static Marker[] markersFor(Gson gson, String json, String name)
	{
		return match(parse(gson, json, null), name);
	}

	// The format belongs to the other plugin and could change, so anything unexpected is skipped.
	private static List<Entry> parse(Gson gson, String json, DebugLog debugLog)
	{
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}

		final JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (JsonParseException e)
		{
			log.debug("Couldn't read Boss Health Indicators config", e);
			if (debugLog != null)
			{
				debugLog.add("Couldn't read Boss Health Indicators config: {}", e.toString());
			}
			return Collections.emptyList();
		}
		if (root == null || !root.isJsonArray())
		{
			return Collections.emptyList();
		}

		final List<Entry> entries = new ArrayList<>();
		for (JsonElement element : root.getAsJsonArray())
		{
			final Entry entry = parseEntry(element);
			if (entry != null)
			{
				entries.add(entry);
			}
		}
		return entries;
	}

	private static Entry parseEntry(JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		final JsonObject object = element.getAsJsonObject();
		final String bossName = string(object.get("bossName"));
		final JsonElement markerList = object.get("entries");
		if (bossName == null || markerList == null || !markerList.isJsonArray())
		{
			return null;
		}

		final Pattern pattern;
		try
		{
			pattern = Pattern.compile(bossName);
		}
		catch (PatternSyntaxException e)
		{
			return null;
		}

		final List<Marker> markers = new ArrayList<>();
		for (JsonElement markerElement : (JsonArray) markerList)
		{
			final Marker marker = parseMarker(markerElement);
			if (marker != null)
			{
				markers.add(marker);
			}
		}
		return markers.isEmpty() ? null : new Entry(pattern, markers);
	}

	public static Marker parseMarker(JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		final JsonObject object = element.getAsJsonObject();
		final JsonElement percentage = object.get("percentage");
		final Color color = color(object.get("color"));
		if (percentage == null || !percentage.isJsonPrimitive() || !percentage.getAsJsonPrimitive().isNumber() || color == null)
		{
			return null;
		}
		final float fraction = percentage.getAsFloat();
		return fraction > 0f && fraction < 1f ? new Marker(fraction, color) : null;
	}

	// Usually a "#AARRGGBB" string, but an object holding the ARGB value if it was saved without a color
	// type adapter. The other plugin draws its lines opaque, so the alpha is dropped.
	private static Color color(JsonElement element)
	{
		if (element == null)
		{
			return null;
		}

		final String hex = string(element);
		if (hex != null)
		{
			final String digits = hex.startsWith("#") ? hex.substring(1) : hex;
			if (digits.length() != 6 && digits.length() != 8)
			{
				return null;
			}
			try
			{
				return new Color((int) Long.parseLong(digits, 16));
			}
			catch (NumberFormatException e)
			{
				return null;
			}
		}

		if (!element.isJsonObject())
		{
			return null;
		}
		final JsonElement value = element.getAsJsonObject().get("value");
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		return new Color(value.getAsInt());
	}

	private static String string(JsonElement element)
	{
		return element != null && element.isJsonPrimitive() && element.getAsJsonPrimitive().isString()
			? element.getAsString() : null;
	}
}

package com.ghordrin.bosshealthbar.integrations;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.QuantityFormatter;

// Reads the kill counts saved by RuneLite's Chat Commands plugin. It keys them by the boss name in the
// game's kill count message, lowercased, which is usually the NPC name.
@Singleton
public class KillCounts
{
	public static final String CONFIG_GROUP = "killcount";

	private final ConfigManager configManager;

	private String cachedKey;
	private String cachedText;

	@Inject
	KillCounts(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public static String text(Integer count)
	{
		return count != null && count > 0 ? "KC " + QuantityFormatter.formatNumber(count.longValue()) : null;
	}

	public void invalidate()
	{
		cachedKey = null;
		cachedText = null;
	}

	// Called every frame, so the result is kept for the last key.
	public String textFor(String key)
	{
		if (key == null)
		{
			return null;
		}
		if (!key.equals(cachedKey))
		{
			cachedKey = key;
			cachedText = text(configManager.getRSProfileConfiguration(CONFIG_GROUP, key, int.class));
		}
		return cachedText;
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.google.common.annotations.VisibleForTesting;
import com.google.common.primitives.Doubles;
import com.google.common.primitives.Ints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.QuantityFormatter;

// A kill count milestone or a new personal best, taken from the moment RuneLite's Chat Commands plugin saves
// it, so the bar of that boss can mark it while it shows the kill. Both are saved under the boss name.
@Singleton
public class KillMoments
{
	public static final String PERSONAL_BEST_GROUP = "personalbest";
	// The game's message comes a tick or two either side of the death, so a moment waits a while for its bar.
	private static final long SHOWN_MILLIS = 15_000;

	private final BossHealthBarConfig config;

	private String key;
	private int milestone;
	private boolean personalBest;
	private long savedAt;

	@Inject
	KillMoments(BossHealthBarConfig config)
	{
		this.config = config;
	}

	public void killCountSaved(String bossKey, String oldValue, String newValue, long nowMillis)
	{
		if (!config.killMilestones())
		{
			return;
		}
		final Integer count = newValue != null ? Ints.tryParse(newValue) : null;
		final Integer before = oldValue != null ? Ints.tryParse(oldValue) : null;
		// Only a count going up is a kill. Chat Commands also writes counts it reads off the game's logs.
		if (count != null && (before == null || count > before) && isMilestone(count, config.killMilestoneEvery()))
		{
			note(bossKey, nowMillis);
			milestone = count;
		}
	}

	public void personalBestSaved(String bossKey, String oldValue, String newValue, long nowMillis)
	{
		final Double time = newValue != null ? Doubles.tryParse(newValue) : null;
		final Double before = oldValue != null ? Doubles.tryParse(oldValue) : null;
		// Only a faster time is a new best. Chat Commands also saves the best the game repeats after a kill,
		// and the one it reads off the adventure log, which would otherwise read as new the first time.
		if (config.personalBests() && time != null && before != null && time < before)
		{
			note(bossKey, nowMillis);
			personalBest = true;
		}
	}

	// Null when there is nothing to mark for this boss now.
	public String labelFor(String bossKey, long nowMillis)
	{
		if (bossKey == null || !bossKey.equals(key) || nowMillis - savedAt > SHOWN_MILLIS)
		{
			return null;
		}
		return label(milestone, personalBest);
	}

	private void note(String bossKey, long nowMillis)
	{
		if (!bossKey.equals(key) || nowMillis - savedAt > SHOWN_MILLIS)
		{
			milestone = 0;
			personalBest = false;
		}
		key = bossKey;
		savedAt = nowMillis;
	}

	@VisibleForTesting
	static boolean isMilestone(int count, int every)
	{
		return count == 1 || (every > 0 && count % every == 0);
	}

	@VisibleForTesting
	static String label(int milestone, boolean personalBest)
	{
		final String kill = milestone > 0 ? ordinal(milestone) + " kill" : null;
		if (kill != null && personalBest)
		{
			return kill + ", New PB";
		}
		return kill != null ? kill : personalBest ? "New PB" : null;
	}

	@VisibleForTesting
	static String ordinal(int number)
	{
		final int lastTwo = number % 100;
		final int last = number % 10;
		final String suffix = lastTwo >= 11 && lastTwo <= 13 ? "th"
			: last == 1 ? "st" : last == 2 ? "nd" : last == 3 ? "rd" : "th";
		return QuantityFormatter.formatNumber(number) + suffix;
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.google.common.annotations.VisibleForTesting;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.Map;
import net.runelite.client.util.ImageUtil;

// Tells Better Party Defence's Magic defence box apart by its image. With its theme icon option on it draws its
// own 16x16 copy of the Magic icon (or of a resource pack's override), so those copies are rebuilt the same way
// here and compared pixel by pixel.
class MagicIconMatcher
{
	private static final int THEMED_ICON_SIZE = 16;
	private static final int MAX_VERDICTS = 8;

	private BufferedImage classicSource;
	private BufferedImage classic;
	private BufferedImage overrideSource;
	private BufferedImage override;
	private final Map<BufferedImage, Boolean> verdicts = new IdentityHashMap<>();

	boolean isMagic(BufferedImage image, BufferedImage skillImage, BufferedImage overrideImage)
	{
		if (image == null)
		{
			return false;
		}
		if (image == skillImage)
		{
			return true;
		}

		if (skillImage != classicSource)
		{
			classicSource = skillImage;
			classic = themed(skillImage);
			verdicts.clear();
		}
		if (overrideImage != overrideSource)
		{
			overrideSource = overrideImage;
			override = themed(overrideImage);
			verdicts.clear();
		}

		Boolean verdict = verdicts.get(image);
		if (verdict == null)
		{
			if (verdicts.size() >= MAX_VERDICTS)
			{
				verdicts.clear();
			}
			verdict = samePixels(image, classic) || samePixels(image, override);
			verdicts.put(image, verdict);
		}
		return verdict;
	}

	void reset()
	{
		classicSource = null;
		classic = null;
		overrideSource = null;
		override = null;
		verdicts.clear();
	}

	@VisibleForTesting
	static BufferedImage themed(BufferedImage source)
	{
		return source != null && source.getWidth() > 0 && source.getHeight() > 0
			? ImageUtil.resizeImage(source, THEMED_ICON_SIZE, THEMED_ICON_SIZE) : null;
	}

	@VisibleForTesting
	static boolean samePixels(BufferedImage a, BufferedImage b)
	{
		if (a == null || b == null || a.getWidth() != b.getWidth() || a.getHeight() != b.getHeight())
		{
			return false;
		}
		final int width = a.getWidth();
		final int height = a.getHeight();
		return Arrays.equals(a.getRGB(0, 0, width, height, null, 0, width), b.getRGB(0, 0, width, height, null, 0, width));
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.config.ConfigWrites;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

// Turns off the health bar of RuneLite's Opponent Information plugin while this plugin runs, and
// puts the user's own setting back afterwards.
@Singleton
public class OpponentInfoOverride
{
	private static final String GROUP = "opponentinfo";
	private static final String KEY = "showOpponentHealthOverlay";
	// Stored in config so the original value can still be restored if the client closes while hidden.
	private static final String SAVED_KEY = "savedOpponentHealthOverlay";
	private static final String HIDDEN_KEY = "opponentHealthOverlayHidden";

	private final ConfigManager configManager;
	private final BossHealthBarConfig config;

	@Inject
	OpponentInfoOverride(ConfigManager configManager, BossHealthBarConfig config)
	{
		this.configManager = configManager;
		this.config = config;
	}

	public void apply()
	{
		if (!config.hideVanillaOverlay())
		{
			return;
		}

		if (!isHidden())
		{
			ConfigWrites.write(configManager, SAVED_KEY, configManager.getConfiguration(GROUP, KEY));
			configManager.setConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY, true);
		}

		configManager.setConfiguration(GROUP, KEY, false);
	}

	public void restore()
	{
		if (!isHidden())
		{
			return;
		}

		ConfigWrites.write(configManager, GROUP, KEY, configManager.getConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY));

		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, SAVED_KEY);
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY);
	}

	private boolean isHidden()
	{
		return Boolean.parseBoolean(configManager.getConfiguration(BossHealthBarConfig.GROUP, HIDDEN_KEY));
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.data.DamageNumberSource;
import com.ghordrin.bosshealthbar.tracking.DamageTracker;
import com.ghordrin.bosshealthbar.tracking.OpponentTracker;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;

// Shares your hits on the current opponent with your RuneLite party, so members who count party
// damage can add them to their number.
@Singleton
public class PartyDamage
{
	private final Client client;
	private final BossHealthBarConfig config;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final OpponentTracker opponentTracker;
	private final DamageTracker damageTracker;

	@Inject
	PartyDamage(Client client, BossHealthBarConfig config, PartyService partyService, WSClient wsClient,
		OpponentTracker opponentTracker, DamageTracker damageTracker)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.opponentTracker = opponentTracker;
		this.damageTracker = damageTracker;
	}

	public void startUp()
	{
		wsClient.registerMessage(BossBarPartyHit.class);
	}

	public void shutDown()
	{
		wsClient.unregisterMessage(BossBarPartyHit.class);
	}

	public void sendHit(Actor target, int damage)
	{
		if (damage <= 0 || !(target instanceof NPC) || !partyService.isInParty())
		{
			return;
		}
		partyService.send(new BossBarPartyHit(client.getWorld(), ((NPC) target).getIndex(), damage));
	}

	public boolean countsPartyHits()
	{
		return config.damageNumberSource() == DamageNumberSource.PARTY && partyService.isInParty();
	}

	public void onPartyHit(BossBarPartyHit hit)
	{
		if (!countsPartyHits())
		{
			return;
		}

		final PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == hit.getMemberId())
		{
			return;
		}

		final Actor opponent = opponentTracker.getOpponent();
		if (opponent instanceof NPC && ((NPC) opponent).getIndex() == hit.getNpcIndex() && client.getWorld() == hit.getWorld())
		{
			damageTracker.recordPartyHit(hit.getDamage(), client.getTickCount());
		}
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.google.common.annotations.VisibleForTesting;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.Text;

// Reads the defence the "Better Party Defence" or "Party Defence Tracker" plugin shows in its info box,
// and the magic defence from Better Party Defence.
@Slf4j
@Singleton
public class PartyDefence
{
	private static final String PLUGIN_NAME = "Party Defence Tracker";
	private static final String BETTER_PLUGIN_NAME = "Better Party Defence";
	// InfoBox.getName() defaults to the plugin's class name and the info box's class name.
	@VisibleForTesting
	static final String BOX_NAME = "DefenceTrackerPlugin_DefenceInfoBox";
	@VisibleForTesting
	static final String BETTER_BOX_NAME = "BetterPartyDefencePlugin_DefenceInfoBox";

	@Value
	public static class Reading
	{
		String text;
		Color color;
	}

	private final Client client;
	private final BossHealthBarConfig config;
	private final InfoBoxManager infoBoxManager;
	private final SkillIconManager skillIconManager;
	private final PluginReader plugin;
	private final PluginReader betterPlugin;
	private final PluginReader.ReadFailure readFailure;

	private boolean available;
	private boolean magicAvailable;
	private final PluginReader.HeldReading<Reading> defence = new PluginReader.HeldReading<>();
	private final PluginReader.HeldReading<Reading> magic = new PluginReader.HeldReading<>();
	public BufferedImage icon;
	public BufferedImage magicIcon;
	private final MagicIconMatcher magicIconMatcher = new MagicIconMatcher();
	private SpritePixels magicOverrideSource;
	private BufferedImage magicOverrideImage;

	@Inject
	PartyDefence(Client client, BossHealthBarConfig config, PluginManager pluginManager, InfoBoxManager infoBoxManager,
		SkillIconManager skillIconManager, DebugLog debugLog)
	{
		this.client = client;
		this.config = config;
		this.infoBoxManager = infoBoxManager;
		this.skillIconManager = skillIconManager;
		this.plugin = new PluginReader(pluginManager, PLUGIN_NAME);
		this.betterPlugin = new PluginReader(pluginManager, BETTER_PLUGIN_NAME);
		this.readFailure = new PluginReader.ReadFailure(debugLog, "Couldn't read party defence info box");
	}

	public void invalidatePlugin()
	{
		plugin.invalidate();
		betterPlugin.invalidate();
	}

	public void reset()
	{
		invalidatePlugin();
		available = false;
		magicAvailable = false;
		defence.clear();
		magic.clear();
		magicIconMatcher.reset();
		magicOverrideSource = null;
		magicOverrideImage = null;
	}

	// Called each game tick, so the overlay doesn't go through the info boxes every frame.
	public void update(Actor opponent)
	{
		final boolean pluginActive = plugin.isActive();
		final boolean betterPluginActive = betterPlugin.isActive();
		available = (pluginActive || betterPluginActive) && config.showPartyDefence();
		magicAvailable = betterPluginActive && config.showMagicDefence();

		final String name = opponent != null ? opponent.getName() : null;
		if (!available || name == null)
		{
			defence.clear();
		}
		if (!magicAvailable || name == null)
		{
			magic.clear();
		}
		if (name == null || !available && !magicAvailable)
		{
			return;
		}

		try
		{
			final List<InfoBox> infoBoxes = infoBoxManager.getInfoBoxes();
			final Predicate<BufferedImage> isMagic = betterPluginActive ? magicTest() : image -> false;
			if (available)
			{
				defence.accept(name, select(infoBoxes, name, betterPluginActive, isMagic));
			}
			if (magicAvailable)
			{
				magic.accept(name, findBetterMagic(infoBoxes, isMagic));
			}
			readFailure.succeeded();
		}
		catch (RuntimeException e)
		{
			readFailure.failed(log, e);
			defence.clear();
			magic.clear();
		}
	}

	private Predicate<BufferedImage> magicTest()
	{
		final BufferedImage skillImage = skillIconManager.getSkillImage(Skill.MAGIC);
		final Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		final SpritePixels override = overrides != null ? overrides.get(SpriteID.Staticons.MAGIC) : null;
		if (override != magicOverrideSource)
		{
			magicOverrideSource = override;
			magicOverrideImage = override != null ? override.toBufferedImage() : null;
		}
		final BufferedImage overrideImage = magicOverrideImage;
		return image -> magicIconMatcher.isMagic(image, skillImage, overrideImage);
	}

	public boolean isAvailable()
	{
		return available;
	}

	public boolean isMagicAvailable()
	{
		return magicAvailable;
	}

	public Reading readingFor(Actor opponent)
	{
		return opponent != null ? defence.readingFor(opponent.getName()) : null;
	}

	public Reading magicReadingFor(Actor opponent)
	{
		return opponent != null ? magic.readingFor(opponent.getName()) : null;
	}

	public BufferedImage icon()
	{
		if (icon == null)
		{
			icon = skillIconManager.getSkillImage(Skill.DEFENCE, true);
		}
		return icon;
	}

	public BufferedImage magicIcon()
	{
		if (magicIcon == null)
		{
			magicIcon = skillIconManager.getSkillImage(Skill.MAGIC, true);
		}
		return magicIcon;
	}

	@VisibleForTesting
	static Reading find(List<InfoBox> infoBoxes, String opponentName)
	{
		for (InfoBox infoBox : infoBoxes)
		{
			if (!matches(infoBox, opponentName))
			{
				continue;
			}
			final Reading reading = reading(infoBox);
			if (reading != null)
			{
				return reading;
			}
		}
		return null;
	}

	// Better Party Defence removes the other plugin's boxes while it runs, so its box wins when it's on.
	@VisibleForTesting
	static Reading select(List<InfoBox> infoBoxes, String opponentName, boolean betterPluginActive,
		Predicate<BufferedImage> isMagic)
	{
		return betterPluginActive ? findBetter(infoBoxes, isMagic) : find(infoBoxes, opponentName);
	}

	// Its tooltip doesn't name the NPC, so the reading is for whichever NPC that plugin tracks.
	@VisibleForTesting
	static Reading findBetter(List<InfoBox> infoBoxes, Predicate<BufferedImage> isMagic)
	{
		final List<InfoBox> boxes = betterBoxes(infoBoxes);
		final InfoBox magicBox = magicBox(boxes, isMagic);
		for (InfoBox box : boxes)
		{
			if (box != magicBox)
			{
				return reading(box);
			}
		}
		return null;
	}

	@VisibleForTesting
	static Reading findBetterMagic(List<InfoBox> infoBoxes, Predicate<BufferedImage> isMagic)
	{
		final InfoBox magicBox = magicBox(betterBoxes(infoBoxes), isMagic);
		return magicBox != null ? reading(magicBox) : null;
	}

	// The Defence and Magic defence boxes share a name and can be added in either order, so only the image
	// tells them apart. A box that isn't recognised as Magic is taken as Defence.
	private static InfoBox magicBox(List<InfoBox> boxes, Predicate<BufferedImage> isMagic)
	{
		for (InfoBox box : boxes)
		{
			if (isMagic.test(box.getImage()))
			{
				return box;
			}
		}
		return null;
	}

	private static List<InfoBox> betterBoxes(List<InfoBox> infoBoxes)
	{
		final List<InfoBox> boxes = new ArrayList<>(2);
		for (InfoBox infoBox : infoBoxes)
		{
			if (infoBox != null && BETTER_BOX_NAME.equals(infoBox.getName()))
			{
				boxes.add(infoBox);
			}
		}
		return boxes;
	}

	private static Reading reading(InfoBox infoBox)
	{
		final String text = infoBox.getText();
		return text != null && !text.isEmpty() ? new Reading(text, infoBox.getTextColor()) : null;
	}

	@VisibleForTesting
	static boolean matches(InfoBox infoBox, String opponentName)
	{
		if (infoBox == null || opponentName == null || !BOX_NAME.equals(infoBox.getName()))
		{
			return false;
		}
		final String tooltip = infoBox.getTooltip();
		return tooltip != null && Text.removeTags(tooltip).trim().equalsIgnoreCase(Text.removeTags(opponentName).trim());
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.debug.DebugLog;
import java.util.Objects;
import net.runelite.client.plugins.PluginManager;
import org.slf4j.Logger;

// Whether another plugin this one reads from is on. Checked once, then kept until invalidate.
class PluginReader
{
	private final PluginManager pluginManager;
	private final String name;
	private Boolean active;

	PluginReader(PluginManager pluginManager, String name)
	{
		this.pluginManager = pluginManager;
		this.name = name;
	}

	boolean isActive()
	{
		if (active == null)
		{
			active = PluginState.isActive(pluginManager, name);
		}
		return active;
	}

	void invalidate()
	{
		active = null;
	}

	// A broken info box fails every tick, so the debug log gets it once until a read works again.
	static class ReadFailure
	{
		private final DebugLog debugLog;
		private final String message;
		private boolean logged;

		ReadFailure(DebugLog debugLog, String message)
		{
			this.debugLog = debugLog;
			this.message = message;
		}

		void failed(Logger log, RuntimeException e)
		{
			log.debug(message, e);
			if (!logged)
			{
				logged = true;
				debugLog.add(message + ": {}", e.toString());
			}
		}

		void succeeded()
		{
			logged = false;
		}
	}

	// The other plugin's info boxes can be gone for a tick while they're rebuilt, so the last reading is kept
	// for one tick, as long as it's still for the same key.
	static class HeldReading<T>
	{
		private Object key;
		private T reading;
		private boolean missedTick;

		// A null reading means none was found this tick.
		void accept(Object key, T found)
		{
			if (found != null)
			{
				// An unchanged reading keeps the old instance, so callers can compare by identity.
				if (!found.equals(reading))
				{
					reading = found;
				}
				this.key = key;
				missedTick = false;
			}
			else if (reading != null && !missedTick && Objects.equals(key, this.key))
			{
				missedTick = true;
			}
			else
			{
				clear();
			}
		}

		T reading()
		{
			return reading;
		}

		T readingFor(Object key)
		{
			return key != null && key.equals(this.key) ? reading : null;
		}

		void clear()
		{
			key = null;
			reading = null;
			missedTick = false;
		}
	}
}

package com.ghordrin.bosshealthbar.integrations;

import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

public final class PluginState
{
	private PluginState()
	{
	}

	public static Plugin find(PluginManager pluginManager, String name)
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (name.equals(plugin.getName()))
			{
				return plugin;
			}
		}
		return null;
	}

	static boolean isActive(PluginManager pluginManager, String name)
	{
		final Plugin plugin = find(pluginManager, name);
		return plugin != null && pluginManager.isPluginActive(plugin);
	}
}

package com.ghordrin.bosshealthbar.integrations;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
