	// A titled block of rows, built the way the client's own config sections are, which the header folds away.
	private JPanel section(String title, boolean open, Consumer<JPanel> rows)
	{
		final JPanel section = new JPanel();
		section.setBackground(ColorScheme.DARK_GRAY_COLOR);
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setMinimumSize(new Dimension(PANEL_WIDTH, 0));

		final JPanel header = new JPanel();
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setLayout(new BorderLayout());
		header.setMinimumSize(new Dimension(PANEL_WIDTH, 0));
		header.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(0, 0, 3, 1)));

		final JButton toggle = new JButton();
		setToggleIcon(toggle, open);
		SwingUtil.removeButtonDecorations(toggle);
		toggle.setPreferredSize(new Dimension(18, 0));
		toggle.setBorder(new EmptyBorder(0, 0, 0, 5));
		toggle.setToolTipText(open ? "Retract" : "Expand");
		header.add(toggle, BorderLayout.WEST);

		final JLabel name = new JLabel(title);
		name.setForeground(ColorScheme.BRAND_ORANGE);
		name.setFont(FontManager.getRunescapeBoldFont());
		header.add(name, BorderLayout.CENTER);

		final JPanel contents = new JPanel();
		contents.setBackground(ColorScheme.DARK_GRAY_COLOR);
		contents.setLayout(new DynamicGridLayout(0, 1, 0, 5));
		contents.setMinimumSize(new Dimension(PANEL_WIDTH, 0));
		contents.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(BORDER_OFFSET, 0, BORDER_OFFSET, 0)));
		contents.setVisible(open);

		// The whole header folds the section, not only the arrow, which is a small target.
		final MouseAdapter click = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggleSection(toggle, contents);
			}
		};
		toggle.addActionListener(e -> toggleSection(toggle, contents));
		name.addMouseListener(click);
		header.addMouseListener(click);

		section.add(header);
		section.add(contents);
		rows.accept(contents);
		return section;
	}

	private void toggleSection(JButton toggle, JPanel contents)
	{
		final boolean open = !contents.isVisible();
		contents.setVisible(open);
		setToggleIcon(toggle, open);
		toggle.setToolTipText(open ? "Retract" : "Expand");
		SwingUtilities.invokeLater(contents::revalidate);
	}

	// Without the client's arrow, a plain sign still says which way the section goes.
	private void setToggleIcon(JButton toggle, boolean open)
	{
		final ImageIcon icon = open ? sectionRetractIcon : sectionExpandIcon;
		if (icon != null)
		{
			toggle.setIcon(icon);
		}
		else
		{
			toggle.setText(open ? "-" : "+");
		}
	}

	private JPanel row(JPanel parent, String label, String tooltip)
	{
		final JPanel row = new JPanel();
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setLayout(new BorderLayout());
		row.setMinimumSize(new Dimension(PANEL_WIDTH, 0));

		final JLabel text = new JLabel(label);
		text.setForeground(Color.WHITE);
		text.setToolTipText("<html>" + label + ":<br>" + tooltip + "</html>");

		row.add(text, BorderLayout.CENTER);
		parent.add(row);
		return row;
	}

	private void checkbox(JPanel parent, String label, String tooltip, String key, BooleanSupplier value)
	{
		final JCheckBox box = new JCheckBox();
		box.setFocusable(false);
		box.setSelected(value.getAsBoolean());
		box.addActionListener(e ->
		{
			if (!refreshing)
			{
				write(key, box.isSelected());
			}
		});
		row(parent, label, tooltip).add(box, BorderLayout.EAST);
		refreshers.add(() -> box.setSelected(value.getAsBoolean()));
	}

	private <T extends Enum<T>> void combo(JPanel parent, String label, String tooltip, String key, Class<T> type,
		Supplier<T> value)
	{
		final JComboBox<T> box = new JComboBox<>(type.getEnumConstants());
		// Set before it is measured: the renderer builds the entries the preferred width is taken from.
		box.setRenderer(listCellRenderer);
		box.setPreferredSize(new Dimension(box.getPreferredSize().width, COMBO_HEIGHT));
		box.setFocusable(false);
		box.setSelectedItem(value.get());
		box.addItemListener(e ->
		{
			if (!refreshing && e.getStateChange() == ItemEvent.SELECTED)
			{
				write(key, box.getSelectedItem());
			}
		});
		row(parent, label, tooltip).add(box, BorderLayout.EAST);
		refreshers.add(() -> box.setSelectedItem(value.get()));
	}

	private void spinner(JPanel parent, String label, String tooltip, String key, int min, int max, IntSupplier value)
	{
		final JSpinner spinner = new JSpinner(new SpinnerNumberModel(value.getAsInt(), min, max, 1));
		final JFormattedTextField field = ((JSpinner.DefaultEditor) spinner.getEditor()).getTextField();
		field.setColumns(SPINNER_FIELD_WIDTH);
		spinner.addChangeListener(e ->
		{
			if (!refreshing)
			{
				write(key, spinner.getValue());
			}
		});
		row(parent, label, tooltip).add(spinner, BorderLayout.EAST);
		refreshers.add(() -> spinner.setValue(value.getAsInt()));
	}

	// Every color here can be transparent, so the swatch and the hex beside it both carry the alpha.
	private void color(JPanel parent, String label, String tooltip, String key, Supplier<Color> value)
	{
		final ColorJButton button = new ColorJButton(hex(value.get()), value.get());
		button.setFocusable(false);
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				final RuneliteColorPicker picker = colorPickerManager.create(
					SwingUtilities.getWindowAncestor(BossHealthBarPanel.this), button.getColor(), label, false);
				picker.setLocationRelativeTo(button);
				picker.setOnColorChange(chosen ->
				{
					button.setColor(chosen);
					button.setText(hex(chosen));
				});
				picker.setOnClose(chosen -> write(key, chosen));
				picker.setVisible(true);
			}
		});
		row(parent, label, tooltip).add(button, BorderLayout.EAST);
		refreshers.add(() ->
		{
			button.setColor(value.get());
			button.setText(hex(value.get()));
		});
	}

	private static String hex(Color color)
	{
		return "#" + ColorUtil.colorToAlphaHexCode(color).toUpperCase();
	}

	// An action rather than a setting, so it takes a row of its own instead of sitting beside a label.
	private void button(JPanel parent, String label, String tooltip, Runnable onClick)
	{
		final JButton button = new JButton(label);
		button.setToolTipText(tooltip);
		button.setFocusable(false);
		button.addActionListener(e -> onClick.run());

		final JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setMinimumSize(new Dimension(PANEL_WIDTH, 0));
		row.setBorder(new EmptyBorder(BORDER_OFFSET, 0, 0, 0));
		row.add(button, BorderLayout.CENTER);
		parent.add(row);
	}

	private void write(String key, Object value)
	{
		writingKey = key;
		try
		{
			ConfigWrites.write(configManager, key, value);
		}
		finally
		{
			writingKey = null;
		}
	}

	// A setting changed somewhere else: the config screen, a theme filling in the colors, an import, or the
	// Oldschool tick writing its companions. Everything is put back, since one change can move several. Those
	// follow-up writes arrive while this panel's own write is still running, so only that one key is skipped.
	public void settingsChanged(String key)
	{
		if (writingKey != null && writingKey.equals(key))
		{
			return;
		}

		SwingUtilities.invokeLater(() ->
		{
			refreshing = true;
			try
			{
				for (Runnable refresher : refreshers)
				{
					refresher.run();
				}
			}
			finally
			{
				refreshing = false;
			}
		});
	}

	// Keeps the rows at the panel's width however wide their contents would like to be, so a long dropdown
	// entry doesn't stretch the panel and leave every row scrolling sideways.
	private static class FixedWidthPanel extends JPanel
	{
		FixedWidthPanel()
		{
			setBackground(ColorScheme.DARK_GRAY_COLOR);
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(PANEL_WIDTH, super.getPreferredSize().height);
		}
	}

	// Carries the plugin for the event that opens its settings, and is never added to anything or drawn.
	private static class PluginOverlay extends Overlay
	{
		PluginOverlay(BossHealthBarPlugin plugin)
		{
			super(plugin);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			return null;
		}
	}
}

package com.ghordrin.bosshealthbar.render;

import java.time.Duration;

public final class BarAnimation
{
	private static final Duration TRAIL_HOLD = Duration.ofMillis(800);
	private static final float TRAIL_CATCH_UP_RATE = 3.5f;
	private static final float TRAIL_MIN_DRAIN_PER_SECOND = 0.15f;
	private static final Duration FADE_IN_DURATION = Duration.ofMillis(300);
	private static final int INTRO_SLIDE_DISTANCE = 14;
	private static final Duration INTRO_SLIDE_DURATION = Duration.ofMillis(400);
	private static final Duration INTRO_EXPAND_DELAY = Duration.ofMillis(80);
	private static final Duration INTRO_EXPAND_DURATION = Duration.ofMillis(400);
	private static final Duration INTRO_FILL_DELAY = Duration.ofMillis(380);
	private static final Duration INTRO_FILL_DURATION = Duration.ofMillis(450);
	private static final Duration INTRO_TEXT_DELAY = Duration.ofMillis(400);
	private static final Duration INTRO_TEXT_DURATION = Duration.ofMillis(250);
	static final Duration DEFEAT_HOLD = Duration.ofMillis(1600);
	static final Duration DEFEAT_FADE = Duration.ofMillis(700);
	private static final Duration LOW_HEALTH_PULSE_PERIOD = Duration.ofMillis(1100);
	// The bar waits before it reacts, so the change reads as an answer to the phase and not as part of the
	// hit that brought it on. The colors are held back over that wait and arrive under the flash.
	static final Duration FORTIFY_DELAY = Duration.ofMillis(180);
	static final Duration FORTIFY_FLASH = Duration.ofMillis(90);
	static final Duration FORTIFY_SWEEP = Duration.ofMillis(520);
	static final Duration FORTIFY_BADGE_DELAY = Duration.ofMillis(600);
	static final Duration FORTIFY_BADGE = Duration.ofMillis(300);
	private static final Duration FORTIFY_DURATION = Duration.ofMillis(900);

	private float displayedFraction = -1f;
	private float trailFraction = -1f;
	private float actualFraction = -1f;
	private long lastRenderNanos;
	private long fadeStartNanos;
	private long defeatStartNanos;
	private long defeatFirstStartNanos;
	private boolean snapToTarget;
	public boolean skipIntro;
	private int phaseKey;
	private long fortifyStartNanos;
	private boolean fortifyFromNoPhase;

	public void reset()
	{
		displayedFraction = -1f;
		trailFraction = -1f;
		actualFraction = -1f;
		fadeStartNanos = 0;
		defeatStartNanos = 0;
		defeatFirstStartNanos = 0;
		snapToTarget = false;
		skipIntro = false;
		phaseKey = 0;
		fortifyStartNanos = 0;
		fortifyFromNoPhase = false;
	}

	// The game put the boss into another phase, or took it out of one. Entering plays the run; leaving only
	// drops the colors, since the end of a phase shouldn't be as loud as its start.
	public void fortify(long now, int key)
	{
		if (key == phaseKey)
		{
			return;
		}
		fortifyFromNoPhase = phaseKey == 0;
		phaseKey = key;
		fortifyStartNanos = key == 0 ? 0 : now;
	}

	// How far the run has got, or -1 once it is over and the phase is just being shown.
	public long fortifyMillis(long now)
	{
		if (fortifyStartNanos == 0)
		{
			return -1;
		}
		final long elapsed = (now - fortifyStartNanos) / 1_000_000L;
		return elapsed > FORTIFY_DURATION.toMillis() ? -1 : Math.max(0, elapsed);
	}

	// Whether the phase's colors are still being held back. Only on the way in from no phase at all: between
	// two phases there are colors to hold, and dropping to the theme's for a moment would read as a flicker.
	public boolean fortifyHoldsPhase(long now)
	{
		final long elapsed = fortifyMillis(now);
		return fortifyFromNoPhase && elapsed >= 0 && elapsed < FORTIFY_DELAY.toMillis();
	}

	// The next bar shows up fully drawn, as if its intro had already played.
	public void skipIntro()
	{
		skipIntro = true;
	}

	// The next tick jumps straight to the new health without replaying the intro, and without
	// showing the difference from the old target as a damage trail.
	public void retarget()
	{
		snapToTarget = true;
	}

	public void resetFrameTime()
	{
		lastRenderNanos = 0;
	}

	public void tick(float targetFraction, float healSpeed, boolean showTrail, long lastHitMillis)
	{
		long now = System.nanoTime();
		float dt = lastRenderNanos == 0 ? 0f : Math.min(0.25f, (now - lastRenderNanos) / 1_000_000_000f);
		lastRenderNanos = now;
		actualFraction = targetFraction;

		if (displayedFraction < 0f)
		{
			displayedFraction = targetFraction;
			trailFraction = targetFraction;
			fadeStartNanos = skipIntro ? 0 : now;
			snapToTarget = false;
			skipIntro = false;
			return;
		}

		if (snapToTarget)
		{
			displayedFraction = targetFraction;
			trailFraction = targetFraction;
			snapToTarget = false;
			return;
		}

		if (targetFraction < displayedFraction)
		{
			displayedFraction = targetFraction;
		}
		else
		{
			displayedFraction += (targetFraction - displayedFraction) * Math.min(1f, dt * healSpeed);
			if (Math.abs(displayedFraction - targetFraction) < 0.001f)
			{
				displayedFraction = targetFraction;
			}
		}

		if (!showTrail || displayedFraction >= trailFraction)
		{
			trailFraction = displayedFraction;
			return;
		}

		if (lastHitMillis != 0 && System.currentTimeMillis() - lastHitMillis < TRAIL_HOLD.toMillis())
		{
			return;
		}

		final float gap = trailFraction - displayedFraction;
		trailFraction = Math.max(displayedFraction,
			trailFraction - Math.max(TRAIL_MIN_DRAIN_PER_SECOND, gap * TRAIL_CATCH_UP_RATE) * dt);
	}

	float getDisplayedFraction()
	{
		return displayedFraction;
	}

	float getTrailFraction()
	{
		return trailFraction;
	}

	float getActualFraction()
	{
		return actualFraction;
	}

	public boolean isDefeatPlaying()
	{
		return defeatStartNanos != 0;
	}

	public void startDefeat(long now)
	{
		defeatStartNanos = now;
		defeatFirstStartNanos = now;
	}

	public void cancelDefeat()
	{
		defeatStartNanos = 0;
		defeatFirstStartNanos = 0;
	}

	// Keeps a playing defeat at the end of its "Defeated" hold, so the fade only starts once this stops being called,
	// or once it has been held for maxHoldNanos.
	public void holdDefeat(long now, long maxHoldNanos)
	{
		if (defeatStartNanos != 0 && now - defeatStartNanos > DEFEAT_HOLD.toNanos()
			&& now - defeatFirstStartNanos < Math.max(DEFEAT_HOLD.toNanos(), maxHoldNanos))
		{
			defeatStartNanos = now - DEFEAT_HOLD.toNanos();
		}
	}

	// The whole bar's opacity, or -1 once the defeat animation is over. Burn away doesn't fade the whole bar.
	public float defeatOpacity(long now, boolean burnAway)
	{
		if (defeatStartNanos == 0)
		{
			return 1f;
		}

		final long elapsed = now - defeatStartNanos;
		final long hold = DEFEAT_HOLD.toNanos();
		final long duration = (burnAway ? BarEffects.BURN_DURATION : DEFEAT_FADE).toNanos();
		if (elapsed >= hold + duration)
		{
			return -1f;
		}

		return !burnAway && elapsed > hold ? 1f - (elapsed - hold) / (float) duration : 1f;
	}

	// Burn away fades the text around the bar on its own, as fast as the fade does.
	public float defeatTextOpacity(long now, boolean burnAway)
	{
		if (defeatStartNanos == 0 || !burnAway)
		{
			return 1f;
		}
		return 1f - progress(now - defeatStartNanos, DEFEAT_HOLD, DEFEAT_FADE);
	}

	// Time since the "Defeated" hold ended, negative before then or when no defeat is playing.
	public long defeatEffectMillis(long now)
	{
		if (defeatStartNanos == 0)
		{
			return -1;
		}
		return (now - defeatStartNanos - DEFEAT_HOLD.toNanos()) / 1_000_000L;
	}

	private long introElapsed(long now)
	{
		return fadeStartNanos == 0 ? Long.MAX_VALUE : now - fadeStartNanos;
	}

	public long introElapsedMillis(long now)
	{
		final long elapsed = introElapsed(now);
		return elapsed == Long.MAX_VALUE ? elapsed : elapsed / 1_000_000L;
	}

	public float fadeInOpacity(long now)
	{
		return progress(introElapsed(now), Duration.ZERO, FADE_IN_DURATION);
	}

	public int slideOffset(IntroAnimation intro, long now)
	{
		return intro.slide
			? Math.round(INTRO_SLIDE_DISTANCE * (1f - easeOut(progress(introElapsed(now), Duration.ZERO, INTRO_SLIDE_DURATION))))
			: 0;
	}

	public float expandProgress(IntroAnimation intro, long now)
	{
		return intro.expand ? easeOut(progress(introElapsed(now), INTRO_EXPAND_DELAY, INTRO_EXPAND_DURATION)) : 1f;
	}

	public float fillProgress(IntroAnimation intro, long now)
	{
		return intro.expand ? easeOut(progress(introElapsed(now), INTRO_FILL_DELAY, INTRO_FILL_DURATION)) : 1f;
	}

	public float textOpacity(IntroAnimation intro, long now)
	{
		return intro.expand ? progress(introElapsed(now), INTRO_TEXT_DELAY, INTRO_TEXT_DURATION) : 1f;
	}

	float lowHealthPulse(boolean defeated, boolean enabled, int thresholdPercent)
	{
		if (defeated || !enabled || displayedFraction <= 0f || displayedFraction > thresholdPercent / 100f)
		{
			return 0f;
		}

		final long period = LOW_HEALTH_PULSE_PERIOD.toNanos();
		final double phase = (System.nanoTime() % period) / (double) period * 2 * Math.PI;
		return (float) (0.5 - 0.5 * Math.cos(phase));
	}

	static float progress(long elapsedNanos, Duration delay, Duration duration)
	{
		return clamp01((elapsedNanos - delay.toNanos()) / (float) duration.toNanos());
	}

	static float easeOut(float t)
	{
		final float inverse = 1f - t;
		return 1f - inverse * inverse * inverse;
	}

	public static float clamp01(float value)
	{
		return Math.max(0f, Math.min(1f, value));
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.render.BarAnimation.clamp01;
import java.awt.Color;
import java.time.Duration;

public final class BarEffects
{
	static final Duration BURN_DURATION = Duration.ofMillis(1300);
	static final int BURN_SPARK_COUNT = 30;
	private static final int BURN_SEED = 13;

	private static final int COLOR_STEPS = 16;
	private static final Color[] SPARK_COLORS = fireColors(210, 80, 50);

	private BarEffects()
	{
	}

	static final class Particle
	{
		float x;
		float y;
		float size;
		float progress;
		float along;
	}

	static float easeIn(float t)
	{
		final float k = clamp01(t);
		return k * k;
	}

	// Deterministic noise in [0, 1), so particles move the same way every frame without being stored.
	static float random(int seed, int index)
	{
		int h = seed * 0x9E3779B1 + index * 0x85EBCA6B;
		h ^= h >>> 16;
		h *= 0x7FEB352D;
		h ^= h >>> 15;
		h *= 0x846CA68B;
		h ^= h >>> 16;
		return (h >>> 8) / (float) (1 << 24);
	}

	// along is how far the spark started along the burn (0 at the right end, 1 at the left), x and y are
	// offsets from there and from the middle of the bar. False before the spark is thrown and once it's out.
	static boolean burnSpark(int index, long burnMillis, Particle out)
	{
		final int base = index * 5;
		final float start = random(BURN_SEED, base);
		final float life = 400f + random(BURN_SEED, base + 1) * 400f;
		final float age = burnMillis - start * BURN_DURATION.toMillis();
		if (age < 0f || age > life)
		{
			return false;
		}

		final float k = age / life;
		out.along = easeIn(start);
		out.x = (random(BURN_SEED, base + 2) - 0.5f) * 16f * k;
		out.y = -(10f + random(BURN_SEED, base + 3) * 22f) * k;
		out.size = 1f + random(BURN_SEED, base + 4) * 1.5f;
		out.progress = k;
		return true;
	}

	public static float burnProgress(long millis)
	{
		return easeIn(millis / (float) BURN_DURATION.toMillis());
	}

	static Color sparkColor(float progress)
	{
		return SPARK_COLORS[Math.min(COLOR_STEPS - 1, (int) (clamp01(progress) * COLOR_STEPS))];
	}

	// Yellow-orange cooling to red as it fades out.
	private static Color[] fireColors(int startGreen, int endGreen, int blue)
	{
		final Color[] colors = new Color[COLOR_STEPS];
		for (int i = 0; i < COLOR_STEPS; i++)
		{
			final float k = i / (float) (COLOR_STEPS - 1);
			colors[i] = new Color(255, Math.round(startGreen + (endGreen - startGreen) * k), blue, Math.round(255 * (1f - k)));
		}
		return colors;
	}
}

