	private static final int BOTTOM_ROW = BarPosition.Row.BOTTOM.ordinal();
	private static final int BOTTOM_2_ROW = BarPosition.Row.BOTTOM_2.ordinal();

	// The items around the bar, most important first.
	static final int NAME = 0;
	static final int HITPOINTS = 1;
	static final int DAMAGE_NUMBER = 2;
	static final int FIGHT_TIMER = 3;
	static final int KILL_COUNT = 4;
	static final int PARTY_DEFENCE = 5;
	static final int MAGIC_DEFENCE = 6;
	static final int SPECIAL_ATTACKS = 7;
	static final int WEAKNESS = 8;
	static final int DRAIN_CAP = 9;
	static final int ITEM_COUNT = 10;

	private final DamageTracker damageTracker;
	private final BossHealthBarConfig config;
	private final BarFonts fonts;

	private final BarPosition[] positions = new BarPosition[ITEM_COUNT];
	private final boolean[] available = new boolean[ITEM_COUNT];
	private final BarLayout[] rows = new BarLayout[BarPosition.ROW_COUNT];
	private final int[] rowAbove = new int[ITEM_COUNT];
	private final int[] rowBelow = new int[ITEM_COUNT];
	private final int[] rowHeights = new int[BarPosition.ROW_COUNT];
	private final int[] rowBaselines = new int[BarPosition.ROW_COUNT];

	// What layoutText placed, for drawRow in the same frame.
	private final int[] baselines = new int[BarPosition.ROW_COUNT];
	private String nameText;
	private String levelText;
	private String delveText;
	private BufferedImage nameIcon;
	private String hitpointsText;
	private boolean defeated;
	private String defeatedText;
	private int defeatedX;
	private int previewDamage;
	private String fightTimeText;
	private int fightTimeWidth;
	private int fightTimeSlotWidth;
	private String sizedFightTime;
	private FontMetrics sizedFightTimeMetrics;
	private char widestDigit;
	private String killCountText;
	private PartyDefence.Reading defence;
	private BufferedImage scaledDefenceIcon;
	private int defenceIconWidth;
	private PartyDefence.Reading magicDefence;
	private BufferedImage scaledMagicIcon;
	private int magicIconWidth;
	private int arrowWidth;
	private List<SpecialAttackCounts.Reading> specialAttacks;
	private int specialAttackIconSize;
	private BufferedImage scaledDrainIcon;
	private int drainIconWidth;
	private String weaknessText;
	private BufferedImage weaknessIcon;
	private int weaknessIconWidth;
	private int weaknessIconHeight;
	private int weaknessIconPadding;
	private int weaknessIconAdvance;
	private String drainCapText;

	private final EllipsizedText ellipsizedName = new EllipsizedText();
	private final EllipsizedText partnerName = new EllipsizedText();

	private final ScaledIcon defenceIconCache = new ScaledIcon();
	private final ScaledIcon magicIconCache = new ScaledIcon();
	private final ScaledIcon drainIconCache = new ScaledIcon();

	private final Map<BufferedImage, BufferedImage> itemIcons = new IdentityHashMap<>();
	private int itemIconHeight;

	@Inject
	BarTextPainter(DamageTracker damageTracker, BossHealthBarConfig config)
	{
		this.damageTracker = damageTracker;
		this.config = config;
		this.fonts = new BarFonts(config);
		for (int row = 0; row < rows.length; row++)
		{
			rows[row] = new BarLayout(ITEM_COUNT);
		}
	}

	public void updateFonts()
	{
		fonts.updateFonts();
	}

	@VisibleForTesting
	BarFonts fonts()
	{
		return fonts;
	}

	public FontMetrics nameMetrics()
	{
		return fonts.metrics(NAME);
	}

	public void drawNameStyleText(Graphics2D graphics, String text, int x, int baseline, Color color)
	{
		fonts.useFont(graphics, NAME);
		drawShadowedText(graphics, text, x, baseline, color, 1f);
	}

	public void applyTextHints(Graphics2D graphics)
	{
		fonts.applyTextHints(graphics);
	}

	public void updateRows(boolean partyDefenceAvailable, boolean magicDefenceAvailable, boolean specialAttacksAvailable,
		boolean hasWeakness, boolean hasDrainCap)
	{
		positions[NAME] = config.namePosition();
		positions[HITPOINTS] = config.hitpointsPosition();
		positions[DAMAGE_NUMBER] = config.damageNumberPosition();
		positions[FIGHT_TIMER] = config.fightTimerPosition();
		positions[KILL_COUNT] = config.killCountPosition();
		positions[PARTY_DEFENCE] = config.partyDefencePosition();
		positions[MAGIC_DEFENCE] = config.partyDefencePosition();
		positions[SPECIAL_ATTACKS] = config.specialAttackCountsPosition();
		positions[WEAKNESS] = config.weaknessPosition();
		positions[DRAIN_CAP] = config.drainCapPosition();

		itemsAvailable(config, partyDefenceAvailable, magicDefenceAvailable, specialAttacksAvailable, hasWeakness,
			hasDrainCap, available);
		for (int item = 0; item < ITEM_COUNT; item++)
		{
			rowAbove[item] = fonts.above(item);
			rowBelow[item] = fonts.below(item);
		}
		if (config.showCombatLevel())
		{
			rowAbove[NAME] = Math.max(rowAbove[NAME], fonts.levelAbove());
			rowBelow[NAME] = Math.max(rowBelow[NAME], fonts.levelBelow());
		}
		for (int row = 0; row < rows.length; row++)
		{
			rowBaselines[row] = rowBaseline(positions, available, ROWS[row], rowAbove);
			rowHeights[row] = rowHeight(positions, available, ROWS[row], rowAbove, rowBelow);
		}
	}

	// Rows are sized from the settings rather than what's showing, so they don't jump during a fight.
	@VisibleForTesting
	static void itemsAvailable(BossHealthBarConfig config, boolean partyDefenceAvailable, boolean magicDefenceAvailable,
		boolean specialAttacksAvailable, boolean hasWeakness, boolean hasDrainCap, boolean[] available)
	{
		available[NAME] = config.showBossName();
		available[HITPOINTS] = config.hitpointsTextMode() != HitpointsTextMode.NONE || config.showDefeatAnimation();
		available[DAMAGE_NUMBER] = config.showDamageNumber();
		available[FIGHT_TIMER] = config.showFightTimer();
		available[KILL_COUNT] = config.showKillCount();
		available[PARTY_DEFENCE] = partyDefenceAvailable;
		available[MAGIC_DEFENCE] = magicDefenceAvailable;
		available[SPECIAL_ATTACKS] = specialAttacksAvailable;
		available[WEAKNESS] = hasWeakness;
		available[DRAIN_CAP] = hasDrainCap;
	}

	// Everything on a row shares one baseline, low enough for the tallest text.
	@VisibleForTesting
	static int rowBaseline(BarPosition[] positions, boolean[] available, BarPosition.Row row, int[] above)
	{
		int baseline = 0;
		for (int item = 0; item < ITEM_COUNT; item++)
		{
			if (available[item] && positions[item].getRow() == row)
			{
				baseline = Math.max(baseline, above[item]);
			}
		}
		return baseline;
	}

	@VisibleForTesting
	static int rowHeight(BarPosition[] positions, boolean[] available, BarPosition.Row row, int[] above, int[] below)
	{
		final int baseline = rowBaseline(positions, available, row, above);
		if (baseline == 0)
		{
			return 0;
		}
		int descent = 0;
		for (int item = 0; item < ITEM_COUNT; item++)
		{
			if (available[item] && positions[item].getRow() == row)
			{
				descent = Math.max(descent, below[item]);
			}
		}
		return baseline + descent;
	}

	@VisibleForTesting
	int rowBaseline(BarPosition.Row row)
	{
		return rowBaselines[row.ordinal()];
	}

	public int rowHeight(BarPosition.Row row)
	{
		return rowHeights[row.ordinal()];
	}

	// The partner bar's text row, in the same fonts as the main bar. Sized from the settings so it doesn't jump.
	public int partnerRowHeight()
	{
		return partnerRowHeight(available[NAME], available[HITPOINTS],
			fonts.above(NAME), fonts.below(NAME), fonts.above(HITPOINTS), fonts.below(HITPOINTS));
	}

	// The name and the hitpoints share a baseline, so the row fits whichever of the two shown fonts reaches furthest.
	@VisibleForTesting
	static int partnerRowHeight(boolean showName, boolean showHitpoints,
		int nameAbove, int nameBelow, int hitpointsAbove, int hitpointsBelow)
	{
		return partnerBaseline(showName, showHitpoints, nameAbove, hitpointsAbove)
			+ Math.max(showName ? nameBelow : 0, showHitpoints ? hitpointsBelow : 0);
	}

	@VisibleForTesting
	static int partnerBaseline(boolean showName, boolean showHitpoints, int nameAbove, int hitpointsAbove)
	{
		return Math.max(showName ? nameAbove : 0, showHitpoints ? hitpointsAbove : 0);
	}

	// Name on the left, hitpoints or "Defeated" on the right, between the bar's caps.
	public void drawPartnerRow(Graphics2D graphics, String name, String hitpointsText, boolean defeated, ThemeColors colors,
		int width, int capWidth, int top)
	{
		final int left = capWidth + TEXT_INSET;
		final int right = width - capWidth - TEXT_INSET;
		final int baseline = top + partnerBaseline(available[NAME], available[HITPOINTS],
			fonts.above(NAME), fonts.above(HITPOINTS));

		final String rightText = defeated ? (available[HITPOINTS] ? DEFEATED_TEXT : null) : hitpointsText;
		int nameRight = right;
		if (rightText != null)
		{
			fonts.useFont(graphics, HITPOINTS);
			final int textWidth = fonts.metrics(HITPOINTS).stringWidth(rightText);
			drawShadowedText(graphics, rightText, right - textWidth, baseline,
				defeated ? colors.getDefeatedText() : colors.getHitpointsText(), 1f);
			nameRight -= textWidth + LEVEL_GAP;
		}

		if (available[NAME] && name != null && nameRight > left)
		{
			fonts.useFont(graphics, NAME);
			drawShadowedText(graphics, partnerName.get(name, fonts.metrics(NAME), nameRight - left), left, baseline,
				colors.getText(), 1f);
		}
	}

	public void layoutText(String name, String shortName, int combatLevel, int delveLevel, BufferedImage nameIcon,
		String hitpointsText,
		boolean defeated, String defeatedText, int previewDamage, boolean showFightTime, String fightTimeText,
		String killCountText,
		PartyDefence.Reading defence,
		BufferedImage defenceIcon, PartyDefence.Reading magicDefence, BufferedImage magicIcon,
		List<SpecialAttackCounts.Reading> specialAttacks, String weaknessText,
		BufferedImage weaknessIcon, String drainCapText, int width, int capWidth, int barMiddle, int bottomTop)
	{
		final FontMetrics textMetrics = fonts.metrics(NAME);
		final int left = capWidth + TEXT_INSET;
		final int right = width - capWidth - TEXT_INSET;

		this.nameIcon = nameIcon;
		this.hitpointsText = hitpointsText;
		this.defeated = defeated;
		this.defeatedText = defeatedText != null ? defeatedText : DEFEATED_TEXT;
		this.previewDamage = previewDamage;
		this.fightTimeText = fightTimeText;
		this.killCountText = killCountText;
		this.defence = defence;
		this.magicDefence = magicDefence;
		this.specialAttacks = specialAttacks;
		this.weaknessText = weaknessText;
		this.weaknessIcon = weaknessIcon;
		this.drainCapText = drainCapText;

		for (BarLayout row : rows)
		{
			row.clear();
		}

		final boolean showName = config.showBossName();
		levelText = null;
		delveText = null;
		nameText = null;
		int nameFixedWidth = 0;
		final int ellipsisWidth = textMetrics.stringWidth(ELLIPSIS);
		if (showName)
		{
			if (nameIcon != null)
			{
				nameFixedWidth = headerIconSize(textMetrics) + HEADER_ICON_GAP;
			}
			if (config.showCombatLevel() && combatLevel > 0)
			{
				levelText = "LV " + combatLevel;
				nameFixedWidth += LEVEL_GAP + fonts.levelMetrics().stringWidth(levelText);
			}
			// The delve level keeps its room like the combat level, so the name gives way to it instead of it dropping.
			if (delveLevel > BarState.NO_DELVE_LEVEL)
			{
				delveText = DelveLevel.text(delveLevel);
				nameFixedWidth += LEVEL_GAP + textMetrics.stringWidth(delveText);
			}
			row(NAME).addKept(NAME, positions[NAME].getSpot(), nameFixedWidth + ellipsisWidth);
		}

		if (config.showDamageNumber())
		{
			add(DAMAGE_NUMBER, fonts.metrics(DAMAGE_NUMBER).stringWidth(DAMAGE_NUMBER_SIZING));
		}

		// While "Defeated" shows, the hitpoints keep their slot so the other items stay where they were.
		if (hitpointsText != null)
		{
			add(HITPOINTS, fonts.metrics(HITPOINTS).stringWidth(hitpointsText));
		}

		// The slot is kept before the first hit too, so the name doesn't get shorter when the time appears.
		if (showFightTime)
		{
			sizeFightTime(fightTimeText != null ? fightTimeText : EMPTY_FIGHT_TIME, fonts.metrics(FIGHT_TIMER));
			add(FIGHT_TIMER, fightTimeSlotWidth);
		}

		if (killCountText != null)
		{
			add(KILL_COUNT, fonts.metrics(KILL_COUNT).stringWidth(killCountText));
		}

		final int defenceIconSize = fonts.metrics(PARTY_DEFENCE).getAscent() + 1;
		scaledDefenceIcon = defence != null ? defenceIconCache.get(defenceIcon, defenceIconSize) : null;
		defenceIconWidth = scaledDefenceIcon != null ? scaledDefenceIcon.getWidth() + DEFENCE_GAP : 0;
		arrowWidth = Math.max(5, Math.round(fonts.metrics(PARTY_DEFENCE).getAscent() * 0.6f));
		if (defence != null)
		{
			add(PARTY_DEFENCE, defenceIconWidth + arrowWidth + DEFENCE_GAP
				+ fonts.metrics(PARTY_DEFENCE).stringWidth(defence.getText()));
		}

		scaledMagicIcon = magicDefence != null ? magicIconCache.get(magicIcon, defenceIconSize) : null;
		magicIconWidth = scaledMagicIcon != null ? scaledMagicIcon.getWidth() + DEFENCE_GAP : 0;
		if (magicDefence != null)
		{
			add(MAGIC_DEFENCE, magicIconWidth + arrowWidth + DEFENCE_GAP
				+ fonts.metrics(MAGIC_DEFENCE).stringWidth(magicDefence.getText()));
		}

		specialAttackIconSize = itemIconSize(fonts.metrics(SPECIAL_ATTACKS));
		if (!specialAttacks.isEmpty())
		{
			add(SPECIAL_ATTACKS, specialAttacksEnd(specialAttacks, fonts.metrics(SPECIAL_ATTACKS), 0, specialAttackIconSize));
		}

		weaknessIconHeight = weaknessIcon != null && weaknessIcon.getHeight() > 0 ? itemIconSize(fonts.metrics(WEAKNESS)) : 0;
		weaknessIconWidth = weaknessIconHeight > 0
			? Math.round(weaknessIcon.getWidth() * weaknessIconHeight / (float) weaknessIcon.getHeight()) : 0;
		weaknessIconPadding = (weaknessIconWidth - Math.round(weaknessIconWidth / RUNE_ICON_SCALE)) / 2;
		weaknessIconAdvance = weaknessIconWidth > 0 ? weaknessIconWidth - weaknessIconPadding * 2 + DEFENCE_GAP : 0;
		if (weaknessText != null)
		{
			add(WEAKNESS, weaknessIconAdvance + fonts.metrics(WEAKNESS).stringWidth(weaknessText));
		}

		// The drain limit shows the Defence icon too, at its own size.
		scaledDrainIcon = drainCapText != null ? drainIconCache.get(defenceIcon, fonts.metrics(DRAIN_CAP).getAscent() + 1) : null;
		drainIconWidth = scaledDrainIcon != null ? scaledDrainIcon.getWidth() + DEFENCE_GAP : 0;
		if (drainCapText != null)
		{
			add(DRAIN_CAP, drainIconWidth + fonts.metrics(DRAIN_CAP).stringWidth(drainCapText));
		}

		for (BarLayout row : rows)
		{
			row.layout(width, left, right, LEVEL_GAP);
		}

		// The name never drops out. It's laid out at its shortest first, so the items sharing its row keep
		// their space, then gets whatever room is left and is laid out again at the width it ends up with.
		if (showName)
		{
			final BarLayout nameRow = row(NAME);
			final int nameRoom = ellipsisWidth + nameRow.room(NAME);
			nameText = ellipsizedName.get(fittedName(name, shortName, textMetrics, nameRoom), textMetrics, nameRoom);
			nameRow.setWidth(NAME, nameFixedWidth + textMetrics.stringWidth(nameText));
			nameRow.layout(width, left, right, LEVEL_GAP);
		}

		defeatedX = defeated
			? row(HITPOINTS).centredX(fonts.metrics(HITPOINTS).stringWidth(this.defeatedText), HITPOINTS) : BarLayout.NOT_PLACED;

		baselines[TOP_ROW] = rowBaselines[TOP_ROW];
		// The in-bar row is centred on the bar, so it straddles a bar shorter than its text.
		baselines[IN_BAR_ROW] = barMiddle - rowHeights[IN_BAR_ROW] / 2 + rowBaselines[IN_BAR_ROW];
		baselines[BOTTOM_ROW] = bottomTop + rowBaselines[BOTTOM_ROW];
		baselines[BOTTOM_2_ROW] = bottomTop + rowHeights[BOTTOM_ROW] + rowBaselines[BOTTOM_2_ROW];
	}

	// A boss with a short name uses it only once the full name no longer fits, so a wide bar still spells it out.
	// Anything that still doesn't fit is ellipsized after this.
	@VisibleForTesting
	static String fittedName(String name, String shortName, FontMetrics metrics, int room)
	{
		return shortName == null || metrics.stringWidth(name) <= room ? name : shortName;
	}

	// How far the in-bar row reaches past a bar shorter than its text. The overlay keeps that much room free.
	@VisibleForTesting
	public static int inBarOverflow(int inBarHeight, int barHeight)
	{
		return Math.max(0, inBarHeight - barHeight);
	}

	// Item images have a transparent border around the rune or weapon, so draw them larger to match the skill icon.
	@VisibleForTesting
	static int itemIconSize(FontMetrics metrics)
	{
		return Math.round((metrics.getAscent() + 1) * RUNE_ICON_SCALE);
	}

	public void drawRow(Graphics2D graphics, BarPosition.Row row, ThemeColors colors)
	{
		final int baseline = baselines[row.ordinal()];

		if (onRow(NAME, row))
		{
			final FontMetrics textMetrics = fonts.metrics(NAME);
			int x = x(NAME);
			if (nameIcon != null)
			{
				x = drawHeaderIcon(graphics, nameIcon, textMetrics, x, baseline);
			}
			fonts.useFont(graphics, NAME);
			drawShadowedText(graphics, nameText, x, baseline, colors.getText(), 1f);
			int after = x + textMetrics.stringWidth(nameText);
			if (levelText != null)
			{
				fonts.useLevelFont(graphics);
				after += LEVEL_GAP;
				drawShadowedText(graphics, levelText, after, baseline, colors.getCombatLevelText(), 0.9f);
				after += fonts.levelMetrics().stringWidth(levelText);
			}
			// Last in the row, in the name's font, since the level belongs to the name rather than to the stats.
			if (delveText != null)
			{
				fonts.useFont(graphics, NAME);
				drawShadowedText(graphics, delveText, after + LEVEL_GAP, baseline, colors.getDelveLevelText(), 1f);
			}
		}

		if (onRow(DAMAGE_NUMBER, row))
		{
			drawDamageNumber(graphics, fonts.metrics(DAMAGE_NUMBER), row(DAMAGE_NUMBER), baseline, previewDamage, colors.getDamageText());
		}

		fonts.useFont(graphics, HITPOINTS);
		if (defeated)
		{
			if (defeatedX != BarLayout.NOT_PLACED && positions[HITPOINTS].getRow() == row)
			{
				drawShadowedText(graphics, defeatedText, defeatedX, baseline, colors.getDefeatedText(), 1f);
			}
		}
		else if (onRow(HITPOINTS, row))
		{
			drawShadowedText(graphics, hitpointsText, x(HITPOINTS), baseline, colors.getHitpointsText(), 1f);
		}

		if (fightTimeText != null && onRow(FIGHT_TIMER, row))
		{
			fonts.useFont(graphics, FIGHT_TIMER);
			final BarLayout timerRow = row(FIGHT_TIMER);
			drawShadowedText(graphics, fightTimeText, damageNumberX(timerRow.spot(FIGHT_TIMER), timerRow.x(FIGHT_TIMER),
				fightTimeSlotWidth, fightTimeWidth), baseline, colors.getFightTimerText(), 0.9f);
		}

		if (onRow(KILL_COUNT, row))
		{
			fonts.useFont(graphics, KILL_COUNT);
			drawShadowedText(graphics, killCountText, x(KILL_COUNT), baseline, colors.getKillCountText(), 0.9f);
		}

		final int defenceAscent = fonts.metrics(PARTY_DEFENCE).getAscent();
		if (onRow(PARTY_DEFENCE, row))
		{
			fonts.useFont(graphics, PARTY_DEFENCE);
			drawDefence(graphics, defence, scaledDefenceIcon, defenceIconWidth, arrowWidth, defenceAscent,
				x(PARTY_DEFENCE), baseline, colors);
		}

		if (onRow(MAGIC_DEFENCE, row))
		{
			fonts.useFont(graphics, MAGIC_DEFENCE);
			drawDefence(graphics, magicDefence, scaledMagicIcon, magicIconWidth, arrowWidth, defenceAscent,
				x(MAGIC_DEFENCE), baseline, colors);
		}

		if (onRow(SPECIAL_ATTACKS, row))
		{
			fonts.useFont(graphics, SPECIAL_ATTACKS);
			drawSpecialAttacks(graphics, specialAttacks, fonts.metrics(SPECIAL_ATTACKS), specialAttackIconSize,
				x(SPECIAL_ATTACKS), baseline, colors);
		}

		if (onRow(WEAKNESS, row))
		{
			int x = x(WEAKNESS);
			if (weaknessIconWidth > 0)
			{
				drawScaled(graphics, weaknessIcon, x - weaknessIconPadding,
					baseline - fonts.metrics(WEAKNESS).getAscent() / 2 - weaknessIconHeight / 2, weaknessIconWidth, weaknessIconHeight);
				x += weaknessIconAdvance;
			}
			fonts.useFont(graphics, WEAKNESS);
			drawShadowedText(graphics, weaknessText, x, baseline, colors.getWeaknessText(), 0.9f);
		}

		if (onRow(DRAIN_CAP, row))
		{
			int x = x(DRAIN_CAP);
			if (scaledDrainIcon != null)
			{
				graphics.drawImage(scaledDrainIcon, x,
					baseline - fonts.metrics(DRAIN_CAP).getAscent() / 2 - scaledDrainIcon.getHeight() / 2, null);
				x += drainIconWidth;
			}
			fonts.useFont(graphics, DRAIN_CAP);
			drawShadowedText(graphics, drainCapText, x, baseline, colors.getDrainCapText(), 0.9f);
		}
	}

	private BarLayout row(int item)
	{
		return rows[positions[item].getRow().ordinal()];
	}

	private void add(int item, int width)
	{
		row(item).add(item, positions[item].getSpot(), width);
	}

	private boolean onRow(int item, BarPosition.Row row)
	{
		return positions[item].getRow() == row && x(item) != BarLayout.NOT_PLACED;
	}

	private int x(int item)
	{
		return row(item).x(item);
	}

	private static int headerIconSize(FontMetrics textMetrics)
	{
		return textMetrics.getAscent() + 1;
	}

	private int drawHeaderIcon(Graphics2D graphics, BufferedImage icon, FontMetrics textMetrics, int left, int baseline)
	{
		final int ascent = textMetrics.getAscent();
		final int size = headerIconSize(textMetrics);
		// Centred on the capital letters, which take up roughly the top 70% of the ascent.
		final int top = baseline - Math.round(ascent * 0.35f) - size / 2;
		drawScaled(graphics, icon, left, top, size, size);
		return left + size + HEADER_ICON_GAP;
	}

	private void drawDefence(Graphics2D graphics, PartyDefence.Reading defence, BufferedImage scaledIcon, int iconWidth,
		int arrowWidth, int ascent, int left, int baseline, ThemeColors colors)
	{
		final int arrowHeight = Math.max(3, Math.round(arrowWidth * 0.6f));
		final int middle = baseline - ascent / 2;
		int x = left;
		if (scaledIcon != null)
		{
			graphics.drawImage(scaledIcon, x, middle - scaledIcon.getHeight() / 2, null);
			x += iconWidth;
		}

		final int arrowTop = middle - arrowHeight / 2;
		final int[] xs = {x, x + arrowWidth, x + arrowWidth / 2};
		final int[] ys = {arrowTop, arrowTop, arrowTop + arrowHeight};
		final Object antialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final TextOutline edge = config.textOutline();
		if (edge == TextOutline.SHADOW)
		{
			graphics.translate(1, 1);
			graphics.setColor(TEXT_SHADOW);
			graphics.fillPolygon(xs, ys, 3);
			graphics.translate(-1, -1);
		}
		else if (edge == TextOutline.OUTLINE)
		{
			graphics.setColor(TEXT_EDGE);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx != 0 || dy != 0)
					{
						graphics.translate(dx, dy);
						graphics.fillPolygon(xs, ys, 3);
						graphics.translate(-dx, -dy);
					}
				}
			}
		}
		graphics.setColor(DEFENCE_ARROW);
		graphics.fillPolygon(xs, ys, 3);
		if (antialiasing != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialiasing);
		}
		x += arrowWidth + DEFENCE_GAP;

		final Color color = colors.defenceText(defence.getColor());
		drawShadowedText(graphics, defence.getText(), x, baseline, color, 1f);
	}

	private void drawSpecialAttacks(Graphics2D graphics, List<SpecialAttackCounts.Reading> readings, FontMetrics metrics,
		int iconHeight, int left, int baseline, ThemeColors colors)
	{
		final int middle = baseline - metrics.getAscent() / 2;
		int x = left;
		for (SpecialAttackCounts.Reading reading : readings)
		{
			final BufferedImage icon = reading.getImage();
			final int iconWidth = itemIconWidth(icon, iconHeight);
			final int iconPadding = itemIconPadding(iconWidth);
			final int iconAdvance = iconAdvance(icon, iconHeight);
			final int itemEnd = x + iconAdvance + metrics.stringWidth(reading.getText());

			if (iconWidth > 0)
			{
				final BufferedImage scaled = scaledItemIcon(icon, iconWidth, iconHeight);
				if (scaled != null)
				{
					graphics.drawImage(scaled, x - iconPadding, middle - iconHeight / 2, null);
				}
				x += iconAdvance;
			}

			final Color color = colors.specialAttackText(reading.getColor());
			drawShadowedText(graphics, reading.getText(), x, baseline, color, 1f);
			x = itemEnd + SPECIAL_ATTACK_GAP;
		}
	}

	@VisibleForTesting
	public static int specialAttacksEnd(List<SpecialAttackCounts.Reading> readings, FontMetrics metrics, int left, int iconHeight)
	{
		int end = left - SPECIAL_ATTACK_GAP;
		for (SpecialAttackCounts.Reading reading : readings)
		{
			end += SPECIAL_ATTACK_GAP + iconAdvance(reading.getImage(), iconHeight) + metrics.stringWidth(reading.getText());
		}
		return end;
	}

	private static int itemIconWidth(BufferedImage icon, int iconHeight)
	{
		return icon != null && icon.getWidth() > 0 && icon.getHeight() > 0
			? Math.max(1, Math.round(icon.getWidth() * iconHeight / (float) icon.getHeight())) : 0;
	}

	private static int itemIconPadding(int iconWidth)
	{
		return (iconWidth - Math.round(iconWidth / RUNE_ICON_SCALE)) / 2;
	}

	private static int iconAdvance(BufferedImage icon, int iconHeight)
	{
		final int iconWidth = itemIconWidth(icon, iconHeight);
		return iconWidth > 0 ? iconWidth - itemIconPadding(iconWidth) * 2 + DEFENCE_GAP : 0;
	}

	private BufferedImage scaledItemIcon(BufferedImage icon, int width, int height)
	{
		if (height != itemIconHeight || itemIcons.size() > MAX_CACHED_ITEM_ICONS)
		{
			itemIcons.clear();
			itemIconHeight = height;
		}

		BufferedImage scaled = itemIcons.get(icon);
		// ItemManager hands out a blank image that fills in once the item has loaded, so that one isn't cached yet.
		if (scaled == null && hasVisiblePixel(icon))
		{
			scaled = ImageUtil.resizeImage(icon, width, height);
			itemIcons.put(icon, scaled);
		}
		return scaled;
	}

	private static boolean hasVisiblePixel(BufferedImage image)
	{
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static void drawScaled(Graphics2D graphics, BufferedImage icon, int x, int y, int width, int height)
	{
		final Object interpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		// Drawn scaled every frame, because ItemManager's image only fills in once the item has loaded.
		graphics.drawImage(icon, x, y, width, height, null);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation != null
			? interpolation : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
	}

	private static final class ScaledIcon
	{
		private BufferedImage source;
		private int height;
		private BufferedImage scaled;

		BufferedImage get(BufferedImage icon, int height)
		{
			if (icon == null || icon.getWidth() <= 0 || icon.getHeight() <= 0)
			{
				return null;
			}
			if (icon != source || height != this.height)
			{
				final int width = Math.max(1, Math.round(icon.getWidth() * height / (float) icon.getHeight()));
				scaled = icon.getHeight() == height ? icon : ImageUtil.resizeImage(icon, width, height);
				source = icon;
				this.height = height;
			}
			return scaled;
		}
	}

	private static final class EllipsizedText
	{
		private String source;
		private Font font;
		private int maxWidth;
		private String text;

		String get(String name, FontMetrics metrics, int maxWidth)
		{
			if (!name.equals(source) || metrics.getFont() != font || maxWidth != this.maxWidth)
			{
				text = ellipsize(name, metrics, maxWidth);
				source = name;
				font = metrics.getFont();
				this.maxWidth = maxWidth;
			}
			return text;
		}
	}

	private static String ellipsize(String text, FontMetrics metrics, int maxWidth)
	{
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		for (int end = text.length() - 1; end > 0; end--)
		{
			String candidate = text.substring(0, end).trim() + ELLIPSIS;
			if (metrics.stringWidth(candidate) <= maxWidth)
			{
				return candidate;
			}
		}
		return ELLIPSIS;
	}

	private void drawDamageNumber(Graphics2D graphics, FontMetrics metrics, BarLayout row, int baseline,
		int previewDamage, Color color)
	{
		int damage = previewDamage;
		float alpha = 1f;
		if (damage <= 0)
		{
			final long lastDamage = damageTracker.getLastDamageDealtMillis();
			damage = damageTracker.getComboDamage();
			if (lastDamage == 0 || damage <= 0)
			{
				return;
			}

			final long elapsed = System.currentTimeMillis() - lastDamage;
			final long window = DamageTracker.DISPLAY_HOLD.toMillis();
			if (elapsed >= window)
			{
				return;
			}

			if (elapsed > window - DAMAGE_NUMBER_FADE_MILLIS)
			{
				alpha = (window - elapsed) / (float) DAMAGE_NUMBER_FADE_MILLIS;
			}
		}

		final String text = String.valueOf(damage);
		fonts.useFont(graphics, DAMAGE_NUMBER);
		drawShadowedText(graphics, text, damageNumberX(row.spot(DAMAGE_NUMBER), row.x(DAMAGE_NUMBER),
			row.width(DAMAGE_NUMBER), metrics.stringWidth(text)), baseline, color, alpha);
	}

	// The number sits in a slot as wide as the widest usual number, against the side its spot is on.
	@VisibleForTesting
	static int damageNumberX(BarLayout.Spot spot, int slotX, int slotWidth, int textWidth)
	{
		switch (spot)
		{
			case LEFT:
				return slotX;
			case CENTER:
				return slotX + (slotWidth - textWidth) / 2;
			default:
				return slotX + slotWidth - textWidth;
		}
	}

	// The slot is sized as if every digit were the widest one, so the time doesn't shift as its digits change.
	private void sizeFightTime(String text, FontMetrics metrics)
	{
		if (metrics != sizedFightTimeMetrics)
		{
			widestDigit = widestDigit(metrics);
		}
		else if (text.equals(sizedFightTime))
		{
			return;
		}
		sizedFightTime = text;
		sizedFightTimeMetrics = metrics;
		fightTimeWidth = metrics.stringWidth(text);
		fightTimeSlotWidth = metrics.stringWidth(withDigits(text, widestDigit));
	}

	private static char widestDigit(FontMetrics metrics)
	{
		char widest = '0';
		for (char digit = '1'; digit <= '9'; digit++)
		{
			if (metrics.charWidth(digit) > metrics.charWidth(widest))
			{
				widest = digit;
			}
		}
		return widest;
	}

	@VisibleForTesting
	static String withDigits(String text, char digit)
	{
		final char[] chars = text.toCharArray();
		for (int i = 0; i < chars.length; i++)
		{
			if (chars[i] >= '0' && chars[i] <= '9')
			{
				chars[i] = digit;
			}
		}
		return new String(chars);
	}

	// Every edge style draws the text itself in the same place, so the setting never moves anything.
	private void drawShadowedText(Graphics2D graphics, String text, int x, int y, Color color, float alpha)
	{
		alpha = clamp01(alpha);
		final boolean opaque = alpha >= 1f;
		final TextOutline edge = config.textOutline();
		if (edge == TextOutline.SHADOW)
		{
			graphics.setColor(opaque ? TEXT_SHADOW : withAlpha(TEXT_SHADOW, Math.round(TEXT_SHADOW.getAlpha() * alpha)));
			graphics.drawString(text, x + 1, y + 1);
		}
		else if (edge == TextOutline.OUTLINE)
		{
			graphics.setColor(opaque ? TEXT_EDGE : withAlpha(TEXT_EDGE, Math.round(TEXT_EDGE.getAlpha() * alpha)));
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx != 0 || dy != 0)
					{
						graphics.drawString(text, x + dx, y + dy);
					}
				}
			}
		}
		graphics.setColor(opaque ? color : withAlpha(color, Math.round(255 * alpha)));
		graphics.drawString(text, x, y);
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.theme.ColorUtil.brighten;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.darken;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;

public class CrestRenderer
{
	public static final class Piece
	{
		public final BufferedImage image;
		public final int anchorX;
		public final int anchorY;

		public Piece(BufferedImage image, int anchorX, int anchorY)
		{
			this.image = image;
			this.anchorX = anchorX;
			this.anchorY = anchorY;
		}
	}

	public static final class Crest
	{
		public final Piece left;
		public final Piece right;
		public final int iconSize;

		public Crest(Piece left, Piece right, int iconSize)
		{
			this.left = left;
			this.right = right;
			this.iconSize = iconSize;
		}
	}

	private static final Color OUTLINE = new Color(8, 6, 6, 215);
	private static final Color SHADOW = new Color(0, 0, 0, 110);
	private static final Color GLINT = new Color(255, 255, 255, 150);
	private static final Color GEM_GLINT = new Color(255, 255, 255, 70);

	private static final float LONG_POINT = 1.38f;
	private static final float SHORT_POINT = 1.14f;
	private static final float POINT_VALLEY = 0.84f;
	private static final float BEVEL = 0.8f;
	private static final float WELL = 0.68f;
	private static final float ICON_OVER_WELL = 1.15f;

	private Color cachedColor;
	private Color cachedGlowColor;
	private float cachedBarHalfExtent;
	private Crest cached;

	public Crest getCrest(Color plateColor, Color glowColor, float barHalfExtent)
	{
		if (cached == null || !plateColor.equals(cachedColor) || !glowColor.equals(cachedGlowColor)
			|| barHalfExtent != cachedBarHalfExtent)
		{
			cached = build(plateColor, glowColor, barHalfExtent);
			cachedColor = plateColor;
			cachedGlowColor = glowColor;
			cachedBarHalfExtent = barHalfExtent;
		}
		return cached;
	}

	private static Crest build(Color plateColor, Color glowColor, float half)
	{
		final float reach = half + 3f;
		final float bound = reach * LONG_POINT + 1.5f;
		final Piece right = rasterise(-bound, -bound, bound, bound,
			g -> drawPlate(g, plateColor, glowColor, reach));
		final int iconSize = Math.round(reach * WELL * 2 * ICON_OVER_WELL);
		return new Crest(mirror(right), right, iconSize);
	}

	private static void drawPlate(Graphics2D g, Color plateColor, Color glowColor, float reach)
	{
		final Shape star = star(reach);
		shadow(g, star);
		metal(g, star, darken(plateColor, 0.15f), -reach * LONG_POINT, reach * LONG_POINT);

		final Shape rim = circle(reach);
		shadow(g, rim);
		metal(g, rim, plateColor, -reach, reach);

		final float bevelRadius = reach * BEVEL;
		g.setPaint(new GradientPaint(
			0, -bevelRadius, darken(plateColor, 0.6f),
			0, bevelRadius, brighten(plateColor, 0.35f)));
		g.fill(circle(bevelRadius));

		final float wellRadius = reach * WELL;
		final Shape well = circle(wellRadius);
		g.setPaint(new RadialGradientPaint(
			new Point2D.Float(0, -wellRadius * 0.2f), wellRadius * 1.1f,
			new float[]{0f, 0.55f, 1f},
			new Color[]{brighten(glowColor, 0.25f), darken(glowColor, 0.45f), darken(glowColor, 0.85f)}));
		g.fill(well);
		g.setStroke(new BasicStroke(0.6f));
		g.setColor(OUTLINE);
		g.draw(well);

		g.setColor(GEM_GLINT);
		g.fill(new Ellipse2D.Float(-wellRadius * 0.7f, -wellRadius * 0.85f, wellRadius * 0.9f, wellRadius * 0.55f));
		g.setStroke(new BasicStroke(0.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(GLINT);
		final float glintRadius = reach * 0.9f;
		g.draw(new Arc2D.Float(-glintRadius, -glintRadius, glintRadius * 2, glintRadius * 2, 105, 60, Arc2D.OPEN));
	}

	private static Shape star(float reach)
	{
		final Path2D.Float path = new Path2D.Float();
		for (int i = 0; i < 16; i++)
		{
			final double angle = Math.PI / 8 * i - Math.PI / 2;
			final float radius = i % 2 == 1 ? reach * POINT_VALLEY
				: i % 4 == 0 ? reach * LONG_POINT : reach * SHORT_POINT;
			final float x = (float) (Math.cos(angle) * radius);
			final float y = (float) (Math.sin(angle) * radius);
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static Shape circle(float radius)
	{
		return new Ellipse2D.Float(-radius, -radius, radius * 2, radius * 2);
	}

	private static Piece mirror(Piece piece)
	{
		final BufferedImage source = piece.image;
		final int width = source.getWidth();
		final int height = source.getHeight();
		final BufferedImage flipped = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = flipped.createGraphics();
		g.drawImage(source, width, 0, 0, height, 0, 0, width, height, null);
		g.dispose();
		final int logicalWidth = Math.round(width / BarPainter.RASTER_SCALE);
		return new Piece(flipped, logicalWidth - piece.anchorX, piece.anchorY);
	}

	private static Piece rasterise(float minX, float minY, float maxX, float maxY, Consumer<Graphics2D> painter)
	{
		final int pad = 2;
		final int anchorX = pad + (int) Math.ceil(-minX);
		final int anchorY = pad + (int) Math.ceil(-minY);
		final int width = anchorX + (int) Math.ceil(maxX) + pad;
		final int height = anchorY + (int) Math.ceil(maxY) + pad;

		final float rasterScale = BarPainter.RASTER_SCALE;
		final BufferedImage image = new BufferedImage(Math.round(width * rasterScale), Math.round(height * rasterScale),
			BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.scale(rasterScale, rasterScale);
		g.translate(anchorX, anchorY);
		painter.accept(g);
		g.dispose();
		return new Piece(image, anchorX, anchorY);
	}

	private static void shadow(Graphics2D g, Shape shape)
	{
		final AffineTransform base = g.getTransform();
		g.translate(0.8, 1.2);
		g.setColor(SHADOW);
		g.fill(shape);
		g.setTransform(base);
	}

	private static void metal(Graphics2D g, Shape shape, Color color, float top, float bottom)
	{
		g.setPaint(new GradientPaint(
			0, top, brighten(color, 0.5f),
			0, bottom, darken(color, 0.5f)));
		g.fill(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(OUTLINE);
		g.draw(shape);
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.render.BarAnimation.clamp01;
import static com.ghordrin.bosshealthbar.render.BarPainter.capRise;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.data.BarState;
import com.ghordrin.bosshealthbar.data.Health;
import com.ghordrin.bosshealthbar.gamebars.GameBossBar;
import com.ghordrin.bosshealthbar.theme.PhaseColors;
import com.ghordrin.bosshealthbar.theme.ThemeColors;
import com.google.common.annotations.VisibleForTesting;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;

// The second bar the game drives for a boss that carries something besides its health, such as an energy bar.
// Hiding the game's bar takes that one with it, so it is drawn again as a thin strip under the health, in the
// colors the game paints it in. It follows the game's bar and has nothing of its own to set, so there is no
// setting for it: it shows whenever the game shows one.
@Singleton
public class ExtraBar
{
	// The room left between the health bar and this one, tighter than the gap before another boss's bar since
	// this one belongs to the same boss.
	public static final int GAP = 2;

	@VisibleForTesting
	static final int MIN_THICKNESS = 3;
	private static final int THICKNESS_SHARE = 3;

	// drawBar reads the phase markers off a state and takes the fraction it fills to from the animation, so
	// one state with no markers serves every frame and nothing is allocated per frame.
	private static final BarState STATE = BarState.healthOnly(null, new Health(0, 1, true, null, false));

	private final BossHealthBarConfig config;
	private final BarPainter barPainter;
	private final GameBossBar gameBossBar;
	private final BarAnimation animation = new BarAnimation();

	@Inject
	private ExtraBar(BossHealthBarConfig config, BarPainter barPainter, GameBossBar gameBossBar)
	{
		this.config = config;
		this.barPainter = barPainter;
		this.gameBossBar = gameBossBar;
	}

	// The preview is a bar of our own making, so a boss being fought behind it doesn't put a strip on it.
	public boolean isLive(boolean preview)
	{
		return !preview && gameBossBar.showsExtraBar() && gameBossBar.extraMaxHealth() > 0;
	}

	// A share of the main bar's height, so the strip keeps its proportion whatever that height is set to.
	public static int thickness(int barHeight)
	{
		return Math.max(MIN_THICKNESS, Math.round(barHeight / (float) THICKNESS_SHARE));
	}

	// The room it takes, without the gap before it.
	public static int height(int barHeight, boolean flat, BarEnds ends)
	{
		final int thickness = thickness(barHeight);
		return capRise(thickness, flat, ends) * 2 + thickness;
	}

	public void reset()
	{
		animation.reset();
	}

	// top is where the room under the health bar starts, so the gap and this bar's own ends are kept here.
	public void draw(Graphics2D graphics, ThemeColors themeColors, int top, int shownWidth, int shownInset,
		int barHeight, float fillProgress, boolean flat, BarEnds ends)
	{
		animation.tick(fraction(gameBossBar.extraHealth(), gameBossBar.extraMaxHealth()), config.animationSpeed(),
			config.showDamageTrail(), 0);
		final int thickness = thickness(barHeight);
		graphics.translate(shownInset, 0);
		barPainter.drawBar(graphics, colors(themeColors), STATE, animation, false,
			top + GAP + capRise(thickness, flat, ends), shownWidth, thickness, fillProgress, false, flat, ends, false,
			false, -1);
		graphics.translate(-shownInset, 0);
	}

	@VisibleForTesting
	static float fraction(int current, int base)
	{
		return base <= 0 ? 0f : clamp01(current / (float) base);
	}

	// The game's own colors for this bar, which tell it apart from the health above it. They are this bar's
	// colors rather than a phase of the health, so the phase color setting and the fortify tint stay out of
	// it. A boss whose extra bar the game paints in the usual boss colors keeps the theme's.
	private ThemeColors colors(ThemeColors themeColors)
	{
		final PhaseColors colors = gameBossBar.extraBarColors();
		return colors != null ? colors.applyTo(themeColors, null, false) : themeColors;
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.theme.ColorUtil.brighten;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.withAlpha;
import com.ghordrin.bosshealthbar.theme.ThemeColors;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Named;

public class GoldBar
{
	static final Color GOLD = new Color(0xE0B84A);
	private static final int CHANCE = 250;
	private static final int DEVELOPER_CHANCE = 2;

	// Plays once, just after the intro animation has filled the bar.
	private static final long SHINE_DELAY_MILLIS = 850;
	private static final long SHINE_MILLIS = 900;
	private static final Color SHINE = new Color(255, 248, 225);

	private static final long SPARKLE_PERIOD_MILLIS = 1800;
	private static final float SPARKLE_VISIBLE = 0.35f;
	private static final Color SPARKLE = new Color(255, 246, 214);
	// x and y in crest radii from its centre, then a phase offset.
	private static final float[][] SPARKLES = {
		{-0.95f, -0.75f, 0f},
		{0.9f, -0.95f, 0.33f},
		{-0.15f, 1.05f, 0.66f},
	};

	private final Random random = new Random();
	private final int chance;

	private ThemeColors source;
	private ThemeColors gold;

	@Inject
	GoldBar(@Named("developerMode") boolean developerMode)
	{
		chance = developerMode ? DEVELOPER_CHANCE : CHANCE;
	}

	public boolean roll()
	{
		return random.nextInt(chance) == 0;
	}

	public ThemeColors colors(ThemeColors colors)
	{
		if (colors != source)
		{
			gold = gilded(colors);
			source = colors;
		}
		return gold;
	}

	static ThemeColors gilded(ThemeColors colors)
	{
		return colors.toBuilder()
			.frame(GOLD)
			.levelText(brighten(GOLD, 0.35f))
			.defeatedText(brighten(GOLD, 0.45f))
			.build();
	}

	public void drawShine(Graphics2D graphics, int x, int y, int width, int height, long barAgeMillis)
	{
		final long time = barAgeMillis - SHINE_DELAY_MILLIS;
		if (time < 0 || time >= SHINE_MILLIS || width <= 0)
		{
			return;
		}

		final float progress = time / (float) SHINE_MILLIS;
		final float band = Math.max(24f, height * 3f);
		final float centre = x - band + (width + band * 2) * progress;
		graphics.setPaint(new LinearGradientPaint(
			centre - band / 2, y, centre + band / 2, y + height,
			new float[]{0f, 0.5f, 1f},
			new Color[]{withAlpha(SHINE, 0), withAlpha(SHINE, 150), withAlpha(SHINE, 0)}));
		graphics.fillRect(x, y, width, height);
	}

	public void drawSparkles(Graphics2D graphics, float centreX, float centreY, float radius, boolean mirrored, long nowMillis)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final float cycle = (nowMillis % SPARKLE_PERIOD_MILLIS) / (float) SPARKLE_PERIOD_MILLIS;
		for (float[] sparkle : SPARKLES)
		{
			final float phase = (cycle + sparkle[2] + (mirrored ? 0.5f : 0f)) % 1f;
			if (phase >= SPARKLE_VISIBLE)
			{
				continue;
			}

			final float strength = (float) Math.sin(Math.PI * phase / SPARKLE_VISIBLE);
			final float x = centreX + (mirrored ? -sparkle[0] : sparkle[0]) * radius;
			final float y = centreY + sparkle[1] * radius;
			graphics.setColor(withAlpha(SPARKLE, Math.round(230 * strength)));
			graphics.fill(star(x, y, Math.max(1.5f, radius * 0.4f * strength)));
		}
	}

	private static Shape star(float x, float y, float size)
	{
		final float waist = size * 0.22f;
		final Path2D.Float path = new Path2D.Float();
		path.moveTo(x, y - size);
		path.lineTo(x + waist, y - waist);
		path.lineTo(x + size, y);
		path.lineTo(x + waist, y + waist);
		path.lineTo(x, y + size);
		path.lineTo(x - waist, y + waist);
		path.lineTo(x - size, y);
		path.lineTo(x - waist, y - waist);
		path.closePath();
		return path;
	}
}

package com.ghordrin.bosshealthbar.render;

import com.ghordrin.bosshealthbar.data.Health;

public final class HealthText
{
	public static final int MAX_DECIMALS = 2;
	private static final int[] POWERS_OF_TEN = {1, 10, 100};

	private HealthText()
	{
	}

	public static String hitpointsText(HitpointsTextMode mode, Health health, int decimals)
	{
		if (mode == HitpointsTextMode.NONE)
		{
			return null;
		}

		final String percentText = hitpointsPercent(health.ratio, health.scale, decimals) + "%";
		final String hpText = hitpointsPart(mode, health);

		if (hpText == null)
		{
			return percentText;
		}
		return mode.showsPercentage() ? hpText + "   " + percentText : hpText;
	}

	// Null when there is no hitpoints part to show, which a boss that only reports a percentage also means.
	private static String hitpointsPart(HitpointsTextMode mode, Health health)
	{
		if (mode.hitpoints() == HitpointsTextMode.Hitpoints.OFF
			|| health.maxHealth == null || health.percentOnly)
		{
			return null;
		}

		final int currentHealth = health.exactHealth
			? health.ratio : estimateHealth(health.ratio, health.scale, health.maxHealth);
		return mode.hitpoints() == HitpointsTextMode.Hitpoints.LEFT
			? String.valueOf(currentHealth) : currentHealth + " / " + health.maxHealth;
	}

	// Like the game's own bar, 0% and 100% are only shown when the opponent is really dead or full.
	static String hitpointsPercent(int ratio, int scale, int decimals)
	{
		final int places = Math.max(0, Math.min(MAX_DECIMALS, decimals));
		final int unit = POWERS_OF_TEN[places];
		long percent = Math.round(100.0 * unit * ratio / scale);
		if (ratio > 0 && ratio < scale)
		{
			percent = Math.max(1, Math.min(100L * unit - 1, percent));
		}
		if (places == 0)
		{
			return String.valueOf(percent);
		}
		return percent / unit + "." + String.valueOf(unit + percent % unit).substring(1);
	}

	// The game sends ratio = 1 + (scale - 1) * health / maxHealth, rounded down, for health above 0.
	// This returns the middle of the range of health values that give that ratio.
	static int estimateHealth(int ratio, int healthScale, int maxHealth)
	{
		if (ratio <= 0)
		{
			return 0;
		}

		int minHealth = 1;
		int maxHealthForRatio;
		if (healthScale > 1)
		{
			if (ratio > 1)
			{
				minHealth = (maxHealth * (ratio - 1) + healthScale - 2) / (healthScale - 1);
			}
			maxHealthForRatio = (maxHealth * ratio - 1) / (healthScale - 1);
			if (maxHealthForRatio > maxHealth)
			{
				maxHealthForRatio = maxHealth;
			}
		}
		else
		{
			maxHealthForRatio = maxHealth;
		}

		return (minHealth + maxHealthForRatio + 1) / 2;
	}
}

