package com.ghordrin.bosshealthbar.theme;

import com.google.common.primitives.Ints;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import lombok.Value;

// The Custom colors and icon as one short line of text, to pass around wherever text goes. The colors keep
// the order the Custom colors are listed in, so a color added later goes on the end and older codes still read.
public final class PaletteCode
{
	private static final String PREFIX = "bhb1:";
	// The bar and the four shared text colors, so a pasted code can't leave any of them unset.
	private static final int MIN_COLORS = 9;
	// The background, third in the Custom colors.
	private static final int TRACK_INDEX = 2;
	private static final int NO_ICON = -1;

	@Value
	public static class Palette
	{
		// Transparent where the code leaves a color to follow another one.
		List<Color> colors;
		int iconItemId;
		int iconSpriteId;
	}

	private PaletteCode()
	{
	}

	public static String encode(Collection<Color> colors, int iconItemId, int iconSpriteId)
	{
		final String code = PREFIX + colors.stream().map(PaletteCode::encode).collect(Collectors.joining("."));
		return iconSpriteId >= 0 ? code + ":s" + iconSpriteId : iconItemId > 0 ? code + ":i" + iconItemId : code;
	}

	// A fully transparent color is left empty, and an opaque one drops its alpha, which keeps codes short.
	private static String encode(Color color)
	{
		if (color == null || color.getAlpha() == 0)
		{
			return "";
		}
		final int argb = color.getRGB();
		return color.getAlpha() == 255
			? String.format("%06X", argb & 0xFFFFFF) : String.format("%08X", argb);
	}

	// Null when the text isn't a code. Spaces and line breaks around it, as chat and Discord add, are fine.
	public static Palette decode(String text)
	{
		if (text == null)
		{
			return null;
		}
		final String code = text.trim();
		if (!code.toLowerCase(Locale.ROOT).startsWith(PREFIX))
		{
			return null;
		}

		final String[] parts = code.substring(PREFIX.length()).split(":", -1);
		if (parts.length > 2)
		{
			return null;
		}

		final List<Color> colors = new ArrayList<>();
		for (String part : parts[0].split("\\.", -1))
		{
			final Color color = decodeColor(part);
			if (color == null)
			{
				return null;
			}
			colors.add(color);
		}
		if (colors.size() < MIN_COLORS)
		{
			return null;
		}
		// Among the colors every code carries, only the background may be left transparent.
		for (int i = 0; i < MIN_COLORS; i++)
		{
			if (i != TRACK_INDEX && colors.get(i).getAlpha() == 0)
			{
				return null;
			}
		}

		int itemId = NO_ICON;
		int spriteId = NO_ICON;
		if (parts.length == 2)
		{
			final String icon = parts[1];
			final Integer id = icon.length() > 1 ? Ints.tryParse(icon.substring(1)) : null;
			if (id == null || id < 0)
			{
				return null;
			}
			switch (Character.toLowerCase(icon.charAt(0)))
			{
				case 'i':
					itemId = id;
					break;
				case 's':
					spriteId = id;
					break;
				default:
					return null;
			}
		}
		return new Palette(colors, itemId, spriteId);
	}

	private static Color decodeColor(String part)
	{
		if (part.isEmpty())
		{
			return new Color(0, 0, 0, 0);
		}
		if ((part.length() != 6 && part.length() != 8) || !part.matches("[0-9A-Fa-f]+"))
		{
			return null;
		}
		final long value = Long.parseLong(part, 16);
		return part.length() == 6 ? new Color((int) value) : new Color((int) value, true);
	}
}

package com.ghordrin.bosshealthbar.theme;

import static com.ghordrin.bosshealthbar.theme.ColorUtil.brighten;
import java.awt.Color;

// The colors the game paints its own boss bar in. They are green until a boss shields itself or changes phase,
// when the game switches the whole bar to another hue. Our bar covers the game's, so it follows that switch to
// keep saying what the game was saying.
public final class PhaseColors
{
	private static final Color DEFAULT_FILL = new Color(0x00C800);
	private static final Color DEFAULT_TRAIL = new Color(0x009000);
	private static final Color DEFAULT_TRACK = new Color(0xC80000);

	private final Color fill;
	private final Color trail;
	private final Color track;

	private PhaseColors(Color fill, Color trail, Color track)
	{
		this.fill = fill;
		this.trail = trail;
		this.track = track;
	}

	// Null while the game paints the colors it uses for every boss, which are the ones our themes replace.
	// A bar that hasn't been filled in yet reads as black, and says nothing about a phase either.
	public static PhaseColors of(int fillRgb, int trailRgb, int trackRgb)
	{
		if ((fillRgb & 0xFFFFFF) == 0)
		{
			return null;
		}
		final Color fill = new Color(fillRgb);
		final Color trail = new Color(trailRgb);
		final Color track = new Color(trackRgb);
		if (DEFAULT_FILL.equals(fill) && DEFAULT_TRAIL.equals(trail) && DEFAULT_TRACK.equals(track))
		{
			return null;
		}
		return new PhaseColors(fill, trail, track);
	}

	// Tells one phase from another, so a bar going straight from one into the next counts as a change.
	// Zero is no phase at all, which no phase color can be: a bar reading black isn't one.
	public int key()
	{
		return fill.getRGB() & 0xFFFFFF;
	}

	// The text stays the theme's, so only what the game recolors is recolored here. An override is a single
	// color, so the trail and the track come off it the way a boss color's do. The frame is the theme's too
	// unless tintFrame asks for it, which only the ornate bar does: the flat one's frame is its outline.
	public ThemeColors applyTo(ThemeColors theme, Color override, boolean tintFrame)
	{
		final boolean chosen = override != null && override.getAlpha() > 0;
		final ThemeColors colors = chosen
			? ThemeColors.withBase(theme, override)
			: theme.toBuilder()
				.fillHigh(fill)
				.fillLow(fill)
				.trail(trail)
				.track(track)
				.build();
		if (!tintFrame)
		{
			return colors;
		}
		// A frame in the fill's own color disappears against the fill, so it is lifted off it.
		return colors.toBuilder().frame(brighten(chosen ? override : fill, 0.3f)).build();
	}
}

package com.ghordrin.bosshealthbar.theme;

import static com.ghordrin.bosshealthbar.theme.ColorUtil.brighten;
import java.awt.Color;
import lombok.AccessLevel;
import lombok.Builder;
import lombok.Getter;
import lombok.Value;

@Value
@Builder(toBuilder = true)
public class ThemeColors
{
	static final Color DEFAULT_TEXT = new Color(0xE8E2D4);
	static final Color DEFAULT_HITPOINTS_TEXT = new Color(0xC8C0B0);
	private static final float MIN_TRAIL_CONTRAST = 1.5f;
	private static final float MIN_TRACK_CONTRAST = 1.6f;

	Color fillHigh;
	Color fillLow;
	Color trail;
	// Plain color behind the fill. Null keeps the default dark track.
	Color track;

	Color frame;

	Color text;
	Color levelText;
	Color hitpointsText;
	Color defeatedText;

	// Each item's own text color. Null follows the name color or the level color, which only the Custom colors set.
	Color damageText;
	Color delveLevelText;
	Color combatLevelText;
	Color fightTimerText;
	Color killCountText;
	Color weaknessText;
	Color drainCapText;
	// Null keeps the color the other plugin gives these, or the name color when it gives none.
	@Getter(AccessLevel.NONE)
	Color defenceText;
	@Getter(AccessLevel.NONE)
	Color specialAttackText;

	public Color getDamageText()
	{
		return damageText != null ? damageText : text;
	}

	public Color getDelveLevelText()
	{
		return delveLevelText != null ? delveLevelText : text;
	}

	public Color getCombatLevelText()
	{
		return combatLevelText != null ? combatLevelText : levelText;
	}

	public Color getFightTimerText()
	{
		return fightTimerText != null ? fightTimerText : levelText;
	}

	public Color getKillCountText()
	{
		return killCountText != null ? killCountText : levelText;
	}

	public Color getWeaknessText()
	{
		return weaknessText != null ? weaknessText : levelText;
	}

	public Color getDrainCapText()
	{
		return drainCapText != null ? drainCapText : levelText;
	}

	public Color defenceText(Color pluginColor)
	{
		return defenceText != null ? defenceText : pluginColor != null ? pluginColor : text;
	}

	public Color specialAttackText(Color pluginColor)
	{
		return specialAttackText != null ? specialAttackText : pluginColor != null ? pluginColor : text;
	}

	static ThemeColors of(Color fillHigh, Color fillLow, Color frame, Color trail)
	{
		return ThemeColors.builder()
			.fillHigh(fillHigh)
			.fillLow(fillLow)
			.trail(trail)
			.frame(frame)
			.text(DEFAULT_TEXT)
			.levelText(brighten(frame, 0.35f))
			.hitpointsText(DEFAULT_HITPOINTS_TEXT)
			.defeatedText(brighten(frame, 0.45f))
			.build();
	}

	// Follows how the built-in themes relate their colors: a darker fill at low health that leans red
	// for warm colors, a pale trail of the same hue, and a dark frame tinted with it.
	public static ThemeColors fromBase(Color base)
	{
		final float[] hsb = Color.RGBtoHSB(base.getRed(), base.getGreen(), base.getBlue(), null);
		final float hue = hsb[0];
		final float saturation = hsb[1];
		final boolean grey = saturation < 0.12f;
		final boolean warm = hue >= 20f / 360f && hue <= 80f / 360f;

		final Color fillLow = Color.getHSBColor(hue + (warm ? -10f : 5f) / 360f,
			grey ? saturation : Math.min(1f, saturation * 1.03f + (saturation < 0.5f ? 0.14f : 0f)),
			hsb[2] * 0.68f);
		final Color frame = Color.getHSBColor(hue, grey ? 0.06f : 0.2f, 0.45f);
		return of(base, fillLow, frame, trailFor(base, hue, saturation));
	}

	// A flat theme drawn in the opponent's fill color. The frame and all the text stay the theme's, and the
	// track and trail only change when they would sit too close to that fill.
	public static ThemeColors withBase(ThemeColors flat, Color base)
	{
		final float[] hsb = Color.RGBtoHSB(base.getRed(), base.getGreen(), base.getBlue(), null);
		final Color track = flat.getTrack() != null && contrast(base, flat.getTrack()) < MIN_TRACK_CONTRAST
			? trackFor(base, hsb[0], hsb[1]) : flat.getTrack();
		final Color trail = contrast(flat.getTrail(), base) < MIN_TRAIL_CONTRAST
			? trailFor(base, hsb[0], hsb[1]) : flat.getTrail();
		return flat.toBuilder()
			.fillHigh(base)
			.fillLow(base)
			.track(track)
			.trail(trail)
			.build();
	}

	// The theme in an opponent's own colors, for each bar to follow the boss it shows.
	public static ThemeColors withBoss(ThemeColors themeColors, ThemeColors bossColors, boolean flat)
	{
		if (bossColors == null)
		{
			return themeColors;
		}
		// A flat bar keeps its own look and only takes the opponent's fill color.
		return flat ? withBase(themeColors, bossColors.getFillHigh()) : bossColors;
	}

	// The color's own hue at a low brightness, dark enough for the fill to stand out against it.
	private static Color trackFor(Color base, float hue, float saturation)
	{
		for (float brightness = 0.3f; brightness > 0f; brightness -= 0.05f)
		{
			final Color track = Color.getHSBColor(hue, saturation, brightness);
			if (contrast(base, track) >= MIN_TRACK_CONTRAST)
			{
				return track;
			}
		}
		return Color.BLACK;
	}

	private static Color trailFor(Color base, float hue, float saturation)
	{
		final Color pale = Color.getHSBColor(hue, Math.min(0.5f, saturation * 0.4f), 0.97f);
		return contrast(pale, base) < MIN_TRAIL_CONTRAST ? Color.getHSBColor(hue + 0.5f, 0.45f, 0.9f) : pale;
	}

	static float contrast(Color a, Color b)
	{
		final float la = luminance(a);
		final float lb = luminance(b);
		return (Math.max(la, lb) + 0.05f) / (Math.min(la, lb) + 0.05f);
	}

	private static float luminance(Color c)
	{
		return 0.2126f * linear(c.getRed()) + 0.7152f * linear(c.getGreen()) + 0.0722f * linear(c.getBlue());
	}

	private static float linear(int channel)
	{
		final float c = channel / 255f;
		return c <= 0.03928f ? c / 12.92f : (float) Math.pow((c + 0.055f) / 1.055f, 2.4f);
	}
}

