package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.data.Health;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.inject.Singleton;

// Opponents that went out of sight, kept by NPC index so the bar can carry on when they come back.
// The game only reuses an NPC's index once that NPC is gone, so the name is checked as well.
@Singleton
public class BossMemory
{
	static final int MAX_ENTRIES = 8;
	// 10 minutes and 60 seconds in game ticks.
	static final int FORGET_TICKS = 1000;
	static final int HOLD_TICKS = 100;
	// The game stops showing an NPC once its south-west tile is about 15 tiles away. Kills happen well inside that.
	static final int OUT_OF_SIGHT_DISTANCE = 15;
	// Health this much higher on return means the opponent healed or respawned, so it's a new fight.
	static final float HEALED_FRACTION = 0.2f;

	static final class Entry
	{
		final int index;
		final String name;
		final int tick;
		final FightTimer.Fight fight;
		Health health;

		Entry(int index, String name, int tick, FightTimer.Fight fight)
		{
			this.index = index;
			this.name = name;
			this.tick = tick;
			this.fight = fight;
		}
	}

	private final List<Entry> entries = new ArrayList<>(MAX_ENTRIES);

	Entry remember(int index, String name, int tick, FightTimer.Fight fight)
	{
		forget(index);
		if (entries.size() >= MAX_ENTRIES)
		{
			entries.remove(0);
		}
		final Entry entry = new Entry(index, name, tick, fight);
		entries.add(entry);
		return entry;
	}

	// Drops an entry whose index now belongs to a different NPC, and any that have expired.
	Entry find(int index, String name, int tick)
	{
		for (int i = entries.size() - 1; i >= 0; i--)
		{
			final Entry entry = entries.get(i);
			if (isExpired(entry.tick, tick))
			{
				entries.remove(i);
			}
			else if (entry.index == index)
			{
				if (Objects.equals(entry.name, name))
				{
					return entry;
				}
				entries.remove(i);
			}
		}
		return null;
	}

	Entry take(int index, String name, int tick)
	{
		final Entry entry = find(index, name, tick);
		if (entry != null)
		{
			entries.remove(entry);
		}
		return entry;
	}

	boolean contains(int index)
	{
		for (Entry entry : entries)
		{
			if (entry.index == index)
			{
				return true;
			}
		}
		return false;
	}

	void forget(int index)
	{
		for (int i = entries.size() - 1; i >= 0; i--)
		{
			if (entries.get(i).index == index)
			{
				entries.remove(i);
			}
		}
	}

	void clear()
	{
		entries.clear();
	}

	int size()
	{
		return entries.size();
	}

	static boolean isOutOfSight(boolean playerDied, int distance)
	{
		return !playerDied && distance >= OUT_OF_SIGHT_DISTANCE;
	}

	static int tileDistance(int npcX, int npcY, int x, int y)
	{
		return Math.max(Math.abs(x - npcX), Math.abs(y - npcY));
	}

	// An overhead 0 isn't always a kill, such as a stun meter that empties, so health coming back from it isn't a heal.
	public static boolean healedSince(int rememberedRatio, int rememberedScale, boolean rememberedExact, int ratio, int scale)
	{
		return rememberedScale > 0 && scale > 0 && (rememberedRatio > 0 || rememberedExact)
			&& ratio / (float) scale - rememberedRatio / (float) rememberedScale > HEALED_FRACTION;
	}

	static boolean isExpired(int rememberedTick, int tick)
	{
		return tick - rememberedTick > FORGET_TICKS;
	}

	static boolean isHeld(int rememberedTick, int tick)
	{
		return tick - rememberedTick <= HOLD_TICKS;
	}
}

package com.ghordrin.bosshealthbar.tracking;

import java.time.Duration;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

@Singleton
public class DamageTracker
{
	public static final Duration DISPLAY_HOLD = Duration.ofMillis(2500);
	static final Duration PARTY_WINDOW = Duration.ofMillis(2500);

	// Hits on the same or the next tick belong to one attack (multi-hit weapons and specs land a tick apart).
	private static final int MAX_TICK_GAP = 1;

	@Getter
	private long lastHitMillis;

	@Getter
	private int lastHitAmount;

	@Getter
	private int comboDamage;

	@Getter
	private long lastDamageDealtMillis;

	private int comboStartTick = FightTimer.NO_TICK;

	public void recordHit(Hitsplat hitsplat, int tick, boolean partyTotal)
	{
		if (hitsplat.getAmount() <= 0 || hitsplat.getHitsplatType() == HitsplatID.HEAL)
		{
			return;
		}

		final long now = System.currentTimeMillis();
		lastHitMillis = now;
		lastHitAmount = hitsplat.getAmount();

		// Party members' hits arrive over the party connection instead, so other players' hitsplats never count.
		if (hitsplat.isMine())
		{
			addToCombo(hitsplat.getAmount(), now, tick, partyTotal);
		}
	}

	public void recordPartyHit(int amount, int tick)
	{
		if (amount > 0)
		{
			addToCombo(amount, System.currentTimeMillis(), tick, true);
		}
	}

	// A party total keeps adding while hits keep coming; otherwise each attack gets its own number.
	void addToCombo(int amount, long now, int tick, boolean partyTotal)
	{
		final boolean continues = partyTotal
			? continuesPartyTotal(lastDamageDealtMillis, now)
			: isSameAttack(comboStartTick, tick);
		if (!continues)
		{
			comboDamage = 0;
			comboStartTick = tick;
		}
		comboDamage += amount;
		lastDamageDealtMillis = now;
	}

	static boolean continuesPartyTotal(long lastDamageMillis, long now)
	{
		return lastDamageMillis != 0 && now - lastDamageMillis <= PARTY_WINDOW.toMillis();
	}

	void resetCombo()
	{
		comboDamage = 0;
		lastDamageDealtMillis = 0;
		comboStartTick = FightTimer.NO_TICK;
	}

	public void reset()
	{
		lastHitMillis = 0;
		resetCombo();
	}

	// Measured from the first hit, so hits that keep landing a tick apart can't chain into one long total.
	static boolean isSameAttack(int startTick, int tick)
	{
		final int gap = tick - startTick;
		return startTick != FightTimer.NO_TICK && gap >= 0 && gap <= MAX_TICK_GAP;
	}
}

package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.data.BarState;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.google.common.annotations.VisibleForTesting;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;

// The delve level the game shows on its own bar. Read per update rather than once per opponent, since the level
// changes while the opponent stays the same.
@Singleton
public class DelveLevel
{
	private static final String DELVE_BOSS = "Doom of Mokhaiotl";

	private final Client client;
	private final DebugLog debugLog;

	// Starts below any reading, so a first reading of no delves done still logs.
	private int loggedDelvesDone = -1;

	@Inject
	DelveLevel(Client client, DebugLog debugLog)
	{
		this.client = client;
		this.debugLog = debugLog;
	}

	// The level to show for this opponent, or NO_DELVE_LEVEL when it has none. Named rather than matched by ID,
	// like the rest of the boss lookups, since each form has its own ID.
	public int forOpponent(String name)
	{
		if (name == null || !name.contains(DELVE_BOSS))
		{
			return BarState.NO_DELVE_LEVEL;
		}

		final int delvesDone = client.getVarpValue(VarPlayerID.DOM_CURRENT_LEVEL_TEMP);
		if (delvesDone != loggedDelvesDone)
		{
			loggedDelvesDone = delvesDone;
			debugLog.add("Delve level {}", levelFor(delvesDone));
		}
		return levelFor(delvesDone);
	}

	// The varp counts the delves finished this trip, so the level being fought is one past it: it reads 0 on
	// delve 1 and 1 on delve 2.
	@VisibleForTesting
	static int levelFor(int delvesDone)
	{
		return Math.max(delvesDone, 0) + 1;
	}

	public static String text(int level)
	{
		return "Delve " + level;
	}
}

package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.data.BarState;
import com.ghordrin.bosshealthbar.data.Health;
import com.ghordrin.bosshealthbar.data.NpcUtil;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;

// The NPCs that have been the opponent during the current fight, each with its last known health, so another boss
// fought at the same time can be shown under the main bar.
@Singleton
public class FightGroup
{
	static final int MAX_MEMBERS = 8;
	static final int NO_INDEX = -1;

	public static final class Member
	{
		// The NPC's index while it's in the scene, NO_INDEX while it's away.
		int index = NO_INDEX;
		NPC npc;
		String name;
		boolean bossLike;
		int lastEngagedTick;
		int lastSeenTick;
		int ratio = -1;
		int scale = -1;
		boolean exact;
		Integer maxHealth;
		// The last reading above 0, kept for a moment where the NPC has no reading or reads a 0 it can come back from.
		Health lastAboveZero;
		public BarState state;
		final HealthReader.DownState downState = new HealthReader.DownState();
		final HealthReader.Watch watch = new HealthReader.Watch();

		boolean isAway()
		{
			return index == NO_INDEX;
		}

		// For what the bar has to ask the game about this boss, such as the color its own bar paints it in.
		public NPC npc()
		{
			return npc;
		}

		// A confirmed kill, not just a 0 it can still come back from.
		public boolean isDead()
		{
			return downState.defeated;
		}
	}

	private final HealthReader healthReader;
	private final DebugLog debugLog;
	private final List<Member> members = new ArrayList<>(MAX_MEMBERS);
	private int nextId;
	private int id;
	private int bossLikeJoins;
	private Member partner;

	@Inject
	FightGroup(HealthReader healthReader, DebugLog debugLog)
	{
		this.healthReader = healthReader;
		this.debugLog = debugLog;
	}

	int id()
	{
		return id;
	}

	void startFight(Actor actor, boolean bossLike, int tick)
	{
		clear();
		debugLog.add("Fight group: new fight");
		join(actor, bossLike, tick);
	}

	void join(Actor actor, boolean bossLike, int tick)
	{
		if (!(actor instanceof NPC))
		{
			return;
		}
		final NPC npc = (NPC) actor;
		final String name = name(npc);
		final boolean known = find(npc.getIndex()) != null;
		final boolean back = !known && awayByName(name) != null;
		final Member member = join(npc.getIndex(), name, bossLike, tick);
		member.npc = npc;
		if (back)
		{
			debugLog.add("Fight group: {} back", DebugLog.describe(npc));
		}
		else if (!known)
		{
			debugLog.add("Fight group: {} joined ({} members)", DebugLog.describe(npc), members.size());
		}
	}

	// An opponent back from out of sight carries on the fight it was part of.
	void restore(int fightId, Actor actor, boolean bossLike, int tick)
	{
		if (fightId != id)
		{
			clearMembers();
			id = fightId;
		}
		join(actor, bossLike, tick);
	}

	// A returning NPC gets a new index, so a single away member with its name takes it back.
	Member join(int index, String name, boolean bossLike, int tick)
	{
		Member member = find(index);
		if (member == null)
		{
			member = awayByName(name);
			if (member != null)
			{
				member.index = index;
				member.watch.clear();
			}
		}
		if (member == null)
		{
			if (members.size() >= MAX_MEMBERS)
			{
				remove(leastRecentlyEngaged());
			}
			member = new Member();
			member.index = index;
			member.name = name;
			members.add(member);
		}
		if (bossLike && !member.bossLike)
		{
			member.bossLike = true;
			bossLikeJoins++;
		}
		member.lastEngagedTick = tick;
		member.lastSeenTick = tick;
		return member;
	}

	public boolean isAliveMember(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}
		final NPC npc = (NPC) actor;
		return isAliveMember(npc.getIndex(), name(npc));
	}

	// A member at 0 still counts until its kill is confirmed.
	public boolean isAliveMember(int index, String name)
	{
		Member member = find(index);
		if (member == null)
		{
			member = awayByName(name);
		}
		return member != null && !member.isDead();
	}

	public void onNpcDespawned(NPC npc)
	{
		final Member member = find(npc.getIndex());
		if (member == null)
		{
			return;
		}
		despawned(member, member.downState.down || npc.isDead() || diedReading(member, NpcUtil.isAttackable(npc)));
		if (member.isAway())
		{
			debugLog.add("Fight group: {} away, kept with its last health", DebugLog.describe(npc));
		}
	}

	// One that dies is gone, one that leaves alive is kept with its last health.
	void despawned(Member member, boolean died)
	{
		if (died || member.isDead())
		{
			remove(member);
		}
		else
		{
			member.index = NO_INDEX;
			member.npc = null;
		}
	}

	// A member back up after its kill was confirmed is the next one of its kind, so it starts without the dead one's
	// health or state.
	static boolean startNewLife(Member member)
	{
		if (!member.downState.takeRevived())
		{
			return false;
		}
		member.downState.clear();
		member.ratio = -1;
		member.scale = -1;
		member.exact = false;
		member.maxHealth = null;
		member.lastAboveZero = null;
		member.state = null;
		return true;
	}

	// Some turn into a form that can't be attacked as they die, before their bar reaches 0.
	static boolean diedReading(Member member, boolean attackable)
	{
		return member.scale > 0 && (member.ratio == 0 || !member.exact && member.ratio == 1 && !attackable);
	}

	public void onGameTick(Actor opponent, int tick)
	{
		for (Member member : members)
		{
			final NPC npc = member.npc;
			if (npc == null)
			{
				continue;
			}
			member.lastSeenTick = tick;
			rename(member, npc);
			final HealthReader.Reading reading = healthReader.read(npc);
			final boolean npcDead = npc.isDead();
			final boolean attackable = NpcUtil.isAttackable(npc);
			member.watch.log(debugLog, npc, reading, npcDead, attackable);
			member.downState.update(reading, npcDead, true, attackable, tick, debugLog, "Fight group: ", npc);
			startNewLife(member);
			read(member, reading != null ? reading.health : null);
		}
		expireAway(tick);
		final Member own = opponent instanceof NPC ? find(((NPC) opponent).getIndex()) : null;
		if (own != null)
		{
			own.lastEngagedTick = tick;
		}
		updatePartner(own, opponent != null);
	}

	// Away members are dropped once BossMemory would have forgotten them too.
	void expireAway(int tick)
	{
		for (int i = members.size() - 1; i >= 0; i--)
		{
			final Member member = members.get(i);
			if (member.isAway() && BossMemory.isExpired(member.lastSeenTick, tick))
			{
				remove(member);
			}
		}
	}

	// With no opponent for a moment, such as between two NPCs, the last partner stays.
	void updatePartner(Member own, boolean hasOpponent)
	{
		final Member next = hasOpponent ? choosePartner(own)
			: partner != null && members.contains(partner) && !partner.isDead() ? partner : null;
		if (next != partner)
		{
			partner = next;
			if (next != null)
			{
				debugLog.add("Second bar shows {}", next.npc != null ? DebugLog.describe(next.npc) : next.name + " (away)");
			}
		}
	}

	// The boss fought most recently besides the opponent, while it's alive and has health to show, even while away.
	Member choosePartner(Member own)
	{
		if (own == null || !own.bossLike)
		{
			return null;
		}
		Member best = null;
		for (Member member : members)
		{
			if (member != own && member.bossLike && !member.isDead() && member.scale > 0
				&& (best == null || member.lastEngagedTick > best.lastEngagedTick))
			{
				best = member;
			}
		}
		return best;
	}

	public Member partner()
	{
		return withHealth(partner);
	}

	// Two bosses fought in the same fight. Kept until the fight ends, so the bar doesn't move in the middle of it.
	public boolean isGroupFight()
	{
		return bossLikeJoins >= 2;
	}

	void clear()
	{
		clearMembers();
		id = ++nextId;
	}

	private void clearMembers()
	{
		members.clear();
		partner = null;
		bossLikeJoins = 0;
	}

	int size()
	{
		return members.size();
	}

	Member find(int index)
	{
		if (index == NO_INDEX)
		{
			return null;
		}
		for (Member member : members)
		{
			if (member.index == index)
			{
				return member;
			}
		}
		return null;
	}

	// The last health above 0 read for one NPC of this fight. Same NPC first, and since an NPC that left and came back
	// gets a new index, a single member with its name counts too.
	public Health rememberedHealth(int index, String name)
	{
		if (name == null)
		{
			return null;
		}
		Health byIndex = null;
		Member byName = null;
		int sameName = 0;
		for (Member member : members)
		{
			if (!name.equals(member.name))
			{
				continue;
			}
			if (member.index == index && index != NO_INDEX)
			{
				byIndex = member.lastAboveZero;
			}
			else
			{
				byName = member;
				sameName++;
			}
		}
		if (byIndex != null)
		{
			return byIndex;
		}
		return sameName == 1 ? byName.lastAboveZero : null;
	}

	// An NPC picked up again from memory brings its remembered health back, in case the fight it belonged to was
	// cleared while another one was fought.
	void restoreHealth(int index, Health health)
	{
		final Member member = find(index);
		if (member != null && member.lastAboveZero == null)
		{
			member.lastAboveZero = health;
		}
	}

	// Only a boss is taken back by name, and only when the name leaves no doubt which one it is.
	Member awayByName(String name)
	{
		if (name == null)
		{
			return null;
		}
		Member found = null;
		for (Member member : members)
		{
			if (member.isAway() && member.bossLike && !member.isDead() && name.equals(member.name))
			{
				if (found != null)
				{
					return null;
				}
				found = member;
			}
		}
		return found;
	}

	private Member leastRecentlyEngaged()
	{
		Member oldest = null;
		for (Member member : members)
		{
			if (oldest == null || member.lastEngagedTick < oldest.lastEngagedTick)
			{
				oldest = member;
			}
		}
		return oldest;
	}

	private void remove(Member member)
	{
		members.remove(member);
		if (member == partner)
		{
			partner = null;
		}
	}

	private static String name(NPC npc)
	{
		return npc.getName() != null ? Text.removeTags(npc.getName()) : null;
	}

	private static void rename(Member member, NPC npc)
	{
		final String name = name(npc);
		if (name != null && !name.equals(member.name))
		{
			member.name = name;
			member.state = null;
		}
	}

	private static Member withHealth(Member member)
	{
		if (member == null || member.scale <= 0)
		{
			return null;
		}
		if (member.state == null)
		{
			member.state = BarState.healthOnly(member.name,
				new Health(member.ratio, member.scale, member.exact, member.maxHealth, false));
		}
		return member;
	}

	// Without a reading the last one is kept, since the overhead bar of an NPC that isn't being hit soon goes away.
	static boolean read(Member member, Health health)
	{
		if (health == null || health.scale <= 0 || health.ratio < 0)
		{
			return false;
		}
		if (health.ratio > 0)
		{
			member.lastAboveZero = health;
		}
		if (member.ratio == health.ratio && member.scale == health.scale && member.exact == health.exactHealth
			&& Objects.equals(member.maxHealth, health.maxHealth))
		{
			return false;
		}
		member.ratio = health.ratio;
		member.scale = health.scale;
		member.exact = health.exactHealth;
		member.maxHealth = health.maxHealth;
		member.state = null;
		return true;
	}
}

package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.debug.DebugLog;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Constants;
import net.runelite.client.util.Text;

// How long the fight with the current opponent has lasted, counted in game ticks from when the player goes for it and
// is near it, or from the first hit on it if that comes first.
@Singleton
public class FightTimer
{
	public static final int NO_TICK = -1;
	// A boss that swaps to a new NPC between phases can be gone for a moment before the new one shows up.
	static final int SWAP_TICKS = 10;
	// Counted from the first 0: a despawn after that follows within a moment, past which the clock stops where it is.
	// It matches SWAP_TICKS today, so the clock stops on the last tick a return would still be the same fight, but the
	// two measure different things and either can be tuned on its own.
	static final int DEATH_TICKS = 10;
	// How far the game's time may sit from ours before it is about something else than this fight.
	static final int REPORT_GAP_TICKS = 100;

	// The wordings the game puts in front of a time it kept for a fight, and the time itself. Fight,
	// Challenge and Corrupted challenge duration all end in the same word, which stands for them all.
	// "Total completion time" is the exception: it is the time of everything before it, not of this fight.
	private static final Pattern REPORTED_TIME = Pattern.compile(
		"(?i)(?:duration:|subdued in|(?<!total )completion time:)"
			+ "\\s*(?:(\\d+):)?(\\d+):(\\d{2})(?:\\.(\\d{2}))?");

	static final class Fight
	{
		final int group;
		final int startTick;
		final int endTick;

		Fight(int group, int startTick, int endTick)
		{
			this.group = group;
			this.startTick = startTick;
			this.endTick = endTick;
		}
	}

	private final DebugLog debugLog;

	private Actor opponent;
	private boolean inFight;
	private int endTick = NO_TICK;
	private int clearedTick = NO_TICK;
	// Where the death sequence of a kill made in view began, i.e. the first 0 the opponent read.
	private int deadSince = NO_TICK;
	private Actor lastHitActor;
	private int lastHitTick = NO_TICK;

	// Identifies the current fight, or NO_TICK before it has started.
	@Getter
	private int startTick = NO_TICK;
	private int shownTicks = NO_TICK;
	@Getter
	private String text;
	@Getter
	private boolean preciseTiming;
	private int pendingReport = NO_TICK;
	private int pendingSince = NO_TICK;

	@Inject
	FightTimer(DebugLog debugLog)
	{
		this.debugLog = debugLog;
	}

	// Returns whether the fight carries on with the new opponent.
	boolean opponentChanged(Actor next, boolean aliveMember, boolean previousDefeated, int tick)
	{
		final boolean carried = opponentChanged(aliveMember, previousDefeated,
			next == lastHitActor ? lastHitTick : NO_TICK, tick);
		opponent = next;
		return carried;
	}

	// earlierHitTick is the latest hit on the new opponent from before it became the opponent, if any.
	// aliveMember is whether the new opponent was already fought in this fight and is still alive.
	boolean opponentChanged(boolean aliveMember, boolean previousDefeated, int earlierHitTick, int tick)
	{
		final boolean carried = keepsCounting(inFight, aliveMember, previousDefeated || endTick != NO_TICK, clearedTick,
			tick);
		if (carried)
		{
			debugLog.add("Fight timer carried over to the new opponent ({})", elapsedText(tick));
			if (aliveMember && endTick != NO_TICK)
			{
				endTick = NO_TICK;
				debugLog.add("Fight timer running again, the fight continues");
			}
		}
		else
		{
			if (startTick != NO_TICK)
			{
				debugLog.add("Fight timer: new fight, previous one cleared ({})", elapsedText(tick));
			}
			clearFight();
		}
		opponent = null;
		inFight = true;
		clearedTick = NO_TICK;
		// Whatever is the opponent now, it isn't the one that was defeated.
		deadSince = NO_TICK;
		if (startTick == NO_TICK)
		{
			startTick = recentHitTick(earlierHitTick, tick);
			if (startTick != NO_TICK)
			{
				debugLog.add("Fight timer started from a hit on tick {}", startTick);
			}
		}
		updateText(tick);
		return carried;
	}

	void opponentReturned(Actor next, Fight fight, int tick)
	{
		opponentReturned(fight, next == lastHitActor ? lastHitTick : NO_TICK, tick);
		opponent = next;
	}

	// An opponent that went out of sight carries on its own fight, whatever was fought in between.
	void opponentReturned(Fight fight, int earlierHitTick, int tick)
	{
		opponent = null;
		inFight = true;
		startTick = fight.startTick;
		endTick = fight.endTick;
		clearedTick = NO_TICK;
		deadSince = NO_TICK;
		if (startTick == NO_TICK && endTick == NO_TICK)
		{
			startTick = recentHitTick(earlierHitTick, tick);
		}
		debugLog.add("Fight timer resumed a remembered fight (start tick {}, end tick {})", startTick, endTick);
		updateText(tick);
	}

	void startOver(int tick)
	{
		debugLog.add("Fight timer started over (was {})", elapsedText(tick));
		startTick = tick;
		endTick = NO_TICK;
		deadSince = NO_TICK;
		updateText(tick);
	}

	public int getElapsedTicks(int tick)
	{
		return elapsedTicks(startTick, endTick, tick);
	}

	Fight save(int group)
	{
		return new Fight(group, startTick, endTick);
	}

	void opponentDespawned(boolean defeated, int tick)
	{
		opponentDespawned(defeated, tick, tick);
	}

	// defeatTick is when it was defeated, which can be before the despawn.
	void opponentDespawned(boolean defeated, int defeatTick, int tick)
	{
		if (defeated)
		{
			defeat(endOfFight(deadSince != NO_TICK ? deadSince : defeatTick, tick));
		}
		opponent = null;
		clearedTick = tick;
		updateText(tick);
	}

	// The opponent can be picked after the hit that started the fight, e.g. when the game's boss bar comes up.
	public void onCombatHit(Actor actor, int tick)
	{
		lastHitActor = actor;
		lastHitTick = tick;
		if (actor != null && actor == opponent)
		{
			onHit(tick);
		}
	}

	void onHit(int tick)
	{
		if (startTick == NO_TICK && endTick == NO_TICK)
		{
			startTick = tick;
			debugLog.add("Fight timer started");
			updateText(tick);
		}
	}

	void onEngaged(int tick)
	{
		if (inFight && startTick == NO_TICK && endTick == NO_TICK)
		{
			startTick = tick;
			debugLog.add("Fight timer started, going for the opponent");
			updateText(tick);
		}
	}

	public void onGameTick(Actor current, boolean defeated, int zeroSince, int tick)
	{
		final boolean tracked = current != null && current == opponent;
		onGameTick(tracked, tracked && defeated, tracked ? zeroSince : NO_TICK, tick);
	}

	// zeroSince is the tick the opponent's health first read 0, where its death sequence began.
	void onGameTick(boolean tracked, boolean defeated, int zeroSince, int tick)
	{
		if (tracked)
		{
			if (defeated)
			{
				if (deadSince == NO_TICK)
				{
					deadSince = zeroSince != NO_TICK ? Math.min(zeroSince, tick) : tick;
					debugLog.add("Fight timer: the opponent is defeated, the clock runs until it is gone");
				}
				if (tick - deadSince >= DEATH_TICKS)
				{
					defeat(deadSince + DEATH_TICKS);
				}
			}
			else
			{
				deadSince = NO_TICK;
				if (endTick != NO_TICK)
				{
					// Some opponents drop to 0 and come back for another phase.
					endTick = NO_TICK;
					debugLog.add("Fight timer running again, the opponent is back up");
				}
			}
		}
		usePendingReport(tracked && defeated, tick);
		updateText(tick);
	}

	// The game shows its own durations with hundredths while the player has precise timing on, so the fight
	// time follows that setting instead of a setting of ours.
	public void setPreciseTiming(boolean precise)
	{
		if (precise != preciseTiming)
		{
			preciseTiming = precise;
			// The tick count hasn't changed, so the text has to be asked for again.
			shownTicks = NO_TICK;
		}
	}

	void reset()
	{
		clearFight();
		lastHitActor = null;
		lastHitTick = NO_TICK;
	}

	private void clearFight()
	{
		opponent = null;
		inFight = false;
		startTick = NO_TICK;
		endTick = NO_TICK;
		clearedTick = NO_TICK;
		deadSince = NO_TICK;
		shownTicks = NO_TICK;
		pendingReport = NO_TICK;
		pendingSince = NO_TICK;
		text = null;
	}

	private void defeat(int tick)
	{
		if (startTick != NO_TICK && endTick == NO_TICK)
		{
			endTick = tick;
			debugLog.add("Fight timer stopped, opponent defeated ({})", elapsedText(tick));
		}
	}

	private String elapsedText(int tick)
	{
		final int ticks = elapsedTicks(startTick, endTick, tick);
		return ticks == NO_TICK ? "not started" : ticks + " ticks";
	}

	private void updateText(int tick)
	{
		final int ticks = elapsedTicks(startTick, endTick, tick);
		if (ticks != shownTicks)
		{
			shownTicks = ticks;
			text = ticks == NO_TICK ? null : format(ticks, preciseTiming);
		}
	}

	static int elapsedTicks(int startTick, int endTick, int tick)
	{
		if (startTick == NO_TICK)
		{
			return NO_TICK;
		}
		return Math.max(0, (endTick != NO_TICK ? endTick : tick) - startTick);
	}

	// The fight ends when the opponent is gone, but never more than the death window after the kill was known.
	static int endOfFight(int knownDeadSince, int goneTick)
	{
		return knownDeadSince == NO_TICK ? goneTick : Math.min(goneTick, knownDeadSince + DEATH_TICKS);
	}

	static int recentHitTick(int hitTick, int tick)
	{
		return hitTick != NO_TICK && tick - hitTick >= 0 && tick - hitTick <= 1 ? hitTick : NO_TICK;
	}

	// An NPC already fought in this fight carries it on while it's alive. Any other does too, unless the last opponent
	// was defeated or has been gone too long.
	static boolean keepsCounting(boolean inFight, boolean aliveMember, boolean previousEnded, int clearedTick, int tick)
	{
		return inFight
			&& (aliveMember || (!previousEnded && (clearedTick == NO_TICK || tick - clearedTick <= SWAP_TICKS)));
	}

	// The game prints several wordings of a fight or challenge time, so match on the word they share.
	public static boolean mentionsDuration(String message)
	{
		return message != null && message.toLowerCase(Locale.ROOT).contains("duration");
	}

	// The time the game reports for a kill, in ticks, or NO_TICK when the message holds none. The wordings
	// are the ones the game uses for a fight it times; a total, a personal best and a lap are left out, so
	// only the first time after the wording counts.
	public static int reportedTicks(String message)
	{
		if (message == null)
		{
			return NO_TICK;
		}
		final Matcher matcher = REPORTED_TIME.matcher(Text.removeTags(message));
		if (!matcher.find())
		{
			return NO_TICK;
		}
		final long hours = matcher.group(1) != null ? Long.parseLong(matcher.group(1)) : 0;
		final long minutes = Long.parseLong(matcher.group(2));
		final long seconds = Long.parseLong(matcher.group(3));
		final long hundredths = matcher.group(4) != null ? Long.parseLong(matcher.group(4)) : 0;
		final long millis = ((hours * 60 + minutes) * 60 + seconds) * 1000 + hundredths * 10;
		// Without precise timing the game prints whole seconds, which is its own time rounded down, so the
		// tick count rounds up to land inside the second it printed instead of the one before it.
		final long rounded = matcher.group(4) != null
			? millis : millis + Constants.GAME_TICK_LENGTH - 1;
		return (int) (rounded / Constants.GAME_TICK_LENGTH);
	}

	// The game can print its time on the tick the boss goes down, before the kill is confirmed a tick later,
	// so a time that can't be used yet is kept and tried again on the next ticks.
	public void onReportedTime(int ticks, boolean defeated, int tick)
	{
		if (ticks != NO_TICK && !takeOverTicks(ticks, defeated, tick))
		{
			pendingReport = ticks;
			pendingSince = tick;
		}
	}

	private void usePendingReport(boolean defeated, int tick)
	{
		if (pendingReport != NO_TICK
			&& (takeOverTicks(pendingReport, defeated, tick) || tick - pendingSince >= DEATH_TICKS))
		{
			pendingReport = NO_TICK;
		}
	}

	// The game stopping its own clock is the end of the fight, and its time is the one the player compares
	// against, so the clock stops here and takes it over. A time too far from ours belongs to something
	// larger than this fight, such as a whole raid reported on its last boss, and is left alone.
	boolean takeOverTicks(int ticks, boolean defeated, int tick)
	{
		if (ticks == NO_TICK || startTick == NO_TICK || !(defeated || endTick != NO_TICK))
		{
			return false;
		}
		final int ours = elapsedTicks(startTick, endTick, tick);
		if (Math.abs(ticks - ours) > REPORT_GAP_TICKS)
		{
			debugLog.add("The game's {} ticks are too far from our {}, the fight time is left as it is", ticks, ours);
			return false;
		}
		endTick = startTick + ticks;
		debugLog.add("Fight time taken from the game: {} ticks, ours was {}", ticks, ours);
		updateText(tick);
		return true;
	}

	// With precise timing the hundredths come straight off the ticks, so they land on .00, .20, .40, .60 or
	// .80, the same values the game prints.
	public static String format(int ticks, boolean precise)
	{
		final long millis = (long) ticks * Constants.GAME_TICK_LENGTH;
		final long seconds = millis / 1000;
		final long hours = seconds / 3600;
		final long minutes = seconds / 60 % 60;
		final long secs = seconds % 60;
		final StringBuilder builder = new StringBuilder(11);
		if (hours > 0)
		{
			builder.append(hours).append(':');
			if (minutes < 10)
			{
				builder.append('0');
			}
		}
		builder.append(minutes).append(':');
		if (secs < 10)
		{
			builder.append('0');
		}
		builder.append(secs);
		if (precise)
		{
			final long hundredths = millis % 1000 / 10;
			builder.append('.');
			if (hundredths < 10)
			{
				builder.append('0');
			}
			builder.append(hundredths);
		}
		return builder.toString();
	}
}

package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.data.Health;
import com.ghordrin.bosshealthbar.data.NpcUtil;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.ghordrin.bosshealthbar.gamebars.GameBossBar;
import com.ghordrin.bosshealthbar.gamebars.TobBossBar;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.client.game.NPCManager;

// Where an opponent's health comes from, and what a reading says about whether it's down.
@Singleton
public class HealthReader
{
	public enum Source
	{
		GAME_BAR,
		RAID_BAR,
		OVERHEAD
	}

	public static final class Reading
	{
		public final Source source;
		public final Health health;

		public Reading(Source source, Health health)
		{
			this.source = source;
			this.health = health;
		}

		boolean fromBossBar()
		{
			return source != Source.OVERHEAD;
		}
	}

	private final GameBossBar gameBossBar;
	private final TobBossBar tobBossBar;
	private final NPCManager npcManager;
	private Actor maxHealthActor;
	private int maxHealthForm = -1;
	private Integer maxHealth;

	@Inject
	HealthReader(GameBossBar gameBossBar, TobBossBar tobBossBar, NPCManager npcManager)
	{
		this.gameBossBar = gameBossBar;
		this.tobBossBar = tobBossBar;
		this.npcManager = npcManager;
	}

	// The game's bars have exact hitpoints, and some bosses stop sending overhead health updates while they're
	// shown, so they come first. Null while there's no reading at all.
	public Reading read(Actor actor)
	{
		if (actor == null)
		{
			return null;
		}
		if (gameBossBar.isTracking(actor))
		{
			final Reading reading = readGameBar();
			if (reading != null)
			{
				return reading;
			}
		}
		if (tobBossBar.isTracking(actor))
		{
			final int max = tobBossBar.maxHealth();
			if (max > 0)
			{
				return new Reading(Source.RAID_BAR, new Health(tobBossBar.health(max), max, false, npcMaxHealth(actor),
					false));
			}
		}
		// A scale with a ratio below 0 is the client's "no value", not a reading.
		if (actor.getHealthScale() > 0 && actor.getHealthRatio() >= 0)
		{
			return new Reading(Source.OVERHEAD, new Health(actor.getHealthRatio(), actor.getHealthScale(), false,
				npcMaxHealth(actor), false));
		}
		return null;
	}

	// The game's bar holds the health itself, so a boss that left the scene can still be read off it.
	public Reading readGameBar()
	{
		final int max = gameBossBar.maxHealth();
		if (max <= 0 || !gameBossBar.hasHealth())
		{
			return null;
		}
		return new Reading(Source.GAME_BAR,
			new Health(gameBossBar.health(), max, true, max, gameBossBar.isPercentOnly()));
	}

	void reset()
	{
		maxHealthActor = null;
		maxHealthForm = -1;
		maxHealth = null;
	}

	// Kept for the last NPC and form, since the overlay asks every frame.
	private Integer npcMaxHealth(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return null;
		}
		final int form = NpcUtil.currentId((NPC) actor);
		if (actor == maxHealthActor && form == maxHealthForm)
		{
			return maxHealth;
		}
		final Integer health = npcManager.getHealth(form);
		// An unknown max health is asked again next time.
		if (health != null)
		{
			maxHealthActor = actor;
			maxHealthForm = form;
			maxHealth = health;
		}
		return health;
	}

	// At 0 for now, which isn't a kill on its own: some bosses sit at 0 or heal back from it. A boss bar's own
	// health wins over isDead(), which only means the overhead bar's last update started at 0.
	static boolean isDown(Reading reading, boolean dead, boolean npc, boolean attackable)
	{
		if (reading != null && reading.fromBossBar())
		{
			return reading.health.ratio <= 0;
		}
		// Some turn into a form that can't be attacked as they die, before their bar reaches 0.
		return dead || reading != null && reading.health.ratio == 1 && npc && !attackable;
	}

	// Back for another phase after being down. A boss bar refilling counts; on the overhead bar it has to be
	// attackable again with health to spare.
	static boolean isBackUp(Reading reading, boolean dead, boolean attackable)
	{
		if (reading == null)
		{
			return false;
		}
		if (reading.fromBossBar())
		{
			return reading.health.ratio > 0;
		}
		return !dead && attackable && reading.health.ratio > 1;
	}

	// Once down it stays so until back up, since some die by turning into a death form that still shows a bit of health.
	static boolean stillDown(boolean wasDown, boolean downNow, boolean backUp)
	{
		return downNow || wasDown && !backUp;
	}

	// The first tick of a run of ticks that it's been down and unable to be attacked.
	static int unfightableSince(boolean down, boolean attackable, int since, int tick)
	{
		if (!down || attackable)
		{
			return FightTimer.NO_TICK;
		}
		return since == FightTimer.NO_TICK ? tick : since;
	}

	// A kill once it's been down and unable to be attacked on two ticks in a row. A player at 0 is one at once.
	static boolean isDefeated(boolean down, boolean npc, int unfightableSince, int tick)
	{
		return down && (!npc || unfightableSince != FightTimer.NO_TICK && tick > unfightableSince);
	}

	// Up again after a confirmed kill. A phase change takes about as long as a boss swapping to its next NPC, so only
	// a longer gap than that means the one that comes back is the next one rather than the same fight carrying on.
	static boolean isRevived(int downSince, int tick)
	{
		return downSince != FightTimer.NO_TICK && tick - downSince > FightTimer.SWAP_TICKS;
	}

	static String describe(Reading reading)
	{
		if (reading == null)
		{
			return "no reading";
		}
		final String source;
		switch (reading.source)
		{
			case GAME_BAR:
				source = "game boss bar";
				break;
			case RAID_BAR:
				source = "raid boss bar";
				break;
			default:
				source = "overhead bar";
				break;
		}
		return source + " at " + reading.health.ratio + "/" + reading.health.scale;
	}

	// The overhead bar is up but its ratio is the client's "no value".
	static boolean hasNoValue(int ratio, int scale)
	{
		return scale > 0 && ratio < 0;
	}

	static int form(Actor actor)
	{
		return actor instanceof NPC ? NpcUtil.currentId((NPC) actor) : -1;
	}

	// One actor's down latch and confirmed kill, updated once a tick by whoever reads its health.
	static final class DownState
	{
		boolean down;
		int unfightableSince = FightTimer.NO_TICK;
		boolean defeated;
		private int downSince = FightTimer.NO_TICK;
		private boolean revived;

		// Logs what changed when given a log, so only one owner per NPC passes one. owner starts each line.
		void update(Reading reading, boolean dead, boolean npc, boolean attackable, int tick, DebugLog debugLog,
			String owner, Actor actor)
		{
			final boolean wasDown = down;
			final boolean wasDefeated = defeated;
			final int wasDownSince = downSince;
			down = stillDown(down, isDown(reading, dead, npc, attackable), isBackUp(reading, dead, attackable));
			downSince = !down ? FightTimer.NO_TICK : wasDown ? downSince : tick;
			unfightableSince = HealthReader.unfightableSince(down, npc && attackable, unfightableSince, tick);
			// A kill stays confirmed while it's down, since some die by turning into a form with nothing to read.
			// Being attackable again means it was never a kill.
			defeated = down && (wasDefeated && !(npc && attackable)
				|| isDefeated(down, npc, unfightableSince, tick));
			// Up again long after a confirmed kill, so this is the next one and not another phase.
			final boolean back = wasDefeated && !down && isRevived(wasDownSince, tick);
			revived |= back;
			if (debugLog == null)
			{
				return;
			}
			if (down != wasDown)
			{
				debugLog.add("{}{} {} ({}, dead {})", owner, DebugLog.describe(actor), down ? "down" : "back up",
					describe(reading), dead);
			}
			if (defeated && !wasDefeated)
			{
				debugLog.add("{}{} defeated, can no longer be attacked", owner, DebugLog.describe(actor));
			}
			if (back)
			{
				debugLog.add("{}{} is up again after being defeated", owner, DebugLog.describe(actor));
			}
		}

		// Whether health came back after a confirmed kill, read once by the owner so it acts on it one time.
		boolean takeRevived()
		{
			final boolean revived = this.revived;
			this.revived = false;
			return revived;
		}

		void clear()
		{
			down = false;
			unfightableSince = FightTimer.NO_TICK;
			defeated = false;
			downSince = FightTimer.NO_TICK;
			revived = false;
		}
	}

	// What the debug log last said about one actor's health, so it only gets a line when something that matters changes:
	// the reading's source, a ratio of 0 or 1, an overhead bar with no value, isDead(), being attackable, or the form.
	static final class Watch
	{
		private boolean seen;
		private Source source;
		private int level;
		private boolean dead;
		private boolean attackable;
		private int form;

		boolean changed(Reading reading, boolean noValue, boolean dead, boolean attackable, int form)
		{
			final Source source = reading != null ? reading.source : null;
			final int level = reading != null ? Math.max(-1, Math.min(2, reading.health.ratio)) : noValue ? -2 : -1;
			if (seen && source == this.source && level == this.level && dead == this.dead
				&& attackable == this.attackable && form == this.form)
			{
				return false;
			}
			seen = true;
			this.source = source;
			this.level = level;
			this.dead = dead;
			this.attackable = attackable;
			this.form = form;
			return true;
		}

		void clear()
		{
			seen = false;
		}

		void log(DebugLog debugLog, Actor actor, Reading reading, boolean dead, boolean attackable)
		{
			final int form = form(actor);
			final int ratio = actor.getHealthRatio();
			final int scale = actor.getHealthScale();
			final boolean noValue = reading == null && hasNoValue(ratio, scale);
			if (changed(reading, noValue, dead, attackable, form))
			{
				debugLog.add("Health of {}: {}, dead {}, attackable {}, form {}", DebugLog.describe(actor),
					noValue ? "overhead bar with no value (" + ratio + "/" + scale + "), ignored" : describe(reading),
					dead, attackable, form);
			}
		}
	}
}

package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.data.KnownBosses;
import com.ghordrin.bosshealthbar.data.NpcFilter;
import com.ghordrin.bosshealthbar.data.NpcUtil;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.ghordrin.bosshealthbar.gamebars.GameBossBar;
import com.ghordrin.bosshealthbar.gamebars.TobBossBar;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.InteractingChanged;

@Singleton
public class OpponentTracker
{
	// Past the longest attack range, with room to reposition, but close enough that walking away counts.
	private static final int COMBAT_DISTANCE = 15;

	public enum DespawnOutcome
	{
		DEFEATED,
		OUT_OF_SIGHT,
		LEFT
	}

	// Where the last scene load left the player, so the next one can tell whether they ended up somewhere else.
	static final class Area
	{
		private boolean sceneReloaded;
		private boolean sampled;
		int plane;
		int x;
		int y;
		boolean instance;

		void sceneLoading()
		{
			sceneReloaded = true;
		}

		void clear()
		{
			sceneReloaded = false;
			sampled = false;
			plane = 0;
			x = 0;
			y = 0;
			instance = false;
		}

		// Taken once per load. A no on arrival keeps the sample, in case the position isn't the destination yet, and
		// lets the next tick decide.
		boolean take(boolean onArrival, int toPlane, int toX, int toY, boolean toInstance)
		{
			final boolean left = leftArea(sceneReloaded && sampled, plane, x, y, instance, toPlane, toX, toY, toInstance);
			if (!left && onArrival)
			{
				return false;
			}
			plane = toPlane;
			x = toX;
			y = toY;
			instance = toInstance;
			sampled = true;
			sceneReloaded = false;
			return left;
		}
	}

	private final Client client;
	private final BossHealthBarConfig config;
	private final GameBossBar gameBossBar;
	private final TobBossBar tobBossBar;
	private final SuperiorTracker superiors;
	private final DamageTracker damage;
	private final FightTimer fightTimer;
	private final FightGroup group;
	private final BossMemory memory;
	private final HealthReader healthReader;
	private final DebugLog debugLog;

	@Getter
	private Actor opponent;
	private long interactionLostMillis;
	private long lastHitTakenMillis;
	private long lastOpponentHitMillis;

	private BossMemory.Entry heldEntry;
	private Actor resumedOpponent;
	private final HealthReader.DownState opponentState = new HealthReader.DownState();
	// The opponent, when picking it carried on the fight the previous one was part of.
	private Actor sameFightOpponent;
	private final HealthReader.Watch opponentWatch = new HealthReader.Watch();
	private Actor despawnedActor;
	private DespawnOutcome despawnedOutcome;
	private int zeroSinceTick = FightTimer.NO_TICK;
	// Counts up whenever the opponent starts a new life, so the bar can tell that apart from another phase.
	public int opponentLife;

	private Actor knownBossActor;
	private String knownBossName;
	private boolean knownBoss;

	private final Area area = new Area();

	private NpcFilter alsoShowFor = NpcFilter.EMPTY;
	private NpcFilter neverShowFor = NpcFilter.EMPTY;
	private final NpcFilter.LastMatch opponentListMatch = new NpcFilter.LastMatch();
	private final NpcFilter.LastMatch gameBarListMatch = new NpcFilter.LastMatch();
	private int gameBarNpcId = -1;
	private boolean gameBarNpcShown;
	private NPC raidBossActor;
	private int raidBossForm = -1;
	private boolean raidBossShown;

	@Inject
	OpponentTracker(Client client, BossHealthBarConfig config, GameBossBar gameBossBar, TobBossBar tobBossBar,
		SuperiorTracker superiors, DamageTracker damage, FightTimer fightTimer, FightGroup group, BossMemory memory,
		HealthReader healthReader, DebugLog debugLog)
	{
		this.client = client;
		this.config = config;
		this.gameBossBar = gameBossBar;
		this.tobBossBar = tobBossBar;
		this.superiors = superiors;
		this.damage = damage;
		this.fightTimer = fightTimer;
		this.group = group;
		this.memory = memory;
		this.healthReader = healthReader;
		this.debugLog = debugLog;
	}

	public void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		final Actor target = event.getTarget();
		if (target == null)
		{
			interactionLostMillis = System.currentTimeMillis();
			if (opponent != null)
			{
				debugLog.add("Interaction lost with {}, will clear after {}s if not resumed", DebugLog.describe(opponent),
				config.hideDelay());
			}
			return;
		}

		interactionLostMillis = 0;

		if (target == opponent)
		{
			return;
		}

		// Attacking the smaller NPCs a boss spawns shouldn't take the bar off the boss.
		if (opponent != null && !opponent.isDead() && priority(target) < priority(opponent))
		{
			debugLog.add("Keeping {} over lower priority target {}", DebugLog.describe(opponent), DebugLog.describe(target));
			return;
		}

		setOpponent(target);
	}

	// While a game boss bar is up, the bar follows the NPC it shows.
	public void followGameBars()
	{
		final NPC nativeBarBoss = gameBossBar.findNpc(opponent);
		final NPC gameBarBoss = nativeBarBoss != null ? nativeBarBoss : tobBossBar.findBoss();
		if (gameBarBoss != null && !gameBarBoss.isDead() && gameBarBoss != opponent && !isNeverShown(gameBarBoss))
		{
			setOpponent(gameBarBoss);
			interactionLostMillis = 0;
		}
	}

	public void onNpcSpawned(NPC npc)
	{
		final int tick = client.getTickCount();
		final BossMemory.Entry entry = memory.find(npc.getIndex(), npc.getName(), tick);
		// Only the spawns the bar could pick up, so a busy area doesn't push the current fight out of the log.
		if (entry != null || (opponent != null && npc.getName() != null && npc.getName().equals(opponent.getName())))
		{
			debugLog.add("{} spawned on tick {}", DebugLog.describe(npc), tick);
		}
		if (entry == null || entry != heldEntry || opponent != null || !BossMemory.isHeld(entry.tick, tick)
			|| isNeverShown(npc))
		{
			return;
		}

		// Back in sight soon after leaving it, with nothing else picked meanwhile, so the bar carries on.
		setOpponent(npc);
		interactionLostMillis = System.currentTimeMillis();
	}

	public void onNpcDespawned(NPC npc)
	{
		if (npc != opponent)
		{
			if (memory.contains(npc.getIndex()) && isDown(npc))
			{
				memory.forget(npc.getIndex());
			}
			return;
		}

		final int tick = client.getTickCount();
		// A bar that despawns with the boss can take its health with it, so the last tick's reading counts too.
		final boolean confirmed = opponentState.down || isDown(npc);
		final boolean zero = zeroSinceTick != FightTimer.NO_TICK || readsZero(npc);
		final boolean playerDied = isLocalPlayerDead();
		final int distance = distanceToPlayer(npc);
		// The fight group still holds this NPC's last reading, since it drops it after this.
		final FightGroup.Member member = group.find(npc.getIndex());
		final int lastRatio = member != null ? member.ratio : -1;
		final boolean lastExact = member != null && member.exact;
		final DespawnOutcome outcome = despawnOutcome(confirmed, zero, playerDied, distance, lastRatio, lastExact);
		debugLog.add("Opponent {} despawned (health {}/{}, dead {}, down {}, read 0 since tick {}, player died {}, distance {}): {}",
			DebugLog.describe(npc), npc.getHealthRatio(), npc.getHealthScale(), npc.isDead(), opponentState.down,
			zeroSinceTick, playerDied, distance, outcome);
		// A line of its own when it was the last reading, and not the distance, that made the despawn a kill.
		if (outcome == DespawnOutcome.DEFEATED
			&& despawnOutcome(confirmed, zero, playerDied, distance, -1, false) == DespawnOutcome.OUT_OF_SIGHT)
		{
			debugLog.add("Opponent {} was last read at 0 health, counting its despawn as a kill", DebugLog.describe(npc));
		}
		// A kill ends the fight where the 0 was first read, confirmed then or only at the despawn.
		final int defeatTick = zeroSinceTick != FightTimer.NO_TICK ? zeroSinceTick : tick;
		clearDown();
		despawnedActor = npc;
		despawnedOutcome = outcome;
		fightTimer.opponentDespawned(outcome == DespawnOutcome.DEFEATED, defeatTick, tick);
		if (outcome == DespawnOutcome.OUT_OF_SIGHT)
		{
			heldEntry = memory.remember(npc.getIndex(), npc.getName(), tick, fightTimer.save(group.id()));
			heldEntry.health = member != null ? member.lastAboveZero : null;
		}
		else
		{
			memory.forget(npc.getIndex());
		}
		resumedOpponent = null;
		opponent = null;
		interactionLostMillis = 0;
		lastOpponentHitMillis = 0;
		damage.resetCombo();
	}

	public void onHitsplatApplied(Actor actor, Hitsplat hitsplat)
	{
		if (!isCombatHit(hitsplat.getHitsplatType()))
		{
			return;
		}
		if (actor == client.getLocalPlayer())
		{
			lastHitTakenMillis = System.currentTimeMillis();
		}
		else if (actor != null && actor == opponent)
		{
			lastOpponentHitMillis = System.currentTimeMillis();
		}
	}

	// Clears the opponent once the fight has been quiet for longer than "Hide after", unless a
	// game boss bar still shows it.
	public void onGameTick()
	{
		final Player player = client.getLocalPlayer();
		if (opponent == null || player == null || interactionLostMillis == 0)
		{
			return;
		}

		final boolean nearby = !opponent.isDead() && isNearby(combatDistanceTo(opponent));

		if (opponent != gameBossBar.findNpc(opponent)
			&& opponent != tobBossBar.findBoss()
			&& player.getInteracting() == null
			&& isQuietFor(interactionLostMillis, lastHitTakenMillis, lastOpponentHitMillis, nearby,
				System.currentTimeMillis(), config.hideDelay() * 1000L))
		{
			debugLog.add("Opponent {} timed out after {}s with no combat, clearing", DebugLog.describe(opponent),
				config.hideDelay());
			opponent = null;
			fightTimer.reset();
			group.clear();
			clearDown();
		}
	}

	public void onSceneLoading()
	{
		area.sceneLoading();
	}

	// Whether the fight is to be forgotten: the player ended up somewhere else over the last scene load and nothing of
	// the fight is still here. Taken once per load.
	public boolean takeLeftArea(boolean onArrival)
	{
		final Player player = client.getLocalPlayer();
		final WorldView worldView = client.getTopLevelWorldView();
		if (player == null || worldView == null)
		{
			return false;
		}

		final WorldPoint location = player.getWorldLocation();
		final boolean instance = worldView.isInstance();
		final int fromPlane = area.plane;
		final int fromX = area.x;
		final int fromY = area.y;
		final boolean fromInstance = area.instance;
		final boolean left = area.take(onArrival, location.getPlane(), location.getX(), location.getY(), instance);
		if (left)
		{
			debugLog.add("Left the area over a scene load ({} tiles, plane {} to {}, instance {} to {})",
				BossMemory.tileDistance(fromX, fromY, location.getX(), location.getY()),
				fromPlane, location.getPlane(), fromInstance, instance);
		}
		final boolean forgets = forgetsFight(left, opponent != null);
		if (left && !forgets)
		{
			debugLog.add("Opponent {} is still here, so the fight carries on", DebugLog.describe(opponent));
		}
		return forgets;
	}

	// A fight itself can move the player far enough to reload the scene, so nothing is forgotten while the opponent is
	// still here.
	static boolean forgetsFight(boolean left, boolean opponentPresent)
	{
		return left && !opponentPresent;
	}

	// Far enough over a scene load that nothing we remembered can still be in sight.
	static boolean leftArea(boolean sampled, int fromPlane, int fromX, int fromY, boolean fromInstance,
		int toPlane, int toX, int toY, boolean toInstance)
	{
		return sampled && (fromPlane != toPlane || fromInstance != toInstance
			|| BossMemory.tileDistance(fromX, fromY, toX, toY) >= BossMemory.OUT_OF_SIGHT_DISTANCE);
	}

	// A confirmed defeat counts straight away. An overhead 0 that isn't confirmed, such as a stun meter that empties,
	// only counts if the NPC then despawns in view. Far away it went out of sight, unless the last reading was an
	// exact 0, which wins over the distance.
	static DespawnOutcome despawnOutcome(boolean confirmed, boolean zero, boolean playerDied, int distance,
		int lastRatio, boolean lastExact)
	{
		if (confirmed || zero && distance < BossMemory.OUT_OF_SIGHT_DISTANCE)
		{
			return DespawnOutcome.DEFEATED;
		}
		if (!BossMemory.isOutOfSight(playerDied, distance))
		{
			return DespawnOutcome.LEFT;
		}
		return lastExact && lastRatio == 0 ? DespawnOutcome.DEFEATED : DespawnOutcome.OUT_OF_SIGHT;
	}

	// Close enough for the fight to count.
	static boolean isNearby(int distance)
	{
		return distance >= 0 && distance <= COMBAT_DISTANCE;
	}

	// Whether the player is fighting this opponent right now, which is when its fight starts: going for it, near it,
	// and it can still be fought. One only picked up because a game bar follows it, or already read at 0, isn't fought.
	static boolean startsFight(boolean engaged, boolean attackable, boolean dead, boolean down, int distance)
	{
		return engaged && attackable && !dead && !down && isNearby(distance);
	}

	static boolean isQuietFor(long interactionLostMillis, long lastHitTakenMillis, long lastOpponentHitMillis,
		boolean nearby, long now, long delayMillis)
	{
		if (interactionLostMillis == 0)
		{
			return false;
		}
		long lastCombat = interactionLostMillis;
		if (nearby)
		{
			lastCombat = Math.max(lastCombat, Math.max(lastHitTakenMillis, lastOpponentHitMillis));
		}
		return now - lastCombat > delayMillis;
	}

	// Damage over time is left out on purpose, so ticks that linger after a fight don't keep the bar up.
	public static boolean isCombatHit(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_ME_POISE:
			case HitsplatID.DAMAGE_OTHER_POISE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return true;
			default:
				return false;
		}
	}

	public boolean shouldShowBarFor(Actor actor)
	{
		if (actor == null || actor.getName() == null)
		{
			return false;
		}

		final NpcFilter.Match match = listMatch(opponentListMatch, actor);
		return match != NpcFilter.Match.NEVER
			&& (match == NpcFilter.Match.ALSO
				|| !config.bossOnly()
				|| isKnownBoss(actor)
				|| isGameBarBoss(actor)
				|| (config.showAboveCombatLevel() && actor.getCombatLevel() >= config.minimumCombatLevel())
				|| (config.showSuperiors() && superiors.isSuperior(actor)));
	}

	private boolean isDown(Actor actor)
	{
		return HealthReader.isDown(healthReader.read(actor), actor.isDead(), actor instanceof NPC,
			NpcUtil.isAttackable(actor));
	}

	private static boolean readsZero(Actor actor)
	{
		return actor.getHealthScale() > 0 && actor.getHealthRatio() == 0;
	}

	// A confirmed kill, unlike a 0 the opponent can still come back from.
	public boolean isOpponentDefeated()
	{
		return opponentState.defeated;
	}

	// The tick the opponent's health first read 0, which is where its death sequence began.
	public int zeroSince()
	{
		return zeroSinceTick;
	}

	// Changes when the opponent is back up after a confirmed kill, so the bar starts over for the next one.
	public int opponentLife()
	{
		return opponentLife;
	}

	// Whether the given actor carried on the previous opponent's fight when it was picked, as the fight timer decided.
	public boolean continuesFight(Actor actor)
	{
		return actor != null && actor == sameFightOpponent;
	}

	// How the given opponent's despawn was read, or null if it wasn't the last opponent to despawn.
	public DespawnOutcome despawnOutcome(Actor actor)
	{
		return actor != null && actor == despawnedActor ? despawnedOutcome : null;
	}

	private void clearDown()
	{
		opponentState.clear();
		zeroSinceTick = FightTimer.NO_TICK;
	}

	public void reset()
	{
		opponent = null;
		interactionLostMillis = 0;
		lastHitTakenMillis = 0;
		lastOpponentHitMillis = 0;
		knownBossActor = null;
		knownBossName = null;
		opponentListMatch.clear();
		gameBarListMatch.clear();
		gameBarNpcId = -1;
		raidBossActor = null;
		fightTimer.reset();
		group.clear();
		memory.clear();
		heldEntry = null;
		clearDown();
		despawnedActor = null;
		sameFightOpponent = null;
		healthReader.reset();
		despawnedOutcome = null;
		resumedOpponent = null;
		area.clear();
	}

	public void healedOnReturn(Actor actor)
	{
		debugLog.add("Remembered opponent {} came back with more health, starting a new fight", DebugLog.describe(actor));
		fightTimer.startOver(client.getTickCount());
	}

	// Whether the given opponent was picked up again from memory, carrying on the fight it went out of sight in.
	public boolean resumedFromMemory(Actor actor)
	{
		return actor != null && actor == resumedOpponent;
	}

	private int combatDistanceTo(Actor actor)
	{
		final Player player = client.getLocalPlayer();
		return player == null ? -1 : actor.getWorldArea().distanceTo(player.getWorldLocation());
	}

	// Hits start the fight through the fight timer's own hit path, so this only covers the player going for the opponent.
	private void updateFightStart(Actor actor, boolean attackable, boolean dead, boolean down, int tick)
	{
		// Saves the work below once the fight is under way; onEngaged is what refuses to restart it.
		if (fightTimer.getStartTick() != FightTimer.NO_TICK)
		{
			return;
		}
		// Only the local player's own target counts, and it is read live so an interaction from before counts too.
		final Player player = client.getLocalPlayer();
		final boolean engaged = player != null && actor == player.getInteracting();
		final int distance = engaged ? combatDistanceTo(actor) : -1;
		if (startsFight(engaged, attackable, dead, down, distance) && shouldShowBarFor(actor))
		{
			fightTimer.onEngaged(tick);
		}
	}

	private int distanceToPlayer(NPC npc)
	{
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return -1;
		}
		final WorldPoint tile = npc.getWorldLocation();
		final WorldPoint location = player.getWorldLocation();
		if (tile.getPlane() != location.getPlane())
		{
			return Integer.MAX_VALUE;
		}
		return BossMemory.tileDistance(tile.getX(), tile.getY(), location.getX(), location.getY());
	}

	private boolean isLocalPlayerDead()
	{
		final Player player = client.getLocalPlayer();
		return player != null && (player.isDead() || client.getBoostedSkillLevel(Skill.HITPOINTS) <= 0);
	}

	// Called once a tick. Kept for the despawn, when a boss bar may already have lost the health.
	public void updateOpponentDown()
	{
		if (opponent == null)
		{
			opponentState.clear();
			return;
		}

		final HealthReader.Reading reading = healthReader.read(opponent);
		final boolean dead = opponent.isDead();
		final boolean npc = opponent instanceof NPC;
		final boolean attackable = NpcUtil.isAttackable(opponent);
		// A fight group member's health is logged by the group.
		final DebugLog log = !npc || group.find(((NPC) opponent).getIndex()) == null ? debugLog : null;
		if (log != null)
		{
			opponentWatch.log(log, opponent, reading, dead, attackable);
		}
		final int tick = client.getTickCount();
		opponentState.update(reading, dead, npc, attackable, tick, log, "Opponent ", opponent);
		updateFightStart(opponent, attackable, dead, opponentState.down, tick);
		if (opponentState.takeRevived())
		{
			startNewLife(tick);
		}
		updateZero();
	}

	// The same NPC back up after its kill was confirmed is the next one, so nothing of the previous life carries over.
	private void startNewLife(int tick)
	{
		newLife(fightTimer, group, opponent, isBossLike(opponent), tick);
		sameFightOpponent = null;
		resumedOpponent = null;
		opponentLife++;
		damage.resetCombo();
		clearDown();
		opponentWatch.clear();
	}

	static void newLife(FightTimer fightTimer, FightGroup group, Actor opponent, boolean bossLike, int tick)
	{
		fightTimer.startOver(tick);
		group.startFight(opponent, bossLike, tick);
	}

	// The overhead bar going away, or reading no value, doesn't end the 0, only a reading above it does.
	private void updateZero()
	{
		if (opponent == null || opponent.getHealthScale() <= 0 || opponent.getHealthRatio() < 0)
		{
			return;
		}
		if (opponent.getHealthRatio() > 0)
		{
			zeroSinceTick = FightTimer.NO_TICK;
		}
		else if (zeroSinceTick == FightTimer.NO_TICK)
		{
			zeroSinceTick = client.getTickCount();
			debugLog.add("Opponent {} reads 0 on its overhead bar", DebugLog.describe(opponent));
		}
	}

	public void loadLists()
	{
		alsoShowFor = NpcFilter.parse(config.alsoShowFor());
		neverShowFor = NpcFilter.parse(config.neverShowFor());
		opponentListMatch.clear();
		gameBarListMatch.clear();
		gameBarNpcId = -1;
		raidBossActor = null;
	}

	private void setOpponent(Actor target)
	{
		final int tick = client.getTickCount();
		final BossMemory.Entry returned = target instanceof NPC
			? memory.take(((NPC) target).getIndex(), target.getName(), tick) : null;
		final boolean previousDefeated = opponent != null && (opponentState.down || isDown(opponent));
		final boolean bossLike = isBossLike(target);
		damage.resetCombo();
		heldEntry = null;
		clearDown();
		opponentWatch.clear();
		if (returned != null)
		{
			debugLog.add("Remembered opponent {} came back after {} ticks (remembered health {}/{}, fight start tick {})",
				DebugLog.describe(target), tick - returned.tick, returned.health != null ? returned.health.ratio : -1,
				returned.health != null ? returned.health.scale : -1, returned.fight.startTick);
			fightTimer.opponentReturned(target, returned.fight, tick);
			sameFightOpponent = null;
			group.restore(returned.fight.group, target, bossLike, tick);
			// A fight fought in between leaves the group without this NPC, so the remembered health comes back with it.
			group.restoreHealth(((NPC) target).getIndex(), returned.health);
			resumedOpponent = target;
		}
		else
		{
			if (fightTimer.opponentChanged(target, group.isAliveMember(target), previousDefeated, tick))
			{
				sameFightOpponent = target;
				group.join(target, bossLike, tick);
			}
			else
			{
				sameFightOpponent = null;
				group.startFight(target, bossLike, tick);
			}
			resumedOpponent = null;
		}
		opponent = target;
		lastOpponentHitMillis = 0;
		debugLog.add("New opponent: {} (combat level {}, known boss: {}, game boss bar: {})",
			DebugLog.describe(target), target.getCombatLevel(), KnownBosses.contains(target.getName()), isGameBarBoss(target));
		updateFightStart(target, NpcUtil.isAttackable(target), target.isDead(), isDown(target), tick);
	}

	private int priority(Actor actor)
	{
		if (actor == null)
		{
			return -1;
		}
		if (!shouldShowBarFor(actor))
		{
			return 0;
		}
		return gameBossBar.isTracking(actor) || tobBossBar.isTracking(actor) ? 2 : 1;
	}

	// Opponents that get a bar however "Only show for bosses" is set, apart from the combat level option.
	private boolean isBossLike(Actor actor)
	{
		return actor != null && actor.getName() != null
			&& (listMatch(opponentListMatch, actor) == NpcFilter.Match.ALSO
				|| isKnownBoss(actor)
				|| isGameBarBoss(actor)
				|| (config.showSuperiors() && superiors.isSuperior(actor)));
	}

	private boolean isGameBarBoss(Actor actor)
	{
		return actor != null && (gameBossBar.isTracking(actor) || actor == tobBossBar.cachedBoss());
	}

	// Checked every frame, so the answer is kept for the last actor and name.
	private boolean isKnownBoss(Actor actor)
	{
		final String name = actor.getName();
		if (actor != knownBossActor || !name.equals(knownBossName))
		{
			knownBossActor = actor;
			knownBossName = name;
			knownBoss = KnownBosses.contains(name);
		}
		return knownBoss;
	}

	// A game bar can be up for a boss whose NPC isn't in the scene yet, right after a kill for instance, so
	// this answers by the tracked ID when there is none. The bar counts anything a game bar tracks as a boss,
	// which leaves Never show for as the only setting that can keep it off.
	public boolean gameBarNpcGetsBar(int npcId)
	{
		if (npcId == -1)
		{
			return false;
		}
		if (neverShowFor.isEmpty())
		{
			return true;
		}
		final NPC npc = gameBossBar.trackedNpc();
		if (npc != null && NpcUtil.baseId(npc) == npcId)
		{
			// The NPC in the scene carries the name the lists are matched against everywhere else.
			return !isNeverShown(npc);
		}
		// Asked every frame, so the answer is kept for the last ID.
		if (npcId != gameBarNpcId)
		{
			gameBarNpcId = npcId;
			final NPCComposition composition = client.getNpcDefinition(npcId);
			final String name = composition != null ? composition.getName() : null;
			// A boss with several forms has no name on the ID its bar tracks, only on the forms, so with no
			// NPC in the scene only an entry by ID can answer for it.
			gameBarNpcShown = NpcFilter.check(neverShowFor, NpcFilter.EMPTY, NpcUtil.hasName(name) ? name : "", npcId)
				!= NpcFilter.Match.NEVER;
		}
		return gameBarNpcShown;
	}

	// The raid bar's boss usually isn't the opponent, and the question comes every frame, so the whole answer
	// is kept until that boss or its form changes.
	public boolean raidBarBossGetsBar(NPC boss)
	{
		final int form = boss != null ? NpcUtil.currentId(boss) : -1;
		if (boss != raidBossActor || form != raidBossForm)
		{
			raidBossActor = boss;
			raidBossForm = form;
			raidBossShown = shouldShowBarFor(boss);
		}
		return raidBossShown;
	}

	// Kept apart from the opponent's cached answer, so checking both each frame doesn't redo the match.
	private boolean isNeverShown(NPC npc)
	{
		return npc.getName() != null && listMatch(gameBarListMatch, npc) == NpcFilter.Match.NEVER;
	}

	private NpcFilter.Match listMatch(NpcFilter.LastMatch last, Actor actor)
	{
		if (!(actor instanceof NPC) || (alsoShowFor.isEmpty() && neverShowFor.isEmpty()))
		{
			return NpcFilter.Match.NONE;
		}
		return last.get((NPC) actor, neverShowFor, alsoShowFor);
	}
}

package com.ghordrin.bosshealthbar.tracking;

import com.ghordrin.bosshealthbar.data.NpcUtil;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.google.common.collect.ImmutableSet;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.NpcID;

@Singleton
public class SuperiorTracker
{
	private static final String SPAWN_MESSAGE = "A superior foe has appeared";
	private static final int MATCH_TICKS = 2;
	private static final int SEARCH_DISTANCE = 15;

	// Superior slayer monsters, including their death forms. The weekly data check lists new ones.
	private static final Set<Integer> KNOWN_IDS = ImmutableSet.of(
		NpcID.SUPERIOR_CRAWLING_HAND, NpcID.SUPERIOR_CAVE_CRAWLER, NpcID.SUPERIOR_BANSHEE,
		NpcID.SUPERIOR_KOUREND_BANSHEE, NpcID.SUPERIOR_ROCKSLUG, NpcID.SUPERIOR_COCKATRICE, NpcID.SUPERIOR_PYREFIEND,
		NpcID.SUPERIOR_BASILISK, NpcID.SUPERIOR_INFERNAL_MAGE, NpcID.SUPERIOR_BLOODVELD,
		NpcID.SUPERIOR_KOUREND_BLOODVELD, NpcID.SUPERIOR_JELLY, NpcID.SUPERIOR_KOUREND_JELLY,
		NpcID.SUPERIOR_CAVE_HORROR, NpcID.SUPERIOR_ABBERANT_SPECTRE, NpcID.SUPERIOR_KOUREND_SPECTRE,
		NpcID.SUPERIOR_DUSTDEVIL, NpcID.SUPERIOR_KURASK, NpcID.SUPERIOR_SMOKE_DEVIL, NpcID.SUPERIOR_GARGOYLE,
		NpcID.SUPERIOR_GARGOYLE_DEAD, NpcID.SUPERIOR_DARK_BEAST, NpcID.SUPERIOR_ABYSSAL_DEMON,
		NpcID.SUPERIOR_NECHRYAEL, NpcID.SUPERIOR_BASILISK_KNIGHT, NpcID.SUPERIOR_PYRELORD, NpcID.SUPERIOR_TUROTH,
		NpcID.SUPERIOR_WYRM_DARK, NpcID.SUPERIOR_WYRM_LIGHT, NpcID.SUPERIOR_DRAKE, NpcID.SUPERIOR_DRAKE_DEATH,
		NpcID.SUPERIOR_HYDRA, NpcID.SUPERIOR_WARPED_TERRORBIRD, NpcID.SUPERIOR_WARPED_TORTOISE,
		NpcID.SUPERIOR_ARAXYTE, NpcID.SUPERIOR_CAVE_CRAWLER_ICE, NpcID.SUPERIOR_CUSTODIAN, NpcID.SUPERIOR_GRYPHON,
		NpcID.SUPERIOR_CHILLED_JELLY, NpcID.SUPERIOR_AQUANITE, NpcID.SUPERIOR_AQUANITE_NOLURE,
		NpcID.SUPERIOR_LAVA_STRYKEWYRM, NpcID.SUPERIOR_VENATOR,
		NpcID.DEADMAN_BREACH_SUPERIOR_ABYSSAL_DEMON, NpcID.DEADMAN_BREACH_SUPERIOR_PYREFIEND,
		NpcID.DEADMAN_BREACH_SUPERIOR_CAVE_HORROR, NpcID.DEADMAN_BREACH_SUPERIOR_INFERNAL_MAGE,
		NpcID.DEADMAN_BREACH_SUPERIOR_KOUREND_JELLY, NpcID.DEADMAN_BREACH_SUPERIOR_DARK_BEAST,
		NpcID.LEAGUE_SUPERIOR_CRAWLING_HAND, NpcID.LEAGUE_SUPERIOR_CAVE_CRAWLER, NpcID.LEAGUE_SUPERIOR_BANSHEE,
		NpcID.LEAGUE_SUPERIOR_KOUREND_BANSHEE, NpcID.LEAGUE_SUPERIOR_ROCKSLUG, NpcID.LEAGUE_SUPERIOR_COCKATRICE,
		NpcID.LEAGUE_SUPERIOR_PYREFIEND, NpcID.LEAGUE_SUPERIOR_PYRELORD, NpcID.LEAGUE_SUPERIOR_BASILISK,
		NpcID.LEAGUE_SUPERIOR_BASILISK_KNIGHT, NpcID.LEAGUE_SUPERIOR_INFERNAL_MAGE, NpcID.LEAGUE_SUPERIOR_BLOODVELD,
		NpcID.LEAGUE_SUPERIOR_KOUREND_BLOODVELD, NpcID.LEAGUE_SUPERIOR_JELLY, NpcID.LEAGUE_SUPERIOR_KOUREND_JELLY,
		NpcID.LEAGUE_SUPERIOR_CAVE_HORROR, NpcID.LEAGUE_SUPERIOR_ABBERANT_SPECTRE,
		NpcID.LEAGUE_SUPERIOR_KOUREND_SPECTRE, NpcID.LEAGUE_SUPERIOR_DUSTDEVIL, NpcID.LEAGUE_SUPERIOR_KURASK,
		NpcID.LEAGUE_SUPERIOR_SMOKE_DEVIL, NpcID.LEAGUE_SUPERIOR_GARGOYLE, NpcID.LEAGUE_SUPERIOR_GARGOYLE_DEAD,
		NpcID.LEAGUE_SUPERIOR_DARK_BEAST, NpcID.LEAGUE_SUPERIOR_ABYSSAL_DEMON, NpcID.LEAGUE_SUPERIOR_NECHRYAEL,
		NpcID.LEAGUE_SUPERIOR_TUROTH, NpcID.LEAGUE_SUPERIOR_WYRM_DARK, NpcID.LEAGUE_SUPERIOR_WYRM_LIGHT,
		NpcID.LEAGUE_SUPERIOR_DRAKE, NpcID.LEAGUE_SUPERIOR_DRAKE_DEATH, NpcID.LEAGUE_SUPERIOR_HYDRA);

	@Value
	static class Spawn<T>
	{
		T npc;
		boolean knownSuperior;
		boolean eligible;
	}

	@Value
	static class Match<T>
	{
		boolean decided;
		T superior;
	}

	private final Client client;
	private final DebugLog debugLog;
	private final Map<NPC, Integer> recentSpawnTicks = new HashMap<>();
	private final Set<NPC> superiors = new HashSet<>();
	private int messageTick = -1;

	@Inject
	SuperiorTracker(Client client, DebugLog debugLog)
	{
		this.client = client;
		this.debugLog = debugLog;
	}

	boolean isSuperior(Actor actor)
	{
		return actor instanceof NPC
			&& (superiors.contains(actor) || isKnownSuperior(NpcUtil.currentId((NPC) actor)));
	}

	static boolean isKnownSuperior(int npcId)
	{
		return KNOWN_IDS.contains(npcId);
	}

	public void onNpcSpawned(NPC npc)
	{
		recentSpawnTicks.put(npc, client.getTickCount());
	}

	public void onNpcDespawned(NPC npc)
	{
		recentSpawnTicks.remove(npc);
		superiors.remove(npc);
	}

	public void onChatMessage(ChatMessage event)
	{
		if ((event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
			&& event.getMessage().contains(SPAWN_MESSAGE))
		{
			messageTick = client.getTickCount();
			debugLog.add("Superior spawn message on tick {}", messageTick);
		}
	}

	// Superiors in KNOWN_IDS are known by their ID. For any other, the chat message is matched to the
	// one attackable NPC that spawned near the player around the same tick, in either order.
	public void onGameTick()
	{
		final int tick = client.getTickCount();
		recentSpawnTicks.values().removeIf(spawnTick -> tick - spawnTick > MATCH_TICKS);

		if (messageTick == -1)
		{
			return;
		}

		final Player player = client.getLocalPlayer();
		final List<Spawn<NPC>> spawns = new ArrayList<>();
		int eligible = 0;
		for (NPC npc : recentSpawnTicks.keySet())
		{
			final boolean known = isKnownSuperior(NpcUtil.currentId(npc));
			final Spawn<NPC> spawn = new Spawn<>(npc, known, !known && player != null && isEligible(npc, player));
			eligible += spawn.isEligible() ? 1 : 0;
			spawns.add(spawn);
		}

		final Match<NPC> match = match(spawns);
		if (match.isDecided())
		{
			messageTick = -1;
			if (match.getSuperior() != null)
			{
				superiors.add(match.getSuperior());
				debugLog.add("Marked {} as a superior", DebugLog.describe(match.getSuperior()));
			}
			else if (eligible > 1 && spawns.stream().noneMatch(Spawn::isKnownSuperior))
			{
				debugLog.add("{} NPCs spawned with the superior spawn message, marking none", eligible);
			}
		}
		else if (tick - messageTick >= MATCH_TICKS)
		{
			messageTick = -1;
			debugLog.add("No spawned NPC found for the superior spawn message");
		}
	}

	private boolean isEligible(NPC npc, Player player)
	{
		return !npc.isDead() && !superiors.contains(npc) && NpcUtil.isAttackable(npc)
			&& npc.getWorldLocation().distanceTo(player.getWorldLocation()) <= SEARCH_DISTANCE;
	}

	// A known superior takes the message. Otherwise a single eligible spawn is marked; with several it
	// would be a guess, so none is.
	static <T> Match<T> match(List<Spawn<T>> spawns)
	{
		T only = null;
		int eligible = 0;
		for (Spawn<T> spawn : spawns)
		{
			if (spawn.isKnownSuperior())
			{
				return new Match<>(true, null);
			}
			if (spawn.isEligible())
			{
				only = spawn.getNpc();
				eligible++;
			}
		}
		if (eligible > 1)
		{
			return new Match<>(true, null);
		}
		return new Match<>(eligible == 1, only);
	}

	public void reset()
	{
		recentSpawnTicks.clear();
		superiors.clear();
		messageTick = -1;
	}
}

