package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.tracking.OpponentTracker.DespawnOutcome.DEFEATED;
import static com.ghordrin.bosshealthbar.tracking.OpponentTracker.DespawnOutcome.LEFT;
import static com.ghordrin.bosshealthbar.tracking.OpponentTracker.DespawnOutcome.OUT_OF_SIGHT;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.render.BarStateSelector.DefeatStep;
import com.ghordrin.bosshealthbar.render.BarStateSelector.Switch;
import com.ghordrin.bosshealthbar.tracking.FightTimer;
import com.ghordrin.bosshealthbar.tracking.OpponentTracker;
import org.junit.Test;

public class BarStateSelectorTest
{
	// The bar's defeat follows a confirmed kill, so the input is the tracker's isOpponentDefeated, not isDead.
	@Test
	public void theDefeatStartsOnAKillAndStopsWhenItIsNoLongerOne()
	{
		assertEquals(DefeatStep.START, BarStateSelector.defeatStep(true, false, true));
		assertEquals(DefeatStep.NONE, BarStateSelector.defeatStep(true, true, true));
		assertEquals(DefeatStep.NONE, BarStateSelector.defeatStep(true, false, false));
		assertEquals(DefeatStep.CANCEL, BarStateSelector.defeatStep(false, true, true));
	}

	@Test
	public void withoutADespawnReadingItIsADefeatWhenDeadOrLastReadAtZeroInView()
	{
		assertTrue(BarStateSelector.defeatedAtDespawn(null, true, 20, false));
		assertTrue(BarStateSelector.defeatedAtDespawn(null, false, 0, false));
		assertFalse(BarStateSelector.defeatedAtDespawn(null, false, 20, false));
		assertFalse(BarStateSelector.defeatedAtDespawn(null, true, 0, true));
	}

	@Test
	public void theTrackersDespawnReadingDecides()
	{
		assertTrue(BarStateSelector.defeatedAtDespawn(DEFEATED, false, 1, false));
		assertFalse(BarStateSelector.defeatedAtDespawn(LEFT, true, 0, false));
		assertFalse(BarStateSelector.defeatedAtDespawn(OUT_OF_SIGHT, false, 20, true));
		// The bar's own 0 wins over the distance.
		assertTrue(BarStateSelector.defeatedAtDespawn(OUT_OF_SIGHT, false, 0, false));
	}

	@Test
	public void theOutcomeAloneDecidesTheDefeatAtDespawn()
	{
		assertTrue(BarStateSelector.defeatedAtDespawn(DEFEATED, false, 1, outOfSight(DEFEATED)));
		assertFalse(BarStateSelector.defeatedAtDespawn(OUT_OF_SIGHT, false, 0, outOfSight(OUT_OF_SIGHT)));
		assertFalse(BarStateSelector.defeatedAtDespawn(LEFT, true, 0, outOfSight(LEFT)));
		assertTrue(BarStateSelector.defeatedAtDespawn(null, true, 20, outOfSight(null)));
		assertTrue(BarStateSelector.defeatedAtDespawn(null, false, 0, outOfSight(null)));
	}

	@Test
	public void aResumedOpponentWinsOverMovingAndStartingOver()
	{
		assertEquals(Switch.RESUME, BarStateSelector.switchTo(true, true, true, true, false, true, false));
		assertEquals(Switch.RESUME, BarStateSelector.switchTo(true, true, false, false, false, false, false));
		assertEquals(Switch.RESUME, BarStateSelector.switchTo(true, true, true, false, true, false, false));
		// Without an opponent there is nothing to resume.
		assertEquals(Switch.RESET, BarStateSelector.switchTo(false, true, true, false, false, false, false));
	}

	// A boss that goes untargetable mid-fight leaves the scene, and the game's own bar is the only thing
	// still saying the fight is on. Without that, the bar cleared seconds into the phase.
	@Test
	public void theGameSBarHoldsABossThatLeftLongerThanTheSwitchWindow()
	{
		assertTrue(BarStateSelector.holdsForNext(true, true, false, true));
		assertTrue(BarStateSelector.holdsForNext(true, true, true, false));
		assertFalse(BarStateSelector.holdsForNext(true, true, false, false));
		// The game's bar moving to another boss, or another boss leaving, ends the hold.
		assertFalse(BarStateSelector.holdsForNext(true, false, false, true));
		assertFalse(BarStateSelector.holdsForNext(false, true, true, true));
	}

	// Something hit while the boss is away, such as a mechanic it hides behind, must not take the bar over
	// and then play a defeat when it dies.
	@Test
	public void aHeldBossKeepsTheBarOverAnotherTarget()
	{
		assertEquals(Switch.KEEP, BarStateSelector.switchTo(true, false, true, true, false, true, true));
		assertEquals(Switch.KEEP, BarStateSelector.switchTo(true, true, true, false, false, true, true));
		// The boss itself coming back is not another target, so the bar goes to it.
		assertEquals(Switch.RESUME, BarStateSelector.switchTo(true, true, true, false, false, true, false));
		assertEquals(Switch.MOVE, BarStateSelector.switchTo(true, false, true, true, false, true, false));
	}

	@Test
	public void noOpponentClearsTheBarUnlessTheDefeatIsPlaying()
	{
		assertEquals(Switch.RESET, BarStateSelector.switchTo(false, false, true, false, false, false, false));
		assertEquals(Switch.KEEP, BarStateSelector.switchTo(false, false, true, false, true, false, false));
	}

	@Test
	public void anOpponentThatLeftAliveHoldsTheBarForTheNextOne()
	{
		assertEquals(Switch.KEEP, BarStateSelector.switchTo(false, false, true, false, false, true, false));
		assertEquals(Switch.MOVE, BarStateSelector.switchTo(true, false, true, true, false, true, false));
		assertEquals(Switch.MOVE, BarStateSelector.switchTo(true, false, true, false, false, true, false));
		// Once the hold runs out, the bar clears or starts over as before.
		assertEquals(Switch.RESET, BarStateSelector.switchTo(false, false, true, false, false, false, false));
	}

	// The bar only moves when the fight timer carries on, so the two never disagree.
	@Test
	public void aNewOpponentMovesTheBarOnlyWhenItCarriesOnTheFight()
	{
		assertEquals(Switch.RESUME, BarStateSelector.switchTo(true, true, true, false, true, false, false));
		assertEquals(Switch.MOVE, BarStateSelector.switchTo(true, false, true, true, false, false, false));
		// Such as the next NPC clicked while the last one is still dying: a new fight, so a new bar.
		assertEquals(Switch.RESET, BarStateSelector.switchTo(true, false, true, false, false, false, false));
		assertEquals(Switch.RESET, BarStateSelector.switchTo(true, false, true, true, true, false, false));
		assertEquals(Switch.RESET, BarStateSelector.switchTo(true, false, false, true, false, false, false));
	}

	// An opponent back up after being defeated reports no carried-on fight, which is what the bar asks about here.
	@Test
	public void anOpponentThatDoesNotCarryOnTheFightGetsANewBarEvenWhileADefeatPlays()
	{
		assertEquals(Switch.RESET, BarStateSelector.switchTo(true, false, true, false, true, false, false));
	}

	@Test
	public void aHeldBarFollowsTheTimerOfItsOwnFight()
	{
		assertEquals("1:30", BarStateSelector.heldFightTime("1:28", "1:30", 100, 100));
	}

	// Attacking something else while the defeated bar is still up starts another fight, whose clock isn't this bar's.
	@Test
	public void aHeldBarKeepsItsTimeOnceAnotherFightHasStarted()
	{
		assertEquals("1:30", BarStateSelector.heldFightTime("1:30", "0:00", 100, 420));
		assertEquals("1:30", BarStateSelector.heldFightTime("1:30", null, 100, FightTimer.NO_TICK));
	}

	private static boolean outOfSight(OpponentTracker.DespawnOutcome outcome)
	{
		return outcome == OUT_OF_SIGHT;
	}
}

package com.ghordrin.bosshealthbar.render;

import static org.junit.Assert.assertEquals;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class BarTextPainterTest
{
	private static final FontMetrics METRICS = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB)
		.createGraphics().getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 16));

	@Test
	public void theFullNameIsKeptWhileItFits()
	{
		final int room = METRICS.stringWidth("Doom of Mokhaiotl");
		assertEquals("Doom of Mokhaiotl",
			BarTextPainter.fittedName("Doom of Mokhaiotl", "Doom", METRICS, room));
		assertEquals("Doom of Mokhaiotl",
			BarTextPainter.fittedName("Doom of Mokhaiotl", "Doom", METRICS, room + 50));
	}

	@Test
	public void theShortNameTakesOverOnceTheFullOneDoesNotFit()
	{
		final int room = METRICS.stringWidth("Doom of Mokhaiotl") - 1;
		assertEquals("Doom", BarTextPainter.fittedName("Doom of Mokhaiotl", "Doom", METRICS, room));
		assertEquals("Doom (Burrowed)",
			BarTextPainter.fittedName("Doom of Mokhaiotl (Burrowed)", "Doom (Burrowed)", METRICS, room));
	}

	@Test
	public void aBossWithoutAShortNameKeepsItsFullNameToBeEllipsized()
	{
		assertEquals("General Graardor", BarTextPainter.fittedName("General Graardor", null, METRICS, 0));
	}


	// The name font is usually the taller of the two, so the row has to follow it and not the hitpoints font.
	@Test
	public void thePartnerRowFitsTheTallestFontThatHasText()
	{
		assertEquals(24, BarTextPainter.partnerRowHeight(true, true, 18, 6, 10, 4));
		assertEquals(24, BarTextPainter.partnerRowHeight(true, false, 18, 6, 10, 4));
		assertEquals(14, BarTextPainter.partnerRowHeight(false, true, 18, 6, 10, 4));
		assertEquals(0, BarTextPainter.partnerRowHeight(false, false, 18, 6, 10, 4));
	}

	// Each side reaches a different distance above its baseline, so one of them sets where the shared baseline sits.
	@Test
	public void thePartnerRowMixesTheTwoFontsOnOneBaseline()
	{
		assertEquals(26, BarTextPainter.partnerRowHeight(true, true, 18, 2, 10, 8));
		assertEquals(18, BarTextPainter.partnerBaseline(true, true, 18, 10));
		assertEquals(10, BarTextPainter.partnerBaseline(false, true, 18, 10));
	}

	@Test
	public void theSlotSizingSwapsEveryDigit()
	{
		assertEquals("0:00", BarTextPainter.withDigits("1:23", '0'));
		assertEquals("4:44:44", BarTextPainter.withDigits("1:05:09", '4'));
	}
}

