import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.config.ConfigMigrations;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import net.runelite.client.config.FontType;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

public class ItemFontsTest
{
	private static final FontType SERIF_17 = new FontType().withFamily(Font.SERIF).withSize(17);
	private static final FontType SERIF_12 = new FontType().withFamily(Font.SERIF).withSize(12);

	private static class FontsConfig implements BossHealthBarConfig
	{
		FontType font = DEFAULT_FONT;
		FontType damageNumberFont = FontType.REGULAR;
		FontType combatLevelFont = FontType.SMALL;
		FontType hitpointsFont = FontType.SMALL;
		FontType killCountFont = FontType.SMALL;
		FontType partyDefenceFont = FontType.SMALL;
		boolean smoothText = true;
		boolean showCombatLevel;
		boolean showKillCount;
		BarPosition killCountPosition = BarPosition.BOTTOM_LEFT;

		@Override
		public FontType font()
		{
			return font;
		}

		@Override
		public FontType damageNumberFont()
		{
			return damageNumberFont;
		}

		@Override
		public FontType combatLevelFont()
		{
			return combatLevelFont;
		}

		@Override
		public FontType hitpointsFont()
		{
			return hitpointsFont;
		}

		@Override
		public FontType killCountFont()
		{
			return killCountFont;
		}

		@Override
		public FontType partyDefenceFont()
		{
			return partyDefenceFont;
		}

		@Override
		public boolean smoothText()
		{
			return smoothText;
		}

		@Override
		public boolean showCombatLevel()
		{
			return showCombatLevel;
		}

		@Override
		public boolean showKillCount()
		{
			return showKillCount;
		}

		@Override
		public BarPosition killCountPosition()
		{
			return killCountPosition;
		}
	}

	private static BarTextPainter painter(FontsConfig config)
	{
		final BarTextPainter painter = new BarTextPainter(null, config);
		painter.updateFonts();
		painter.updateRows(false, false, false, false, false);
		return painter;
	}

	// The old look for a Serif 17 name, as the one-time migration sets it up.
	private static FontsConfig migratedSerif()
	{
		final FontsConfig config = new FontsConfig();
		config.font = SERIF_17;
		config.damageNumberFont = SERIF_17;
		config.combatLevelFont = SERIF_12;
		config.hitpointsFont = SERIF_12;
		config.killCountFont = SERIF_12;
		config.partyDefenceFont = SERIF_12;
		return config;
	}

	@Test
	public void migratedSmallTextRowsKeepTheirOldHeightAtEverySize()
	{
		for (int size = 8; size <= 40; size++)
		{
			final FontType name = new FontType().withFamily(Font.SERIF).withSize(size);
			final FontType small = ConfigMigrations.smallTextFont(name);
			final FontsConfig config = new FontsConfig();
			config.font = name;
			config.damageNumberFont = name;
			config.combatLevelFont = small;
			config.hitpointsFont = small;
			config.killCountFont = small;
			config.partyDefenceFont = small;
			// The old row was as tall as the name font. At the smallest sizes the text reached past that,
			// and the row now grows to fit it.
			final BarTextPainter painter = painter(config);
			assertEquals("size " + size, Math.max(size, painter.rowBaseline(BarPosition.Row.BOTTOM)), painter.rowHeight(BarPosition.Row.BOTTOM));
			if (size >= 10)
			{
				assertEquals("size " + size, size, painter.rowHeight(BarPosition.Row.BOTTOM));
			}
		}
	}

	@Test
	public void theTallestItemSetsTheRowBaselineAndHeight()
	{
		final BarPosition[] positions = new BarPosition[ITEM_COUNT];
		Arrays.fill(positions, BarPosition.TOP_LEFT);
		final boolean[] available = new boolean[ITEM_COUNT];
		available[NAME] = true;
		available[KILL_COUNT] = true;
		final int[] above = new int[ITEM_COUNT];
		final int[] below = new int[ITEM_COUNT];
		above[NAME] = 18;
		below[NAME] = 6;
		above[KILL_COUNT] = 30;
		below[KILL_COUNT] = 2;

		assertEquals(30, BarTextPainter.rowBaseline(positions, available, BarPosition.Row.TOP, above));
		assertEquals(36, BarTextPainter.rowHeight(positions, available, BarPosition.Row.TOP, above, below));
		assertEquals(0, BarTextPainter.rowHeight(positions, available, BarPosition.Row.BOTTOM, above, below));
	}

	@Test
	public void fontsAreReadPerItem()
	{
		final FontsConfig config = new FontsConfig();
		config.partyDefenceFont = SERIF_12;
		final FontType[] fonts = new FontType[ITEM_COUNT];
		BarFonts.readItemFonts(config, fonts);
		assertSame(BossHealthBarConfig.DEFAULT_FONT, fonts[NAME]);
		assertSame(FontType.REGULAR, fonts[DAMAGE_NUMBER]);
		assertSame(FontType.SMALL, fonts[HITPOINTS]);
		assertSame(SERIF_12, fonts[PARTY_DEFENCE]);
		assertSame(SERIF_12, fonts[MAGIC_DEFENCE]);
		assertSame(FontType.SMALL, fonts[DRAIN_CAP]);
		assertSame(FontType.SMALL, fonts[BarTextPainter.FIGHT_TIMER]);
	}

	@Test
	public void defaultFontsLookAsBefore()
	{
		final FontsConfig config = new FontsConfig();
		config.showCombatLevel = true;
		final BarTextPainter painter = painter(config);
		final String small = FontManager.getRunescapeSmallFont().getFamily();

		assertEquals(FontManager.getRunescapeFont().getFamily(), painter.fonts().font(NAME).getFamily());
		assertEquals(16, painter.fonts().font(NAME).getSize());
		assertEquals(16, painter.fonts().font(DAMAGE_NUMBER).getSize());
		assertEquals(small, painter.fonts().font(HITPOINTS).getFamily());
		assertEquals(16, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(small, painter.fonts().levelFont().getFamily());
		assertEquals(24, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(16, painter.rowHeight(BarPosition.Row.BOTTOM));
		assertEquals(18, painter.rowBaseline(BarPosition.Row.TOP));
		assertEquals(12, painter.rowBaseline(BarPosition.Row.BOTTOM));
	}

	@Test
	public void migratedSerifLooksAsBefore()
	{
		final FontsConfig config = migratedSerif();
		config.showCombatLevel = true;
		final BarTextPainter painter = painter(config);

		// The old code put a row of small text at the small font's ascent + 1, measured with these hints.
		final Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
		final int smallAscent = graphics.getFontMetrics(FontManager.getFallbackFont(Font.SERIF, Font.PLAIN, 12)).getAscent();
		graphics.dispose();

		assertEquals(17, painter.fonts().font(NAME).getSize());
		assertEquals(12, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(12, painter.fonts().levelFont().getSize());
		assertEquals(26, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(17, painter.rowHeight(BarPosition.Row.BOTTOM));
		assertEquals(20, painter.rowBaseline(BarPosition.Row.TOP));
		assertEquals(smallAscent + 1, painter.rowBaseline(BarPosition.Row.BOTTOM));
	}

	@Test
	public void theNameFontSizeOnlyChangesTheName()
	{
		final FontsConfig config = new FontsConfig();
		config.font = FontType.REGULAR.withSize(24);
		final BarTextPainter painter = painter(config);

		assertEquals(24, painter.fonts().font(NAME).getSize());
		assertEquals(16, painter.fonts().font(DAMAGE_NUMBER).getSize());
		assertEquals(16, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(36, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(16, painter.rowHeight(BarPosition.Row.BOTTOM));
	}

	@Test
	public void rowsGrowToFitLargerFonts()
	{
		final FontsConfig config = new FontsConfig();
		config.hitpointsFont = FontType.SMALL.withSize(32);
		config.showKillCount = true;
		config.killCountPosition = BarPosition.TOP_CENTER;
		config.killCountFont = FontType.SMALL.withSize(40);
		final BarTextPainter painter = painter(config);

		assertEquals(32, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(40, painter.fonts().font(KILL_COUNT).getSize());
		assertEquals(40, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(32, painter.rowHeight(BarPosition.Row.BOTTOM));
	}

	@Test
	public void iconsFollowTheirItemsFont()
	{
		final Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		final FontMetrics normal = graphics.getFontMetrics(FontManager.getRunescapeSmallFont());
		final FontMetrics large = graphics.getFontMetrics(FontManager.getRunescapeSmallFont().deriveFont(32f));
		graphics.dispose();

		assertTrue(BarTextPainter.itemIconSize(large) > BarTextPainter.itemIconSize(normal));
		assertEquals(Math.round((normal.getAscent() + 1) * 1.3f), BarTextPainter.itemIconSize(normal));
	}

	@Test
	public void onlyChangedFontsAreRebuilt()
	{
		final FontsConfig config = new FontsConfig();
		final BarTextPainter painter = painter(config);
		final Font name = painter.fonts().font(NAME);
		final Font hitpoints = painter.fonts().font(HITPOINTS);
		final Font killCount = painter.fonts().font(KILL_COUNT);

		painter.updateFonts();
		assertSame(name, painter.fonts().font(NAME));
		assertSame(hitpoints, painter.fonts().font(HITPOINTS));

		config.hitpointsFont = FontType.SMALL.withSize(24);
		painter.updateFonts();
		assertEquals(24, painter.fonts().font(HITPOINTS).getSize());
		assertSame(killCount, painter.fonts().font(KILL_COUNT));
		assertSame(name, painter.fonts().font(NAME));

		// Smooth text only changes how the fonts are measured and drawn.
		config.smoothText = false;
		painter.updateFonts();
		assertSame(killCount, painter.fonts().font(KILL_COUNT));

		config.killCountFont = FontType.SMALL.withBold(true);
		painter.updateFonts();
		assertTrue(painter.fonts().font(KILL_COUNT).isBold());
		config.killCountFont = FontType.SMALL.withItalic(true);
		painter.updateFonts();
		assertFalse(painter.fonts().font(KILL_COUNT).isBold());
		assertTrue(painter.fonts().font(KILL_COUNT).isItalic());
		assertSame(name, painter.fonts().font(NAME));
	}
}

package com.ghordrin.bosshealthbar.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PartnerBarTest
{
	@Test
	public void itIsLiveInAPreviewOrAGroupFightWhileTheSettingIsOn()
	{
		assertTrue(PartnerBar.isLive(true, true, false));
		assertTrue(PartnerBar.isLive(true, false, true));
		assertFalse(PartnerBar.isLive(true, false, false));
		assertFalse(PartnerBar.isLive(false, true, true));
	}

	@Test
	public void theBarIsAShareOfTheMainOnesHeightDownToAFloor()
	{
		assertEquals(20, PartnerBar.barThickness(40, 50));
		assertEquals(8, PartnerBar.barThickness(15, 50));
		assertEquals(4, PartnerBar.barThickness(6, 50));
		assertEquals(4, PartnerBar.barThickness(1, 50));
		assertEquals(40, PartnerBar.barThickness(40, 100));
		assertEquals(8, PartnerBar.barThickness(40, 20));
		assertEquals(10, PartnerBar.barThickness(16, 65));
	}

	// Half the height is what the bar had before the scale was a setting, so that share has to land on the same
	// pixel for every height.
	@Test
	public void halfTheHeightIsWhatTheBarUsedToBe()
	{
		for (int barHeight = 1; barHeight <= 64; barHeight++)
		{
			assertEquals(Math.max(4, Math.round(barHeight * 0.5f)), PartnerBar.barThickness(barHeight, 50));
		}
	}

	@Test
	public void theFloorHoldsAtSmallHeightsAndLowShares()
	{
		assertEquals(4, PartnerBar.barThickness(4, 20));
		assertEquals(4, PartnerBar.barThickness(16, 20));
		assertEquals(4, PartnerBar.barThickness(1, 100));
	}

	@Test
	public void theHeightIsTheRowTheBarAndTheRoomItsEndsReachInto()
	{
		// A flat bar's ends rise 2 above and below it.
		assertEquals(10 + 6 + 4, PartnerBar.height(10, 6, true, BarEnds.CLASSIC));
		assertEquals(10 + 6 + 4, PartnerBar.height(10, 6, true, BarEnds.SUBTLE));
		assertTrue(PartnerBar.height(10, 6, false, BarEnds.CLASSIC) > 10 + 6);
		assertTrue(PartnerBar.height(10, 6, false, BarEnds.SUBTLE) > 10 + 6);
	}
}

package com.ghordrin.bosshealthbar.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.tracking.DamageTracker;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class TextOutlineTest
{
	private static final Color FILL = new Color(0x40C0FF);
	private static final String TEXT = "1234";

	private static class OutlineConfig implements BossHealthBarConfig
	{
		TextOutline outline = TextOutline.SHADOW;

		@Override
		public TextOutline textOutline()
		{
			return outline;
		}

		@Override
		public boolean smoothText()
		{
			return false;
		}
	}

	@Test
	public void theDefaultIsAShadow()
	{
		assertEquals(TextOutline.SHADOW, new BossHealthBarConfig()
		{
		}.textOutline());
	}

	@Test
	public void everyEdgeDrawsTheTextItselfInTheSamePlace()
	{
		List<Point> expected = null;
		for (TextOutline outline : TextOutline.values())
		{
			final OutlineConfig config = new OutlineConfig();
			config.outline = outline;
			final BarTextPainter painter = new BarTextPainter(new DamageTracker(), config);
			painter.updateFonts();

			final BufferedImage image = new BufferedImage(120, 40, BufferedImage.TYPE_INT_ARGB);
			final Graphics2D graphics = image.createGraphics();
			painter.applyTextHints(graphics);
			painter.drawNameStyleText(graphics, TEXT, 20, 25, FILL);
			graphics.dispose();

			final List<Point> pixels = filledPixels(image);
			assertTrue(outline.name() + " drew nothing", !pixels.isEmpty());
			if (expected == null)
			{
				expected = pixels;
			}
			assertEquals(outline.name(), expected, pixels);
		}
	}

	@Test
	public void theTextMetricsDoNotDependOnTheEdge()
	{
		Integer width = null;
		for (TextOutline outline : TextOutline.values())
		{
			final OutlineConfig config = new OutlineConfig();
			config.outline = outline;
			final BarTextPainter painter = new BarTextPainter(new DamageTracker(), config);
			painter.updateFonts();
			final int stringWidth = painter.nameMetrics().stringWidth(TEXT);
			if (width == null)
			{
				width = stringWidth;
			}
			assertEquals(outline.name(), width.intValue(), stringWidth);
		}
	}

	// Where the fill color itself landed. The edge is drawn under it, so these pixels are the text.
	private static List<Point> filledPixels(BufferedImage image)
	{
		final List<Point> pixels = new ArrayList<>();
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (image.getRGB(x, y) == (FILL.getRGB() | 0xFF000000))
				{
					pixels.add(new Point(x, y));
				}
			}
		}
		return pixels;
	}
}

package com.ghordrin.bosshealthbar.theme;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import org.junit.Test;

public class CustomColorsTest
{
	// Text has to stay readable over the game, and every color has to be set for the panel to show it.
	@Test
	public void randomColorsAreCompleteAndReadable()
	{
		for (long seed = 0; seed < 2000; seed++)
		{
			final ThemeColors colors = CustomColors.randomColors(new Random(seed));
			for (Map.Entry<String, Color> entry : CustomColors.keyedColors(colors).entrySet())
			{
				assertNotNull(entry.getKey(), entry.getValue());
			}
			for (Color text : Arrays.asList(colors.getText(), colors.getLevelText(), colors.getHitpointsText(),
				colors.getDefeatedText()))
			{
				assertTrue("seed " + seed, Color.RGBtoHSB(text.getRed(), text.getGreen(), text.getBlue(), null)[2] >= 0.8f);
			}
		}
	}

	@Test
	public void everyHarmonyComesUpAndTheWeightsHold()
	{
		final Map<CustomColors.Harmony, Integer> counts = new EnumMap<>(CustomColors.Harmony.class);
		final Random random = new Random(1);
		for (int i = 0; i < 10000; i++)
		{
			counts.merge(CustomColors.Harmony.pick(random), 1, Integer::sum);
		}
		assertEquals(CustomColors.Harmony.values().length, counts.size());
		assertTrue(counts.get(CustomColors.Harmony.ANALOGOUS) > counts.get(CustomColors.Harmony.TRIADIC));
	}

	private static final ThemeColors COLORS = ThemeColors.builder()
		.fillHigh(new Color(1))
		.fillLow(new Color(2))
		.trail(new Color(3))
		.frame(new Color(4))
		.text(new Color(5))
		.levelText(new Color(6))
		.hitpointsText(new Color(7))
		.defeatedText(new Color(8))
		.build();

	@Test
	public void everyCustomColorKeyGetsItsOwnColor()
	{
		final Map<String, Color> keyed = CustomColors.keyedColors(COLORS.toBuilder().track(new Color(9)).build());
		// Saved key names: changing one resets that colour for every user.
		assertEquals(Arrays.asList("customFillHighColor", "customFillLowColor", "customTrackColor", "customTrailColor",
			"customFrameColor", "customTextColor", "customLevelTextColor", "customHitpointsTextColor",
			"customDefeatedTextColor", "customDamageTextColor", "customDelveLevelTextColor",
			"customCombatLevelTextColor", "customFightTimerTextColor", "customKillCountTextColor",
			"customWeaknessTextColor", "customDrainCapTextColor", "customDefenceTextColor",
			"customSpecialAttackTextColor"),
			new ArrayList<>(keyed.keySet()));
		final Color none = BossHealthBarConfig.TRANSPARENT;
		assertEquals(Arrays.asList(new Color(1), new Color(2), new Color(9), new Color(3), new Color(4), new Color(5),
			new Color(6), new Color(7), new Color(8), none, none, none, none, none, none, none, none, none),
			new ArrayList<>(keyed.values()));
	}

	// Only the Oldschool theme has a background of its own, so switching from any other has to clear it
	// rather than leave the one the user picked last time under the new colours.
	@Test
	public void aThemeWithoutABackgroundLeavesThePickerTransparent()
	{
		assertEquals(BossHealthBarConfig.TRANSPARENT,
			CustomColors.keyedColors(COLORS).get("customTrackColor"));
	}

	// The prompt to switch themes hangs off this, so a color the set doesn't know about would change
	// nothing and say nothing.
	@Test
	public void everyColorTheThemeWritesCountsAsAColorKey()
	{
		for (String key : CustomColors.keyedColors(COLORS).keySet())
		{
			assertTrue(key, CustomColors.isColorKey(key));
		}
		assertFalse(CustomColors.isColorKey(BossHealthBarConfig.THEME_KEY));
		assertFalse(CustomColors.isColorKey(BossHealthBarConfig.CUSTOM_ICON_ITEM_ID_KEY));
	}

	// The painter reads null as "draw the themed background", which is what an unpicked color has to mean.
	@Test
	public void onlyAnOpaqueBackgroundReachesTheBar()
	{
		assertNull(CustomColors.picked(BossHealthBarConfig.TRANSPARENT));
		assertNull(CustomColors.picked(null));
		assertNull(CustomColors.picked(new Color(180, 0, 0, 0)));
		assertEquals(new Color(0xB40000), CustomColors.picked(new Color(0xB40000)));
	}

	@Test
	public void theCustomThemeReadsEveryCustomColor()
	{
		final BossHealthBarConfig config = new BossHealthBarConfig()
		{
			@Override
			public Color customFillHighColor()
			{
				return COLORS.getFillHigh();
			}

			@Override
			public Color customFillLowColor()
			{
				return COLORS.getFillLow();
			}

			@Override
			public Color customTrackColor()
			{
				return BossHealthBarConfig.TRANSPARENT;
			}

			@Override
			public Color customTrailColor()
			{
				return COLORS.getTrail();
			}

			@Override
			public Color customFrameColor()
			{
				return COLORS.getFrame();
			}

			@Override
			public Color customTextColor()
			{
				return COLORS.getText();
			}

			@Override
			public Color customLevelTextColor()
			{
				return COLORS.getLevelText();
			}

			@Override
			public Color customHitpointsTextColor()
			{
				return COLORS.getHitpointsText();
			}

			@Override
			public Color customDefeatedTextColor()
			{
				return COLORS.getDefeatedText();
			}
		};
		assertEquals(COLORS, CustomColors.fromConfig(config));
	}
}

package com.ghordrin.bosshealthbar.theme;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.render.BarEnds;
import com.ghordrin.bosshealthbar.render.BarPainter;
import org.junit.Test;

public class OldschoolThemeTest
{
	@Test
	public void oldschoolIsFlatAndNotInTheDropdown()
	{
		assertTrue(FlatTheme.OLDSCHOOL.isFlat());
		assertTrue(FlatTheme.CUSTOM.isFlat());
		for (HealthBarTheme theme : HealthBarTheme.values())
		{
			assertFalse(theme.name(), theme.isFlat());
			assertNotEquals(FlatTheme.OLDSCHOOL.name(), theme.name());
		}
	}

	@Test
	public void checkboxOverridesTheDropdown()
	{
		assertSame(FlatTheme.OLDSCHOOL, BarTheme.effective(true, HealthBarTheme.SARADOMIN));
		assertSame(HealthBarTheme.SARADOMIN, BarTheme.effective(false, HealthBarTheme.SARADOMIN));
		assertSame(HealthBarTheme.CUSTOM, BarTheme.effective(false, HealthBarTheme.CUSTOM));
	}

	@Test
	public void customColorsTheOldschoolBar()
	{
		assertSame(FlatTheme.CUSTOM, BarTheme.effective(true, HealthBarTheme.CUSTOM));
		assertNull(FlatTheme.CUSTOM.getColors());
		assertNull(FlatTheme.CUSTOM.getIcon());
	}

	@Test
	public void oldschoolHasAPlainTrackAndOneFillColor()
	{
		final ThemeColors colors = FlatTheme.OLDSCHOOL.getColors();
		assertNotNull(colors.getTrack());
		assertEquals(colors.getFillHigh(), colors.getFillLow());
		assertNull(FlatTheme.OLDSCHOOL.getIcon());
		assertNull(HealthBarTheme.ZAMORAK.getColors().getTrack());
	}

	@Test
	public void flatBarsOnlyReserveRoomForTheOutline()
	{
		for (int height = 4; height <= 24; height++)
		{
			for (BarEnds ends : BarEnds.values())
			{
				assertEquals(1, BarPainter.capWidth(height, true, ends));
				assertEquals(2, BarPainter.capRise(height, true, ends));
			}
			assertEquals(BarPainter.scaledCapWidth(height), BarPainter.capWidth(height, false, BarEnds.CLASSIC));
			assertEquals(BarPainter.scaledCapRise(height), BarPainter.capRise(height, false, BarEnds.CLASSIC));
		}
	}
}

package com.ghordrin.bosshealthbar.theme;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class PaletteCodeTest
{
	private static final Color NONE = BossHealthBarConfig.TRANSPARENT;

	private static List<Color> nine()
	{
		return new ArrayList<>(Arrays.asList(new Color(0x96161A), new Color(0x6A0C0C), NONE, new Color(0xD6B254),
			new Color(0x7A6C54), new Color(0xE8E2D4), new Color(0xA99F90), new Color(0xC8C0B0), new Color(0xB6AEA1)));
	}

	@Test
	public void aCodeReadsBackAsTheSameColorsAndIcon()
	{
		final List<Color> colors = nine();
		colors.add(new Color(0x80FF0000, true));
		colors.add(NONE);
		final String code = PaletteCode.encode(colors, -1, 1234);
		assertEquals("bhb1:96161A.6A0C0C..D6B254.7A6C54.E8E2D4.A99F90.C8C0B0.B6AEA1.80FF0000.:s1234", code);

		final PaletteCode.Palette palette = PaletteCode.decode(code);
		assertNotNull(palette);
		assertEquals(colors, palette.getColors());
		assertEquals(-1, palette.getIconItemId());
		assertEquals(1234, palette.getIconSpriteId());
	}

	@Test
	public void anItemIconAndNoIconBothTravel()
	{
		assertEquals(4151, PaletteCode.decode(PaletteCode.encode(nine(), 4151, -1)).getIconItemId());
		final PaletteCode.Palette none = PaletteCode.decode(PaletteCode.encode(nine(), -1, -1));
		assertEquals(-1, none.getIconItemId());
		assertEquals(-1, none.getIconSpriteId());
	}

	@Test
	public void aCodePastedFromAChatStillReads()
	{
		final String code = PaletteCode.encode(nine(), -1, -1);
		assertNotNull(PaletteCode.decode("  " + code.toUpperCase() + "\n"));
		assertNotNull(PaletteCode.decode(code.toLowerCase()));
	}

	@Test
	public void anythingElseIsNotACode()
	{
		assertNull(PaletteCode.decode(null));
		assertNull(PaletteCode.decode("{\"settings\":{}}"));
		assertNull(PaletteCode.decode("bhb1:96161A"));
		assertNull(PaletteCode.decode(PaletteCode.encode(nine(), -1, -1).replace("96161A", "96161")));
		assertNull(PaletteCode.decode(PaletteCode.encode(nine(), -1, -1).replace("96161A", "ZZZZZZ")));
		assertNull(PaletteCode.decode(PaletteCode.encode(nine(), -1, -1) + ":x12"));
		assertNull(PaletteCode.decode(PaletteCode.encode(nine(), -1, -1) + ":i12:s3"));
	}

	// A fill or text color left out would make that part of the bar vanish, so only the background may be.
	@Test
	public void onlyTheBackgroundMayBeLeftEmpty()
	{
		final List<Color> colors = nine();
		colors.set(0, NONE);
		assertNull(PaletteCode.decode(PaletteCode.encode(colors, -1, -1)));
	}

	@Test
	public void theCodeKeepsTheCustomColorsInTheirListedOrder()
	{
		final BossHealthBarConfig defaults = new BossHealthBarConfig()
		{
		};
		assertEquals(new ArrayList<>(CustomColors.keyedColors(ThemeColors.builder().build()).keySet()),
			new ArrayList<>(CustomColors.configuredColors(defaults).keySet()));
		assertNotNull(PaletteCode.decode(CustomColors.code(defaults)));
	}
}

package com.ghordrin.bosshealthbar.theme;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import java.awt.Color;
import org.junit.Test;

public class PhaseColorsTest
{
	// Read off the game's own bar during a kill: green for the usual phases, purple for a shielded one.
	// Nothing else in the code holds these, and a wrong green would color every boss.
	private static final int GAME_FILL = 0x00C800;
	private static final int GAME_TRAIL = 0x009000;
	private static final int GAME_TRACK = 0xC80000;
	private static final int SHIELD_FILL = 0x7040C8;
	private static final int SHIELD_TRAIL = 0x382068;
	private static final int SHIELD_TRACK = 0x100820;

	private static final ThemeColors THEME = ThemeColors.builder()
		.fillHigh(new Color(1))
		.fillLow(new Color(2))
		.trail(new Color(3))
		.track(new Color(4))
		.frame(new Color(5))
		.text(new Color(6))
		.levelText(new Color(7))
		.hitpointsText(new Color(8))
		.defeatedText(new Color(9))
		.build();

	@Test
	public void theColorsEveryBossGetsAreNotAPhase()
	{
		assertNull(PhaseColors.of(GAME_FILL, GAME_TRAIL, GAME_TRACK));
	}

	// The bar reads as black before the game fills it in, which is not the game saying anything.
	@Test
	public void aBarWithNoColorYetIsNotAPhase()
	{
		assertNull(PhaseColors.of(0, 0, 0));
	}

	// Only what the game recolors is recolored, so the frame and the text stay the theme's.
	@Test
	public void thePhaseTakesTheFillTheTrailAndTheTrack()
	{
		final ThemeColors colors = PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK)
			.applyTo(THEME, BossHealthBarConfig.TRANSPARENT, false);

		assertEquals(new Color(SHIELD_FILL), colors.getFillHigh());
		assertEquals(new Color(SHIELD_FILL), colors.getFillLow());
		assertEquals(new Color(SHIELD_TRAIL), colors.getTrail());
		assertEquals(new Color(SHIELD_TRACK), colors.getTrack());
		assertEquals(THEME.getFrame(), colors.getFrame());
		assertEquals(THEME.getText(), colors.getText());
		assertEquals(THEME.getDefeatedText(), colors.getDefeatedText());
	}

	// A picked color is one color, so the fill is it and the rest comes off it.
	@Test
	public void anOverrideIsUsedInsteadOfTheGameSColor()
	{
		final Color override = new Color(0xB48200);
		final ThemeColors colors = PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK)
			.applyTo(THEME, override, false);

		assertEquals(override, colors.getFillHigh());
		assertEquals(override, colors.getFillLow());
		assertEquals(THEME.getFrame(), colors.getFrame());
	}

	// Fortify puts the phase on the frame too, lifted off the fill so it still reads as an outline.
	@Test
	public void fortifyGivesTheFrameThePhaseSColor()
	{
		final ThemeColors colors = PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK)
			.applyTo(THEME, BossHealthBarConfig.TRANSPARENT, true);

		assertNotEquals(THEME.getFrame(), colors.getFrame());
		assertNotEquals(colors.getFillHigh(), colors.getFrame());
		assertEquals(new Color(SHIELD_FILL), colors.getFillHigh());
	}

	// A phase the player picked a color for puts that color on the frame, not the game's.
	@Test
	public void fortifyFollowsTheOverrideOnTheFrame()
	{
		final Color override = new Color(0xB48200);
		final ThemeColors game = PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK)
			.applyTo(THEME, BossHealthBarConfig.TRANSPARENT, true);
		final ThemeColors picked = PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK)
			.applyTo(THEME, override, true);

		assertNotEquals(game.getFrame(), picked.getFrame());
	}

	// One phase to the next is a change, so the run plays again instead of the bar sitting still.
	@Test
	public void eachPhaseHasItsOwnKey()
	{
		assertNotEquals(PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK).key(),
			PhaseColors.of(0xC87040, SHIELD_TRAIL, SHIELD_TRACK).key());
	}

	// Zero is how the bar says there is no phase at all, so no phase color may land on it.
	@Test
	public void noPhaseSKeyIsNeverAPhaseSKey()
	{
		assertNotEquals(0, PhaseColors.of(SHIELD_FILL, SHIELD_TRAIL, SHIELD_TRACK).key());
	}
}

package com.ghordrin.bosshealthbar.theme;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import org.junit.Test;

public class ThemeColorsTest
{
	@Test
	public void itemTextFollowsItsSharedColorUntilItHasItsOwn()
	{
		final Color name = new Color(1);
		final Color level = new Color(2);
		final Color own = new Color(3);
		final ThemeColors shared = ThemeColors.builder().text(name).levelText(level).build();
		assertEquals(name, shared.getDamageText());
		assertEquals(name, shared.getDelveLevelText());
		assertEquals(level, shared.getCombatLevelText());
		assertEquals(level, shared.getFightTimerText());
		assertEquals(level, shared.getKillCountText());
		assertEquals(level, shared.getWeaknessText());
		assertEquals(level, shared.getDrainCapText());

		final ThemeColors picked = shared.toBuilder().damageText(own).combatLevelText(own).killCountText(own).build();
		assertEquals(own, picked.getDamageText());
		assertEquals(own, picked.getCombatLevelText());
		assertEquals(own, picked.getKillCountText());
		assertEquals(level, picked.getFightTimerText());
	}

	@Test
	public void anotherPluginsColorStaysUntilOneIsPicked()
	{
		final Color name = new Color(1);
		final Color plugin = new Color(4);
		final Color own = new Color(5);
		final ThemeColors shared = ThemeColors.builder().text(name).build();
		assertEquals(plugin, shared.defenceText(plugin));
		assertEquals(name, shared.defenceText(null));
		assertEquals(plugin, shared.specialAttackText(plugin));
		assertEquals(name, shared.specialAttackText(null));

		final ThemeColors picked = shared.toBuilder().defenceText(own).specialAttackText(own).build();
		assertEquals(own, picked.defenceText(plugin));
		assertEquals(own, picked.specialAttackText(null));
	}

	@Test
	public void aFlatThemeOnlyTakesTheBossFillColor()
	{
		final ThemeColors theme = FlatTheme.OLDSCHOOL.getColors();
		final ThemeColors boss = HealthBarTheme.BANDOS.getColors();
		assertEquals(ThemeColors.withBase(theme, boss.getFillHigh()), ThemeColors.withBoss(theme, boss, true));
		assertSame(boss, ThemeColors.withBoss(theme, boss, false));
		assertSame(theme, ThemeColors.withBoss(theme, null, false));
		assertSame(theme, ThemeColors.withBoss(theme, null, true));
	}

	@Test
	public void themesKeepTheirColors()
	{
		final ThemeColors zamorak = HealthBarTheme.ZAMORAK.getColors();
		assertEquals(new Color(0xB01818), zamorak.getFillHigh());
		assertEquals(new Color(0x6A0C0C), zamorak.getFillLow());
		assertEquals(new Color(0xF0A030), zamorak.getTrail());
		assertEquals(new Color(0x5A4E4E), zamorak.getFrame());
		assertEquals(ColorUtil.brighten(new Color(0x5A4E4E), 0.35f), zamorak.getLevelText());
	}

	@Test
	public void derivedColorsStayReadableForAnyBase()
	{
		for (float hue = 0f; hue < 1f; hue += 1f / 36f)
		{
			for (float saturation : new float[]{0.05f, 0.3f, 0.6f, 0.9f})
			{
				for (float brightness : new float[]{0.45f, 0.7f, 0.95f})
				{
					final Color base = Color.getHSBColor(hue, saturation, brightness);
					final ThemeColors colors = ThemeColors.fromBase(base);
					final String label = String.format("base %06X", base.getRGB() & 0xFFFFFF);

					assertEquals(label, base, colors.getFillHigh());
					assertTrue(label, brightness(colors.getFillLow()) < brightness(base));
					assertTrue(label, ThemeColors.contrast(colors.getTrail(), base) >= 1.5f
						|| hueGap(colors.getTrail(), base) >= 0.25f);
				}
			}
		}
	}

	@Test
	public void aBaseAwayFromTheFlatTrackKeepsThatTrack()
	{
		final ThemeColors flat = FlatTheme.OLDSCHOOL.getColors();
		final ThemeColors colors = ThemeColors.withBase(flat, new Color(0x3CB043));
		assertEquals(flat.getTrack(), colors.getTrack());
		assertEquals(new Color(0x3CB043), colors.getFillHigh());
		assertEquals(new Color(0x3CB043), colors.getFillLow());
	}

	@Test
	public void aBaseTooCloseToTheFlatTrackGetsADarkerOneOfItsOwn()
	{
		final ThemeColors flat = FlatTheme.OLDSCHOOL.getColors();
		final Color base = new Color(0xB40000);
		final ThemeColors colors = ThemeColors.withBase(flat, base);
		assertTrue(brightness(colors.getTrack()) < brightness(base));
		assertTrue(ThemeColors.contrast(base, colors.getTrack()) >= 1.6f);
	}

	@Test
	public void theFlatBarStaysReadableAndKeepsItsOwnFrameAndTextForAnyBase()
	{
		final ThemeColors flat = FlatTheme.OLDSCHOOL.getColors();
		for (float hue = 0f; hue < 1f; hue += 1f / 72f)
		{
			for (float saturation : new float[]{0.05f, 0.3f, 0.6f, 0.9f, 1f})
			{
				for (float brightness = 0.3f; brightness <= 1f; brightness += 0.02f)
				{
					final Color base = Color.getHSBColor(hue, saturation, brightness);
					final ThemeColors colors = ThemeColors.withBase(flat, base);
					final String label = String.format("base %06X", base.getRGB() & 0xFFFFFF);

					assertEquals(label, base, colors.getFillHigh());
					assertEquals(label, base, colors.getFillLow());
					assertTrue(label, ThemeColors.contrast(base, colors.getTrack()) >= 1.6f);
					assertTrue(label, ThemeColors.contrast(colors.getTrail(), base) >= 1.5f
						|| hueGap(colors.getTrail(), base) >= 0.25f);

					assertEquals(label, flat.getFrame(), colors.getFrame());
					assertEquals(label, flat.getText(), colors.getText());
					assertEquals(label, flat.getLevelText(), colors.getLevelText());
					assertEquals(label, flat.getHitpointsText(), colors.getHitpointsText());
					assertEquals(label, flat.getDefeatedText(), colors.getDefeatedText());
				}
			}
		}
	}

	private static float brightness(Color c)
	{
		return Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null)[2];
	}

	private static float hueGap(Color a, Color b)
	{
		final float ha = Color.RGBtoHSB(a.getRed(), a.getGreen(), a.getBlue(), null)[0];
		final float hb = Color.RGBtoHSB(b.getRed(), b.getGreen(), b.getBlue(), null)[0];
		final float gap = Math.abs(ha - hb);
		return Math.min(gap, 1f - gap);
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static com.ghordrin.bosshealthbar.tracking.BossMemory.FORGET_TICKS;
import static com.ghordrin.bosshealthbar.tracking.BossMemory.HOLD_TICKS;
import static com.ghordrin.bosshealthbar.tracking.BossMemory.MAX_ENTRIES;
import static com.ghordrin.bosshealthbar.tracking.FightTimer.NO_TICK;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BossMemoryTest
{
	private static final FightTimer.Fight FIGHT = new FightTimer.Fight(1, 10, NO_TICK);

	private final BossMemory memory = new BossMemory();

	@Test
	public void onlyAnOpponentFarAwayWentOutOfSight()
	{
		assertFalse(BossMemory.isOutOfSight(false, 10));
		assertFalse(BossMemory.isOutOfSight(false, 14));
		assertTrue(BossMemory.isOutOfSight(false, 15));
		assertTrue(BossMemory.isOutOfSight(false, Integer.MAX_VALUE));
		assertFalse(BossMemory.isOutOfSight(false, -1));
	}

	@Test
	public void dyingToTheOpponentIsNotWalkingAway()
	{
		assertFalse(BossMemory.isOutOfSight(true, 20));
	}

	@Test
	public void distanceIsFromTheSouthWestTile()
	{
		assertEquals(0, BossMemory.tileDistance(100, 100, 100, 100));
		assertEquals(14, BossMemory.tileDistance(100, 100, 114, 105));
		assertEquals(15, BossMemory.tileDistance(100, 100, 95, 115));
		assertEquals(16, BossMemory.tileDistance(100, 100, 84, 100));
	}

	@Test
	public void clearlyMoreHealthOnReturnIsANewFight()
	{
		assertFalse(BossMemory.healedSince(15, 30, false, 15, 30));
		assertFalse(BossMemory.healedSince(15, 30, false, 20, 30));
		assertTrue(BossMemory.healedSince(15, 30, false, 22, 30));
		assertTrue(BossMemory.healedSince(0, 1000, true, 900, 1000));
		assertFalse(BossMemory.healedSince(500, 1000, true, 10, 30));
		assertFalse(BossMemory.healedSince(0, 0, false, 30, 30));
	}

	@Test
	public void healthBackFromAnOverheadZeroIsNotAHeal()
	{
		assertFalse(BossMemory.healedSince(0, 30, false, 30, 30));
		assertTrue(BossMemory.healedSince(0, 30, true, 30, 30));
	}

	@Test
	public void remembersByIndexAndName()
	{
		memory.remember(5, "Boss", 100, FIGHT);
		assertNull(memory.find(6, "Boss", 101));
		final BossMemory.Entry entry = memory.find(5, "Boss", 101);
		assertNotNull(entry);
		assertSame(FIGHT, entry.fight);
	}

	@Test
	public void aDifferentNameAtTheSameIndexForgetsIt()
	{
		memory.remember(5, "Boss", 100, FIGHT);
		assertNull(memory.find(5, "Goblin", 101));
		assertNull(memory.find(5, "Boss", 102));
	}

	@Test
	public void forgetsAfterTheTimeLimit()
	{
		memory.remember(5, "Boss", 100, FIGHT);
		assertNotNull(memory.find(5, "Boss", 100 + FORGET_TICKS));
		assertNull(memory.find(5, "Boss", 101 + FORGET_TICKS));
		assertEquals(0, memory.size());
	}

	@Test
	public void dropsTheOldestWhenFull()
	{
		for (int i = 0; i <= MAX_ENTRIES; i++)
		{
			memory.remember(i, "Boss", 100 + i, FIGHT);
		}
		assertEquals(MAX_ENTRIES, memory.size());
		assertFalse(memory.contains(0));
		assertTrue(memory.contains(1));
		assertTrue(memory.contains(MAX_ENTRIES));
	}

	@Test
	public void rememberingTheSameIndexAgainReplacesIt()
	{
		memory.remember(5, "Boss", 100, FIGHT);
		final BossMemory.Entry later = memory.remember(5, "Boss", 200, FIGHT);
		assertEquals(1, memory.size());
		assertSame(later, memory.find(5, "Boss", 201));
	}

	@Test
	public void takingAnEntryForgetsIt()
	{
		memory.remember(5, "Boss", 100, FIGHT);
		assertNotNull(memory.take(5, "Boss", 101));
		assertNull(memory.take(5, "Boss", 102));
	}

	@Test
	public void forgetAndClear()
	{
		memory.remember(5, "Boss", 100, FIGHT);
		memory.remember(6, "Boss", 100, FIGHT);
		memory.forget(5);
		assertFalse(memory.contains(5));
		assertTrue(memory.contains(6));
		memory.clear();
		assertEquals(0, memory.size());
	}

	@Test
	public void heldOnlyShortlyAfterGoingOutOfSight()
	{
		assertTrue(BossMemory.isHeld(100, 100 + HOLD_TICKS));
		assertFalse(BossMemory.isHeld(100, 101 + HOLD_TICKS));
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static com.ghordrin.bosshealthbar.tracking.DamageTracker.isSameAttack;
import static com.ghordrin.bosshealthbar.tracking.FightTimer.NO_TICK;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DamageTrackerTest
{
	@Test
	public void noStartTickIsNeverTheSameAttack()
	{
		assertFalse(isSameAttack(NO_TICK, 100));
		assertFalse(isSameAttack(NO_TICK, 0));
	}

	@Test
	public void theSameTickAndTheNextTickAreTheSameAttack()
	{
		assertTrue(isSameAttack(100, 100));
		assertTrue(isSameAttack(100, 101));
	}

	@Test
	public void twoTicksLaterIsANewAttack()
	{
		assertFalse(isSameAttack(100, 102));
	}

	@Test
	public void aTickFromBeforeTheStartIsANewAttack()
	{
		assertFalse(isSameAttack(100, 5));
	}

	@Test
	public void hitsOnTheSameTickAddUp()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		hit(tracker, 15, 100);

		assertEquals(35, tracker.getComboDamage());
	}

	@Test
	public void hitsTwoTicksApartStartFresh()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		hit(tracker, 15, 102);

		assertEquals(15, tracker.getComboDamage());
	}

	@Test
	public void aFourTickCadenceNeverAccumulates()
	{
		final DamageTracker tracker = new DamageTracker();
		for (int tick = 100; tick < 140; tick += 4)
		{
			hit(tracker, 25, tick);
			assertEquals(25, tracker.getComboDamage());
		}
	}

	@Test
	public void multiHitAttackAddsUpThenTheNextAttackStartsFresh()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		hit(tracker, 10, 100);
		hit(tracker, 5, 101);
		hit(tracker, 5, 101);
		assertEquals(40, tracker.getComboDamage());

		hit(tracker, 12, 105);
		assertEquals(12, tracker.getComboDamage());
	}

	@Test
	public void hitsOnEveryTickDoNotChainIntoOneTotal()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 10, 100);
		hit(tracker, 10, 101);
		hit(tracker, 10, 102);
		assertEquals(10, tracker.getComboDamage());

		hit(tracker, 10, 103);
		assertEquals(20, tracker.getComboDamage());
	}

	@Test
	public void resetComboStartsTheNextHitFresh()
	{
		final DamageTracker tracker = new DamageTracker();
		hit(tracker, 20, 100);
		tracker.resetCombo();
		hit(tracker, 15, 100);

		assertEquals(15, tracker.getComboDamage());
	}

	@Test
	public void partyHitsKeepAddingWhileTheyKeepComing()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.addToCombo(20, 1000, 100, true);
		tracker.addToCombo(15, 3400, 104, true);
		tracker.addToCombo(10, 5800, 108, true);

		assertEquals(45, tracker.getComboDamage());
	}

	@Test
	public void partyTotalStartsFreshAfterAPause()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.addToCombo(20, 1000, 100, true);
		tracker.addToCombo(15, 3501, 105, true);

		assertEquals(15, tracker.getComboDamage());
	}

	@Test
	public void zeroPartyHitsAreIgnored()
	{
		final DamageTracker tracker = new DamageTracker();
		tracker.recordPartyHit(0, 100);

		assertEquals(0, tracker.getComboDamage());
	}

	private static void hit(DamageTracker tracker, int amount, int tick)
	{
		tracker.addToCombo(amount, tick * 600L, tick, false);
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class DelveLevelTest
{
	// The varp counts finished delves, so it reads one behind the level being fought.
	@Test
	public void theLevelIsOnePastTheDelvesFinished()
	{
		assertEquals(1, DelveLevel.levelFor(0));
		assertEquals(2, DelveLevel.levelFor(1));
		assertEquals(9, DelveLevel.levelFor(8));
	}

	@Test
	public void anUnsetVarpStillReadsAsTheFirstDelve()
	{
		assertEquals(1, DelveLevel.levelFor(-1));
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.data.BarState;
import com.ghordrin.bosshealthbar.data.Health;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import org.junit.Test;

public class FightGroupTest
{
	private final FightGroup group = new FightGroup(null, new DebugLog(null));

	@Test
	public void opponentsOfTheSameFightJoinItAndANewFightStartsEmpty()
	{
		final int first = group.id();
		group.startFight(null, false, 0);
		assertNotEquals(first, group.id());
		group.join(1, "Boss", true, 0);
		group.join(2, "Minion", false, 5);
		group.join(1, "Boss", true, 10);
		assertEquals(2, group.size());

		final int fight = group.id();
		group.startFight(null, false, 20);
		assertNotEquals(fight, group.id());
		assertEquals(0, group.size());
	}

	@Test
	public void aMemberThatLeavesAliveIsKeptAwayWithItsHealth()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		FightGroup.read(member, overhead(12, 30));
		group.despawned(member, false);

		assertTrue(member.isAway());
		assertEquals(1, group.size());
		assertEquals(12, member.ratio);
		assertTrue(group.isAliveMember(7, "Boss"));
	}

	@Test
	public void aMemberThatDiesIsRemoved()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		group.despawned(member, true);
		assertEquals(0, group.size());
		assertFalse(group.isAliveMember(1, "Boss"));

		final FightGroup.Member confirmed = group.join(2, "Boss", true, 0);
		confirmed.downState.update(overheadReading(1, 60), false, true, false, 1, null, null, null);
		confirmed.downState.update(overheadReading(1, 60), false, true, false, 2, null, null, null);
		group.despawned(confirmed, false);
		assertEquals(0, group.size());
	}

	@Test
	public void aDeathReadingIsZeroOrALastBitOfHealthItCanNoLongerBeAttackedAt()
	{
		final FightGroup.Member member = new FightGroup.Member();
		FightGroup.read(member, overhead(0, 30));
		assertTrue(FightGroup.diedReading(member, true));

		FightGroup.read(member, overhead(1, 60));
		assertTrue(FightGroup.diedReading(member, false));
		assertFalse(FightGroup.diedReading(member, true));

		FightGroup.read(member, gameBar(1, 450));
		assertFalse(FightGroup.diedReading(member, false));

		assertFalse(FightGroup.diedReading(new FightGroup.Member(), false));
	}

	@Test
	public void onlyAConfirmedKillIsNotAnAliveMember()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		member.downState.update(overheadReading(0, 30), true, true, true, 1, null, null, null);
		assertTrue(group.isAliveMember(1, "Boss"));
		member.downState.defeated = true;
		assertFalse(group.isAliveMember(1, "Boss"));
		assertFalse(group.isAliveMember(2, "Other"));
	}

	@Test
	public void aReturningBossTakesBackTheOnlyAwayMemberWithItsName()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		FightGroup.read(member, overhead(12, 30));
		group.despawned(member, false);

		assertSame(member, group.join(9, "Boss", true, 50));
		assertFalse(member.isAway());
		assertEquals(12, member.ratio);
		assertEquals(1, group.size());
		assertSame(member, group.find(9));
	}

	@Test
	public void twoAwayMembersWithTheSameNameAreNotGuessed()
	{
		final FightGroup.Member first = group.join(1, "Boss", true, 0);
		final FightGroup.Member second = group.join(2, "Boss", true, 0);
		group.despawned(first, false);
		group.despawned(second, false);

		assertNull(group.awayByName("Boss"));
		assertFalse(group.isAliveMember(9, "Boss"));
		assertNotSame(first, group.join(9, "Boss", true, 10));
		assertEquals(3, group.size());
	}

	@Test
	public void onlyABossIsTakenBackByName()
	{
		final FightGroup.Member minion = group.join(1, "Minion", false, 0);
		group.despawned(minion, false);
		assertNull(group.awayByName("Minion"));
	}

	@Test
	public void thePartnerIsTheMostRecentlyFoughtOtherBossWithHealth()
	{
		final FightGroup.Member own = group.join(1, "First", true, 30);
		final FightGroup.Member older = group.join(2, "Second", true, 10);
		final FightGroup.Member newer = group.join(3, "Third", true, 20);
		final FightGroup.Member minion = group.join(4, "Minion", false, 25);
		final FightGroup.Member noHealth = group.join(5, "Fifth", true, 28);
		for (FightGroup.Member member : new FightGroup.Member[]{own, older, newer, minion})
		{
			FightGroup.read(member, overhead(20, 30));
		}

		assertSame(newer, group.choosePartner(own));
		newer.downState.defeated = true;
		assertSame(older, group.choosePartner(own));
		assertNull(noHealth.state);
	}

	@Test
	public void anAwayBossCanBeThePartner()
	{
		final FightGroup.Member own = group.join(1, "First", true, 30);
		final FightGroup.Member away = group.join(2, "Second", true, 20);
		FightGroup.read(away, overhead(20, 30));
		group.despawned(away, false);

		group.updatePartner(own, true);
		assertSame(away, group.partner());
		assertEquals("Second", group.partner().state.name);
	}

	@Test
	public void anOpponentThatIsNotABossHasNoPartner()
	{
		final FightGroup.Member own = group.join(1, "Minion", false, 30);
		final FightGroup.Member boss = group.join(2, "Boss", true, 20);
		FightGroup.read(boss, overhead(20, 30));
		assertNull(group.choosePartner(own));
		assertNull(group.choosePartner(null));
	}

	@Test
	public void thePartnerStaysWhileThereIsNoOpponent()
	{
		final FightGroup.Member own = group.join(1, "First", true, 30);
		final FightGroup.Member other = group.join(2, "Second", true, 20);
		FightGroup.read(other, overhead(20, 30));
		group.updatePartner(own, true);
		group.updatePartner(null, false);
		assertSame(other, group.partner());

		group.despawned(other, true);
		assertNull(group.partner());
	}

	@Test
	public void theOldestIsDroppedWhenFull()
	{
		for (int i = 0; i < FightGroup.MAX_MEMBERS; i++)
		{
			group.join(i, "Npc " + i, false, 100 - i);
		}
		group.join(50, "New", false, 200);
		assertEquals(FightGroup.MAX_MEMBERS, group.size());
		assertNull(group.find(FightGroup.MAX_MEMBERS - 1));
		assertEquals("New", group.find(50).name);
	}

	@Test
	public void aGroupFightLastsUntilTheNextFight()
	{
		final FightGroup.Member first = group.join(1, "First", true, 0);
		group.join(2, "Minion", false, 0);
		assertFalse(group.isGroupFight());

		group.join(3, "Second", true, 5);
		assertTrue(group.isGroupFight());
		group.despawned(first, true);
		assertTrue(group.isGroupFight());

		group.startFight(null, false, 50);
		assertFalse(group.isGroupFight());
	}

	@Test
	public void aMinionThatTurnsOutToBeABossCountsOnce()
	{
		group.join(1, "First", true, 0);
		group.join(2, "Second", false, 0);
		assertFalse(group.isGroupFight());
		group.join(2, "Second", true, 1);
		group.join(2, "Second", true, 2);
		assertTrue(group.isGroupFight());
	}

	@Test
	public void restoringAnotherFightStartsFromItsMember()
	{
		group.join(1, "Boss", true, 0);
		final int fight = group.id();
		group.startFight(null, false, 10);
		group.join(2, "Other", true, 10);

		group.restore(fight, null, true, 20);
		assertEquals(fight, group.id());
		assertEquals(0, group.size());

		group.join(3, "Third", true, 20);
		group.restore(fight, null, true, 30);
		assertEquals(1, group.size());
	}

	@Test
	public void awayMembersAreForgottenAfterAWhile()
	{
		final FightGroup.Member away = group.join(1, "Boss", true, 0);
		final FightGroup.Member present = group.join(2, "Other", true, 0);
		group.despawned(away, false);

		group.expireAway(BossMemory.FORGET_TICKS);
		assertEquals(2, group.size());
		group.expireAway(BossMemory.FORGET_TICKS + 1);
		assertEquals(1, group.size());
		assertSame(present, group.find(2));
	}

	@Test
	public void aMemberAtZeroShowsTheZeroAndIsOnlyDeadOnceConfirmed()
	{
		final FightGroup.Member member = new FightGroup.Member();
		FightGroup.read(member, overhead(20, 30));

		member.downState.update(overheadReading(0, 30), true, true, true, 1, null, null, null);
		assertTrue(FightGroup.read(member, overhead(0, 30)));
		assertReading(member, 0, 30, false, 450);
		assertTrue(member.downState.down);
		assertFalse(member.isDead());

		// Healing back from 0 carries on from there.
		member.downState.update(overheadReading(12, 30), false, true, true, 2, null, null, null);
		assertTrue(FightGroup.read(member, overhead(12, 30)));
		assertReading(member, 12, 30, false, 450);
		assertFalse(member.downState.down);
		assertFalse(member.isDead());
	}

	@Test
	public void aMemberIsDeadOnceItCanNoLongerBeAttackedForTwoTicks()
	{
		final FightGroup.Member member = new FightGroup.Member();
		member.downState.update(overheadReading(0, 30), true, true, false, 1, null, null, null);
		assertFalse(member.isDead());
		member.downState.update(overheadReading(0, 30), true, true, false, 2, null, null, null);
		assertTrue(member.isDead());
	}

	@Test
	public void aMemberBackUpAfterAConfirmedKillStartsANewLife()
	{
		final FightGroup.Member own = group.join(1, "First", true, 0);
		FightGroup.read(own, overhead(10, 30));
		final FightGroup.Member member = group.join(2, "Second", true, 0);
		FightGroup.read(member, overhead(20, 30));
		member.downState.update(overheadReading(0, 30), true, true, false, 1, null, null, null);
		member.downState.update(overheadReading(0, 30), true, true, false, 2, null, null, null);
		member.downState.update(null, false, true, false, 3, null, null, null);
		assertTrue(member.isDead());
		assertFalse(group.isAliveMember(2, "Second"));
		assertNull(group.choosePartner(own));
		assertFalse(FightGroup.startNewLife(member));

		// Back with full health well after the kill, so this is the next one and not another phase.
		member.downState.update(overheadReading(30, 30), false, true, true, 20, null, null, null);
		assertTrue(FightGroup.startNewLife(member));
		assertFalse(member.isDead());
		assertTrue(group.isAliveMember(2, "Second"));
		assertEquals(-1, member.ratio);
		assertEquals(-1, member.scale);
		assertNull(member.maxHealth);
		assertNull(member.state);

		FightGroup.read(member, overhead(30, 30));
		assertSame(member, group.choosePartner(own));
		group.despawned(member, false);
		assertSame(member, group.awayByName("Second"));
	}

	@Test
	public void eachReadingIsKeptAndNoReadingKeepsTheLastOne()
	{
		final FightGroup.Member member = new FightGroup.Member();

		assertTrue(FightGroup.read(member, gameBar(300, 450)));
		assertReading(member, 300, 450, true, 450);

		assertTrue(FightGroup.read(member, overhead(15, 30)));
		assertReading(member, 15, 30, false, 450);

		// The overhead bar went away, so the last reading stays.
		assertFalse(FightGroup.read(member, null));
		assertReading(member, 15, 30, false, 450);

		// An overhead bar with no value isn't a reading either.
		assertFalse(FightGroup.read(member, overhead(-1, 60)));
		assertReading(member, 15, 30, false, 450);
	}

	@Test
	public void theStateIsOnlyRebuiltWhenTheReadingChanges()
	{
		final FightGroup.Member member = new FightGroup.Member();
		FightGroup.read(member, overhead(15, 30));
		member.state = BarState.healthOnly("Test", new Health(15, 30, false, 450, false));
		final BarState state = member.state;

		assertFalse(FightGroup.read(member, overhead(15, 30)));
		assertSame(state, member.state);

		assertTrue(FightGroup.read(member, overhead(14, 30)));
		assertNull(member.state);
	}

	@Test
	public void theRememberedHealthIsFoundByIndexAndName()
	{
		final Health first = gameBar(300, 500);
		final Health second = gameBar(200, 500);
		FightGroup.read(group.join(1, "Boss", true, 0), first);
		FightGroup.read(group.join(2, "Boss", true, 0), second);

		assertSame(first, group.rememberedHealth(1, "Boss"));
		assertSame(second, group.rememberedHealth(2, "Boss"));
		assertNull(group.rememberedHealth(1, "Other"));
		assertNull(group.rememberedHealth(1, null));
	}

	// An NPC that leaves and comes back gets a new index, and isn't always linked back to the member it left as.
	@Test
	public void aSingleMemberWithTheNameCoversAMemberWithoutAReading()
	{
		final Health health = gameBar(300, 500);
		final FightGroup.Member left = group.join(1, "Npc", false, 0);
		FightGroup.read(left, health);
		FightGroup.read(group.join(2, "Minion", false, 0), gameBar(50, 500));
		group.despawned(left, false);

		final FightGroup.Member back = group.join(9, "Npc", false, 10);
		assertNull(back.lastAboveZero);
		assertSame(health, group.rememberedHealth(9, "Npc"));
	}

	@Test
	public void anOpponentBackFromMemoryBringsItsRememberedHealthToANewGroup()
	{
		FightGroup.read(group.join(1, "Boss", true, 0), gameBar(300, 500));
		final int fight = group.id();
		group.startFight(null, false, 50);
		group.join(2, "Other", true, 50);

		// The fight it belonged to was cleared meanwhile, so it rejoins without its reading.
		group.restore(fight, null, true, 60);
		group.join(9, "Boss", true, 60);
		assertNull(group.rememberedHealth(9, "Boss"));

		final Health remembered = gameBar(300, 500);
		group.restoreHealth(9, remembered);
		assertSame(remembered, group.rememberedHealth(9, "Boss"));

		// A member that read its own health keeps it.
		group.restoreHealth(9, gameBar(10, 500));
		assertSame(remembered, group.rememberedHealth(9, "Boss"));
	}

	@Test
	public void severalMembersWithTheNameAreNotGuessed()
	{
		FightGroup.read(group.join(1, "Boss", true, 0), gameBar(300, 500));
		FightGroup.read(group.join(2, "Boss", true, 0), gameBar(200, 500));
		assertNull(group.rememberedHealth(9, "Boss"));
	}

	@Test
	public void aNewReadingReplacesTheRememberedOne()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		FightGroup.read(member, gameBar(300, 500));
		final Health newer = gameBar(250, 500);
		FightGroup.read(member, newer);
		assertSame(newer, group.rememberedHealth(1, "Boss"));
		assertSame(newer, group.rememberedHealth(5, "Boss"));
	}

	@Test
	public void theRememberedHealthGoesWithTheMemberThatIsDropped()
	{
		for (int i = 0; i < FightGroup.MAX_MEMBERS; i++)
		{
			FightGroup.read(group.join(i, "Npc " + i, false, 100 - i), gameBar(100 + i, 500));
		}
		FightGroup.read(group.join(50, "New", false, 200), gameBar(400, 500));

		assertNull(group.rememberedHealth(FightGroup.MAX_MEMBERS - 1, "Npc " + (FightGroup.MAX_MEMBERS - 1)));
		assertNotNull(group.rememberedHealth(50, "New"));
		assertNotNull(group.rememberedHealth(1, "Npc 1"));
	}

	@Test
	public void anotherFightDoesntSeeTheRememberedHealth()
	{
		FightGroup.read(group.join(1, "Boss", true, 0), gameBar(300, 500));
		group.startFight(null, false, 10);
		assertNull(group.rememberedHealth(1, "Boss"));
		assertNull(group.rememberedHealth(2, "Boss"));
	}

	// A 0 isn't remembered, so the last health above it stays for an opponent that can still come back from it.
	@Test
	public void aZeroOrNoValueKeepsTheLastHealthAboveIt()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		final Health above = overhead(40, 60);
		FightGroup.read(member, above);
		FightGroup.read(member, overhead(0, 60));
		assertSame(above, group.rememberedHealth(1, "Boss"));

		FightGroup.read(group.join(2, "Other", true, 0), overhead(0, 60));
		assertNull(group.rememberedHealth(2, "Other"));

		FightGroup.read(member, new Health(-1, 60, false, 450, false));
		assertSame(above, group.rememberedHealth(1, "Boss"));
	}

	@Test
	public void aReadingWithoutHealthIsNotRemembered()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		FightGroup.read(member, new Health(-1, -1, false, null, false));
		FightGroup.read(member, null);
		assertNull(group.rememberedHealth(1, "Boss"));
	}

	@Test
	public void aNewLifeForgetsTheRememberedHealth()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		FightGroup.read(member, overhead(20, 30));
		member.downState.update(overheadReading(0, 30), true, true, false, 1, null, null, null);
		member.downState.update(overheadReading(0, 30), true, true, false, 2, null, null, null);
		member.downState.update(overheadReading(30, 30), false, true, true, 20, null, null, null);

		assertTrue(FightGroup.startNewLife(member));
		assertNull(group.rememberedHealth(1, "Boss"));
	}

	// A cleared group keeps no member by name, so a same-named opponent can't carry the old fight.
	@Test
	public void aClearedGroupKeepsNoAwayMember()
	{
		final FightGroup.Member member = group.join(1, "Boss", true, 0);
		group.despawned(member, false);
		assertNotNull(group.awayByName("Boss"));

		group.clear();
		assertNull(group.awayByName("Boss"));
		assertFalse(group.isAliveMember(1, "Boss"));
	}

	private static Health overhead(int ratio, int scale)
	{
		return new Health(ratio, scale, false, 450, false);
	}

	private static HealthReader.Reading overheadReading(int ratio, int scale)
	{
		return new HealthReader.Reading(HealthReader.Source.OVERHEAD, overhead(ratio, scale));
	}

	private static Health gameBar(int health, int max)
	{
		return new Health(health, max, true, max, false);
	}

	private static void assertReading(FightGroup.Member member, int ratio, int scale, boolean exact, Integer maxHealth)
	{
		assertEquals(ratio, member.ratio);
		assertEquals(scale, member.scale);
		assertEquals(exact, member.exact);
		assertEquals(maxHealth, member.maxHealth);
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static com.ghordrin.bosshealthbar.tracking.FightTimer.DEATH_TICKS;
import static com.ghordrin.bosshealthbar.tracking.FightTimer.NO_TICK;
import static com.ghordrin.bosshealthbar.tracking.FightTimer.SWAP_TICKS;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import org.junit.Test;

public class FightTimerTest
{
	private final FightTimer timer = new FightTimer(new DebugLog(null));

	@Test
	public void formatsMinutesAndSeconds()
	{
		assertEquals("0:00", FightTimer.format(0, false));
		assertEquals("0:00", FightTimer.format(1, false));
		assertEquals("0:01", FightTimer.format(2, false));
		assertEquals("0:59", FightTimer.format(99, false));
		assertEquals("1:00", FightTimer.format(100, false));
		assertEquals("1:23", FightTimer.format(139, false));
		assertEquals("59:59", FightTimer.format(5999, false));
	}

	@Test
	public void formatsHoursFromAnHour()
	{
		assertEquals("1:00:00", FightTimer.format(6000, false));
		assertEquals("1:05:09", FightTimer.format(6515, false));
		assertEquals("12:34:56", FightTimer.format(75494, false));
	}

	@Test
	public void preciseTimingAddsTheHundredthsTheGameShows()
	{
		assertEquals("0:00.00", FightTimer.format(0, true));
		assertEquals("0:00.60", FightTimer.format(1, true));
		assertEquals("0:01.20", FightTimer.format(2, true));
		assertEquals("0:59.40", FightTimer.format(99, true));
		assertEquals("1:00.00", FightTimer.format(100, true));
		assertEquals("1:00:00.00", FightTimer.format(6000, true));
	}

	@Test
	public void elapsedStopsAtTheEndTick()
	{
		assertEquals(NO_TICK, FightTimer.elapsedTicks(NO_TICK, NO_TICK, 50));
		assertEquals(40, FightTimer.elapsedTicks(10, NO_TICK, 50));
		assertEquals(20, FightTimer.elapsedTicks(10, 30, 50));
	}

	@Test
	public void anyNpcCarriesOnAnUndefeatedFight()
	{
		assertTrue(FightTimer.keepsCounting(true, false, false, NO_TICK, 100));
		assertFalse(FightTimer.keepsCounting(true, false, true, NO_TICK, 100));
		assertFalse(FightTimer.keepsCounting(false, false, false, NO_TICK, 100));
	}

	@Test
	public void anotherNpcOnlyCarriesOnShortlyAfterTheLastOneWentAway()
	{
		assertTrue(FightTimer.keepsCounting(true, false, false, 100, 100 + SWAP_TICKS));
		assertFalse(FightTimer.keepsCounting(true, false, false, 100, 101 + SWAP_TICKS));
	}

	@Test
	public void anAliveMemberOfTheFightCarriesItOnWhateverHappenedBefore()
	{
		assertTrue(FightTimer.keepsCounting(true, true, true, NO_TICK, 100));
		assertTrue(FightTimer.keepsCounting(true, true, false, 100, 500 + SWAP_TICKS));
		assertTrue(FightTimer.keepsCounting(true, true, true, 100, 500 + SWAP_TICKS));
		assertFalse(FightTimer.keepsCounting(false, true, false, NO_TICK, 100));
	}

	@Test
	public void showsNothingUntilTheFightStarts()
	{
		timer.opponentChanged(false, false, NO_TICK, 10);
		timer.onGameTick(true, false, NO_TICK, 11);
		assertNull(timer.getText());
	}

	@Test
	public void readsTheTimeOutOfEveryWordingTheGameUses()
	{
		assertEquals(154, FightTimer.reportedTicks("Fight duration: 1:32.40. Personal best: 0:31.80"));
		assertEquals(106, FightTimer.reportedTicks("Fight duration: 1:03.60 (new personal best)"));
		assertEquals(105, FightTimer.reportedTicks(
			"Wave 'The Maiden of Sugadinti' (Entry Mode) complete!Duration: 1:03.00 Total: 1:03.00"));
		assertEquals(3129, FightTimer.reportedTicks("Challenge duration: <col=ff0000>31:17</col>"));
