package com.ghordrin.bosshealthbar.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.tracking.HealthReader.Reading;
import com.ghordrin.bosshealthbar.tracking.HealthReader.Source;
import com.ghordrin.bosshealthbar.data.Health;
import org.junit.Test;

public class HealthReaderTest
{
	private static Reading gameBar(int health, int max)
	{
		return new Reading(Source.GAME_BAR, new Health(health, max, true, max, false));
	}

	private static Reading raidBar(int health, int max)
	{
		return new Reading(Source.RAID_BAR, new Health(health, max, false, 900, false));
	}

	private static Reading overhead(int ratio, int scale)
	{
		return new Reading(Source.OVERHEAD, new Health(ratio, scale, false, 450, false));
	}

	// One tick at a time, as the tracker and the fight group run it.
	private static final class Opponent
	{
		final boolean npc;
		final HealthReader.DownState state = new HealthReader.DownState();
		boolean down;
		boolean defeated;
		boolean revived;
		int tick;

		Opponent(boolean npc)
		{
			this.npc = npc;
		}

		Opponent tick(Reading reading, boolean dead, boolean attackable)
		{
			state.update(reading, dead, npc, attackable, ++tick, null, null, null);
			down = state.down;
			defeated = state.defeated;
			revived = state.takeRevived();
			return this;
		}
	}

	@Test
	public void staysDownUntilBackUp()
	{
		assertTrue(HealthReader.stillDown(false, true, false));
		assertTrue(HealthReader.stillDown(true, false, false));
		assertFalse(HealthReader.stillDown(true, false, true));
		assertTrue(HealthReader.stillDown(true, true, true));
		assertFalse(HealthReader.stillDown(false, false, false));
	}

	@Test
	public void aBossBarAboveZeroWinsOverIsDead()
	{
		assertFalse(HealthReader.isDown(gameBar(200, 450), true, true, true));
		assertFalse(HealthReader.isDown(raidBar(5, 600), true, true, true));
		assertTrue(HealthReader.isDown(overhead(0, 30), true, true, true));
		assertTrue(HealthReader.isDown(null, true, true, true));
	}

	@Test
	public void aBossBarAtZeroIsDown()
	{
		assertTrue(HealthReader.isDown(gameBar(0, 450), false, true, true));
		assertFalse(HealthReader.isDown(gameBar(1, 450), false, true, true));
		assertTrue(HealthReader.isDown(raidBar(0, 600), false, true, true));
		assertFalse(HealthReader.isDown(raidBar(5, 600), false, true, true));
	}

	@Test
	public void anOverheadZeroWithoutIsDeadIsNotDownButADeathFormAtOneIs()
	{
		assertFalse(HealthReader.isDown(overhead(0, 30), false, true, true));
		assertTrue(HealthReader.isDown(overhead(1, 60), false, true, false));
		assertFalse(HealthReader.isDown(overhead(1, 60), false, true, true));
		assertFalse(HealthReader.isDown(overhead(1, 60), false, false, false));
		assertFalse(HealthReader.isDown(null, false, true, false));
	}

	@Test
	public void aBossBarRefillingIsBackUp()
	{
		assertTrue(HealthReader.isBackUp(gameBar(1, 450), false, false));
		assertTrue(HealthReader.isBackUp(raidBar(3, 600), true, false));
		assertFalse(HealthReader.isBackUp(gameBar(0, 450), false, true));
	}

	@Test
	public void theOverheadBarIsBackUpOnceAttackableWithHealthToSpare()
	{
		assertTrue(HealthReader.isBackUp(overhead(2, 30), false, true));
		assertFalse(HealthReader.isBackUp(overhead(1, 30), false, true));
		assertFalse(HealthReader.isBackUp(overhead(20, 30), false, false));
		assertFalse(HealthReader.isBackUp(overhead(20, 30), true, true));
		assertFalse(HealthReader.isBackUp(null, false, true));
	}

	@Test
	public void unfightableSinceCountsFromTheFirstTickDownAndUnattackable()
	{
		assertEquals(FightTimer.NO_TICK, HealthReader.unfightableSince(false, false, FightTimer.NO_TICK, 5));
		assertEquals(FightTimer.NO_TICK, HealthReader.unfightableSince(true, true, 4, 5));
		assertEquals(5, HealthReader.unfightableSince(true, false, FightTimer.NO_TICK, 5));
		assertEquals(4, HealthReader.unfightableSince(true, false, 4, 5));
		assertFalse(HealthReader.isDefeated(true, true, 5, 5));
		assertTrue(HealthReader.isDefeated(true, true, 5, 6));
		assertFalse(HealthReader.isDefeated(false, true, 5, 6));
	}

	@Test
	public void healingFromZeroIsDownButNeverDefeated()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(overhead(10, 30), false, true);
		assertFalse(boss.down);
		boss.tick(overhead(0, 30), true, true);
		assertTrue(boss.down);
		for (int i = 0; i < 9; i++)
		{
			boss.tick(overhead(0, 30), true, true);
			assertFalse(boss.defeated);
		}
		boss.tick(overhead(12, 30), false, true);
		assertFalse(boss.down);
		assertFalse(boss.defeated);
	}

	@Test
	public void aDeathFormIsDefeatedAfterTwoUnattackableTicks()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(overhead(3, 60), false, true);
		boss.tick(overhead(1, 60), false, false);
		assertTrue(boss.down);
		assertFalse(boss.defeated);
		boss.tick(overhead(1, 60), false, false);
		assertTrue(boss.defeated);
	}

	@Test
	public void aBossBarAtZeroThatRefillsWhileUnattackableIsBackUp()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(gameBar(40, 450), false, true);
		boss.tick(gameBar(0, 450), false, false);
		assertTrue(boss.down);
		assertFalse(boss.defeated);
		boss.tick(gameBar(450, 450), false, false);
		assertFalse(boss.down);
		assertFalse(boss.defeated);
		// The kill was never confirmed, so this is the same fight carrying on.
		assertFalse(boss.revived);
	}

	@Test
	public void aConfirmedDefeatIsFinalAndHealthComingBackStartsTheNextLife()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(overhead(3, 60), false, true);
		boss.tick(overhead(1, 60), false, false);
		boss.tick(overhead(1, 60), false, false);
		assertTrue(boss.defeated);
		assertFalse(boss.revived);

		// Down with nothing left to read, as when it turns into a form without a bar: the kill still counts.
		for (int i = 0; i < FightTimer.SWAP_TICKS; i++)
		{
			boss.tick(null, false, false);
			assertTrue(boss.down);
			assertTrue(boss.defeated);
			assertFalse(boss.revived);
		}

		boss.tick(overhead(60, 60), false, true);
		assertFalse(boss.down);
		assertFalse(boss.defeated);
		assertTrue(boss.revived);

		// Reported once, and the new life starts undefeated.
		boss.tick(overhead(55, 60), false, true);
		assertFalse(boss.defeated);
		assertFalse(boss.revived);
	}

	@Test
	public void beingAttackableAgainWhileStillAtZeroWasNeverAKill()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(overhead(3, 60), false, true);
		boss.tick(overhead(1, 60), false, false);
		boss.tick(overhead(1, 60), false, false);
		assertTrue(boss.defeated);

		// Still down, but it can be fought again, so it never died and the bar comes back.
		boss.tick(overhead(1, 60), false, true);
		assertTrue(boss.down);
		assertFalse(boss.defeated);
		assertFalse(boss.revived);

		boss.tick(overhead(40, 60), false, true);
		assertFalse(boss.down);
		assertFalse(boss.revived);
	}

	@Test
	public void aShortDownIsAnotherPhaseAndNotTheNextOne()
	{
		assertFalse(HealthReader.isRevived(FightTimer.NO_TICK, 100));
		assertFalse(HealthReader.isRevived(100 - FightTimer.SWAP_TICKS, 100));
		assertTrue(HealthReader.isRevived(99 - FightTimer.SWAP_TICKS, 100));

		final Opponent phased = new Opponent(true);
		phased.tick(gameBar(40, 450), false, true);
		phased.tick(gameBar(0, 450), false, false);
		phased.tick(gameBar(450, 450), false, false);
		assertFalse(phased.revived);

		// Long enough to confirm a kill, but back for its next phase within the gap a phase change takes.
		final Opponent confirmed = new Opponent(true);
		confirmed.tick(gameBar(40, 450), false, true);
		for (int i = 0; i < FightTimer.SWAP_TICKS; i++)
		{
			confirmed.tick(gameBar(0, 450), false, false);
		}
		assertTrue(confirmed.defeated);
		confirmed.tick(gameBar(450, 450), false, false);
		assertFalse(confirmed.down);
		assertFalse(confirmed.defeated);
		assertFalse(confirmed.revived);
	}

	@Test
	public void clearingForgetsAConfirmedDefeat()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(overhead(0, 30), true, false);
		boss.tick(overhead(0, 30), true, false);
		assertTrue(boss.defeated);

		boss.state.clear();
		assertFalse(boss.state.down);
		assertFalse(boss.state.defeated);
		assertFalse(boss.state.takeRevived());

		boss.tick(overhead(30, 30), false, true);
		assertFalse(boss.revived);
	}

	@Test
	public void aBossBarAtZeroThenAnUnattackableFormIsDefeated()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(gameBar(40, 450), false, true);
		boss.tick(gameBar(0, 450), false, true);
		assertTrue(boss.down);
		assertFalse(boss.defeated);
		boss.tick(gameBar(0, 450), false, false);
		assertFalse(boss.defeated);
		boss.tick(gameBar(0, 450), false, false);
		assertTrue(boss.defeated);
	}

	@Test
	public void anOverheadZeroWithoutIsDeadIsNotDown()
	{
		final Opponent boss = new Opponent(true);
		boss.tick(overhead(0, 30), false, false);
		boss.tick(overhead(0, 30), false, false);
		assertFalse(boss.down);
		assertFalse(boss.defeated);
	}

	@Test
	public void aPlayerAtZeroIsDefeatedAtOnce()
	{
		final Opponent player = new Opponent(false);
		player.tick(overhead(0, 30), true, false);
		assertTrue(player.defeated);
	}

	@Test
	public void theWatchOnlyFiresWhenSomethingThatMattersChanges()
	{
		final HealthReader.Watch watch = new HealthReader.Watch();
		assertTrue(watch.changed(overhead(20, 30), false, false, true, 7));
		assertFalse(watch.changed(overhead(15, 30), false, false, true, 7));
		assertTrue(watch.changed(overhead(1, 30), false, false, true, 7));
		assertTrue(watch.changed(overhead(0, 30), false, false, true, 7));
		assertTrue(watch.changed(overhead(0, 30), false, true, true, 7));
		assertTrue(watch.changed(overhead(0, 30), false, true, false, 7));
		assertTrue(watch.changed(overhead(0, 30), false, true, false, 8));
		assertTrue(watch.changed(gameBar(0, 450), false, true, false, 8));
		assertTrue(watch.changed(null, false, true, false, 8));
		assertFalse(watch.changed(null, false, true, false, 8));
		watch.clear();
		assertTrue(watch.changed(null, false, true, false, 8));
	}

	@Test
	public void anOverheadBarWithNoValueIsNoReadingAndGetsItsOwnLogLine()
	{
		assertTrue(HealthReader.hasNoValue(-1, 60));
		assertFalse(HealthReader.hasNoValue(0, 60));
		assertFalse(HealthReader.hasNoValue(-1, -1));

		final HealthReader.Watch watch = new HealthReader.Watch();
		assertTrue(watch.changed(overhead(20, 60), false, false, true, 7));
		assertTrue(watch.changed(null, true, false, true, 7));
		assertFalse(watch.changed(null, true, false, true, 7));
		assertTrue(watch.changed(null, false, false, true, 7));
	}

	@Test
	public void describesWhereTheReadingCameFrom()
	{
		assertEquals("game boss bar at 300/450", HealthReader.describe(gameBar(300, 450)));
		assertEquals("raid boss bar at 0/600", HealthReader.describe(raidBar(0, 600)));
		assertEquals("overhead bar at 12/30", HealthReader.describe(overhead(12, 30)));
		assertEquals("no reading", HealthReader.describe(null));
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static com.ghordrin.bosshealthbar.tracking.OpponentTracker.DespawnOutcome.DEFEATED;
import static com.ghordrin.bosshealthbar.tracking.OpponentTracker.DespawnOutcome.LEFT;
import static com.ghordrin.bosshealthbar.tracking.OpponentTracker.DespawnOutcome.OUT_OF_SIGHT;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import net.runelite.api.HitsplatID;
import org.junit.Test;

public class OpponentTrackerTest
{
	private static final long DELAY = 5000;

	@Test
	public void staysWhileStillInteracting()
	{
		assertFalse(OpponentTracker.isQuietFor(0, 0, 0, true, 100_000, DELAY));
	}

	@Test
	public void hidesOnceTheDelayHasPassedSinceInteractionStopped()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 0, 0, true, 15_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 0, 0, true, 15_001, DELAY));
	}

	@Test
	public void aHitTakenRestartsTheDelay()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 14_000, 0, true, 18_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 14_000, 0, true, 19_001, DELAY));
	}

	@Test
	public void aHitOnTheOpponentRestartsTheDelay()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 0, 16_000, true, 21_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 0, 16_000, true, 21_001, DELAY));
	}

	@Test
	public void theLatestHitCounts()
	{
		assertFalse(OpponentTracker.isQuietFor(10_000, 17_000, 13_000, true, 22_000, DELAY));
		assertTrue(OpponentTracker.isQuietFor(10_000, 17_000, 13_000, true, 22_001, DELAY));
	}

	@Test
	public void hitsBeforeInteractionStoppedDoNotExtendTheDelay()
	{
		assertTrue(OpponentTracker.isQuietFor(10_000, 2_000, 3_000, true, 15_001, DELAY));
	}

	@Test
	public void hitsAreIgnoredWhenTheOpponentIsNotNearby()
	{
		assertTrue(OpponentTracker.isQuietFor(10_000, 14_000, 14_500, false, 15_001, DELAY));
	}

	@Test
	public void damageAndBlocksCount()
	{
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.DAMAGE_ME));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.DAMAGE_OTHER));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.DAMAGE_ME_POISE));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.BLOCK_ME));
		assertTrue(OpponentTracker.isCombatHit(HitsplatID.BLOCK_OTHER));
	}

	@Test
	public void damageOverTimeAndHealsDoNotCount()
	{
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.POISON));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.VENOM));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.BURN));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.BLEED));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.DOOM));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.CORRUPTION));
		assertFalse(OpponentTracker.isCombatHit(HitsplatID.HEAL));
	}

	@Test
	public void aConfirmedDefeatIsAKillWhereverItDespawns()
	{
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(true, false, false, 5, -1, false));
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(true, false, false, 40, -1, false));
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(true, true, true, 40, -1, false));
	}

	@Test
	public void anUnconfirmedZeroIsOnlyAKillInView()
	{
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(false, true, false, 14, -1, false));
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(false, true, false, -1, -1, false));
		assertEquals(OUT_OF_SIGHT, OpponentTracker.despawnOutcome(false, true, false, 15, -1, false));
		assertEquals(LEFT, OpponentTracker.despawnOutcome(false, true, true, 15, -1, false));
	}

	@Test
	public void withoutAZeroItWentOutOfSightOrLeft()
	{
		assertEquals(LEFT, OpponentTracker.despawnOutcome(false, false, false, 14, -1, false));
		assertEquals(OUT_OF_SIGHT, OpponentTracker.despawnOutcome(false, false, false, 15, -1, false));
		assertEquals(LEFT, OpponentTracker.despawnOutcome(false, false, true, 30, -1, false));
	}

	@Test
	public void anExactZeroFarAwayIsAKillAndNotOutOfSight()
	{
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(false, false, false, 20, 0, true));
		assertEquals(DEFEATED, OpponentTracker.despawnOutcome(false, true, false, 20, 0, true));
	}

	@Test
	public void aLastReadingAboveZeroFarAwayIsOutOfSight()
	{
		assertEquals(OUT_OF_SIGHT, OpponentTracker.despawnOutcome(false, false, false, 20, 20, true));
		assertEquals(OUT_OF_SIGHT, OpponentTracker.despawnOutcome(false, false, false, 20, 1, true));
	}

	@Test
	public void anOverheadZeroFarAwayIsOutOfSight()
	{
		assertEquals(OUT_OF_SIGHT, OpponentTracker.despawnOutcome(false, true, false, 20, 0, false));
		assertEquals(OUT_OF_SIGHT, OpponentTracker.despawnOutcome(false, false, false, 20, 0, false));
	}

	// Dying while the opponent reads 0 isn't a kill, however exact that reading was.
	@Test
	public void anExactZeroIsStillNotAKillWhenThePlayerDied()
	{
		assertEquals(LEFT, OpponentTracker.despawnOutcome(false, true, true, 20, 0, true));
		assertEquals(LEFT, OpponentTracker.despawnOutcome(false, false, true, 20, 0, true));
	}

	@Test
	public void aNewLifeStartsTheFightOverAndLeavesTheOldGroupBehind()
	{
		final FightTimer timer = new FightTimer(new DebugLog(null));
		final FightGroup group = new FightGroup(null, new DebugLog(null));
		timer.opponentChanged(false, false, FightTimer.NO_TICK, 0);
		timer.onHit(0);
		group.join(1, "Boss", true, 0);
		group.join(2, "Minion", false, 20);
		timer.onGameTick(true, true, FightTimer.NO_TICK, 600);
		assertEquals("6:00", timer.getText());
		final int fight = group.id();

		OpponentTracker.newLife(timer, group, null, true, 650);
		assertEquals("0:00", timer.getText());
		assertNotEquals(fight, group.id());
		assertEquals(0, group.size());

		timer.onGameTick(true, false, FightTimer.NO_TICK, 700);
		assertEquals("0:30", timer.getText());
	}

	@Test
	public void anOpponentThePlayerGoesForNearbyStartsTheFight()
	{
		assertTrue(OpponentTracker.startsFight(true, true, false, false, 0));
		assertTrue(OpponentTracker.startsFight(true, true, false, false, 15));
		assertFalse(OpponentTracker.startsFight(true, true, false, false, 16));
		assertFalse(OpponentTracker.startsFight(true, true, false, false, -1));
		assertFalse(OpponentTracker.startsFight(true, true, true, false, 0));
		assertFalse(OpponentTracker.startsFight(true, false, false, false, 0));
	}

	// An opponent only picked up because a game bar follows it, with the player not going for it.
	@Test
	public void anOpponentThePlayerIsNotGoingForDoesNotStartTheFight()
	{
		assertFalse(OpponentTracker.startsFight(false, true, false, false, 0));
	}

	// Walking within range of one that is already down, such as another player's kill, is not a fight.
	@Test
	public void anOpponentWithNoHealthLeftDoesNotStartTheFight()
	{
		assertFalse(OpponentTracker.startsFight(true, true, false, true, 0));
	}

	// Without a scene load, or without a point to compare with, there is nothing to tell.
	@Test
	public void aMoveWithoutASampledSceneLoadIsNotLeavingTheArea()
	{
		assertFalse(OpponentTracker.leftArea(false, 0, 3200, 3200, false, 0, 2500, 2500, false));
	}

	@Test
	public void aSceneLoadThatDoesNotMoveThePlayerIsNotLeavingTheArea()
	{
		assertFalse(OpponentTracker.leftArea(true, 0, 3200, 3200, false, 0, 3200, 3200, false));
		assertFalse(OpponentTracker.leftArea(true, 0, 3200, 3200, false, 0, 3214, 3200, false));
	}

	@Test
	public void aSceneLoadThatEndsSomewhereElseIsLeavingTheArea()
	{
		assertTrue(OpponentTracker.leftArea(true, 0, 3200, 3200, false, 0, 3215, 3200, false));
		assertTrue(OpponentTracker.leftArea(true, 0, 3200, 3200, false, 0, 3200, 3215, false));
		assertTrue(OpponentTracker.leftArea(true, 0, 3200, 3200, false, 1, 3200, 3200, false));
		assertTrue(OpponentTracker.leftArea(true, 0, 3200, 3200, false, 0, 3200, 3200, true));
	}

	@Test
	public void theFirstSampleHasNothingToCompareWith()
	{
		final OpponentTracker.Area area = new OpponentTracker.Area();
		area.sceneLoading();
		assertFalse(area.take(true, 0, 3200, 3200, false));
	}

	@Test
	public void aSceneLoadIsTakenOnce()
	{
		final OpponentTracker.Area area = new OpponentTracker.Area();
		area.take(false, 0, 3200, 3200, false);
		area.sceneLoading();
		assertTrue(area.take(false, 0, 3300, 3300, false));
		assertFalse(area.take(false, 0, 3400, 3400, false));
	}

	// Arriving somewhere may not be at the destination yet, so the sample is kept for the next tick to decide.
	@Test
	public void aStayOnArrivalKeepsTheSample()
	{
		final OpponentTracker.Area area = new OpponentTracker.Area();
		area.take(false, 0, 3200, 3200, false);
		area.sceneLoading();
		assertFalse(area.take(true, 0, 3200, 3200, false));
		assertTrue(area.take(false, 0, 3300, 3300, false));
	}

	@Test
	public void aMoveWithoutASceneLoadIsTakenAsStaying()
	{
		final OpponentTracker.Area area = new OpponentTracker.Area();
		area.take(false, 0, 3200, 3200, false);
		assertFalse(area.take(false, 1, 2500, 2500, true));
	}

	@Test
	public void clearingStartsOver()
	{
		final OpponentTracker.Area area = new OpponentTracker.Area();
		area.take(false, 0, 3200, 3200, false);
		area.sceneLoading();
		area.clear();
		assertFalse(area.take(false, 0, 3300, 3300, false));
	}

	// A boss mechanic, a ladder or a door can move the player mid-fight, which reloads the scene with the fight still on.
	@Test
	public void aFightWithItsOpponentStillHereIsNotForgotten()
	{
		assertFalse(OpponentTracker.forgetsFight(true, true));
		assertTrue(OpponentTracker.forgetsFight(true, false));
		assertFalse(OpponentTracker.forgetsFight(false, false));
	}

	@Test
	public void nearnessIsJustTheDistance()
	{
		assertTrue(OpponentTracker.isNearby(0));
		assertTrue(OpponentTracker.isNearby(15));
		assertFalse(OpponentTracker.isNearby(16));
		assertFalse(OpponentTracker.isNearby(-1));
	}
}

package com.ghordrin.bosshealthbar.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;

public class SuperiorTrackerTest
{
	private static SuperiorTracker.Spawn<String> known(String npc)
	{
		return new SuperiorTracker.Spawn<>(npc, true, false);
	}

	private static SuperiorTracker.Spawn<String> eligible(String npc)
	{
		return new SuperiorTracker.Spawn<>(npc, false, true);
	}

	private static SuperiorTracker.Spawn<String> ineligible(String npc)
	{
		return new SuperiorTracker.Spawn<>(npc, false, false);
	}

	@Test
	public void knownSuperiorsAreRecognisedById()
	{
		assertTrue(SuperiorTracker.isKnownSuperior(NpcID.SUPERIOR_ABYSSAL_DEMON));
		assertTrue(SuperiorTracker.isKnownSuperior(NpcID.SUPERIOR_GARGOYLE_DEAD));
		assertTrue(SuperiorTracker.isKnownSuperior(NpcID.LEAGUE_SUPERIOR_HYDRA));
		assertTrue(SuperiorTracker.isKnownSuperior(NpcID.DEADMAN_BREACH_SUPERIOR_DARK_BEAST));
		assertTrue(SuperiorTracker.isKnownSuperior(NpcID.SUPERIOR_VENATOR));
	}

	@Test
	public void thrallsDeathSpawnsAndQuestMonstersAreNotSuperiors()
	{
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.ARCEUUS_THRALL_GHOST_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.ARCEUUS_THRALL_SKELETON_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.ARCEUUS_THRALL_ZOMBIE_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.THRALL_IMP_MAGIC_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.THRALL_IMP_RANGED_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.THRALL_IMP_MELEE_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.SUPERIOR_NECHRYAEL_MELEE_SPAWN));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.SUPERIOR_NECHRYAEL_MAGIC_SPAWN));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.VIKINGEXILE_BASILISK_SUPERIOR));
		assertFalse(SuperiorTracker.isKnownSuperior(NpcID.SLAYER_ABYSSAL));
	}

	@Test
	public void aKnownSuperiorTakesTheMessageOverACloserSpawn()
	{
		final SuperiorTracker.Match<String> match = SuperiorTracker.match(Arrays.asList(eligible("closer"), known("superior")));
		assertTrue(match.isDecided());
		assertNull(match.getSuperior());
	}

	@Test
	public void oneUnknownCandidateIsMarked()
	{
		final SuperiorTracker.Match<String> match = SuperiorTracker.match(Arrays.asList(ineligible("far"), eligible("new")));
		assertTrue(match.isDecided());
		assertEquals("new", match.getSuperior());
	}

	@Test
	public void twoCandidatesMarkNone()
	{
		final SuperiorTracker.Match<String> match = SuperiorTracker.match(Arrays.asList(eligible("a"), eligible("b")));
		assertTrue(match.isDecided());
		assertNull(match.getSuperior());
	}

	@Test
	public void withoutCandidatesTheMessageKeepsWaiting()
	{
		assertFalse(SuperiorTracker.match(Collections.<SuperiorTracker.Spawn<String>>emptyList()).isDecided());
		assertFalse(SuperiorTracker.match(Collections.singletonList(ineligible("dead"))).isDecided());
	}
}
